/* 令和7年委員会データ（自動生成・分割ファイル） */
window.SHINAGAWA_DB.years.r07.committeeSessions.push(...[{"id":"r07-20250924-6","meetingId":"r07-cm09","date":"2025年9月24日","dateIso":"2025-09-24","committee":"区民委員会","time":"午前１０時００分～午後 ０時２４分","status":"正式会議録","sourceType":"formal","overview":"区民委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を35件整理しています。","topics":[{"id":"topic-01","title":"品川区区民保養所のあり方検討会における検討結果","agenda":"品川区区民保養所のあり方検討会における検討結果","exchanges":[{"speaker":"おぎの委員","kind":"質問","question":"光林荘のほうをお伺いしたいのですけれども、日光でなければいけないとか、そういうことというのはあるのでしょうか。１８ページで、ほかの区ではいろいろなところに行っているようですが、やはり日光がいいという希望は教育委員会から出ているのか尋ねました。","respondent":"平原地域活動課長","answer":"教育委員会事務局の気持ちというところで説明があったところなのですが、日光のポテンシャル、そういったことでやっぱりほかには替えられない。そういったところも含めまして、やはり日光の活用というのが一番望ましいと、そういう声があったところです。","id":"exchange-001"},{"speaker":"おぎの委員","kind":"質問","question":"確かに日光を推しているということは分かりました。もし、都や国の助成で何とかなったりとか、そういったものの模索というのはできるのか尋ねました。","respondent":"平原地域活動課長","answer":"まだ区としての方針が出ていない状況ですので、そこまで具体的な検討が進んでいるものではございませんけれども、あまり詳細まで把握していないところです。","id":"exchange-002"},{"speaker":"おぎの委員","kind":"意見","question":"やはりそこが一番悩ましいところではあるのですが、経営が少しは軽くなるかと思いますので、いろいろな角度で検討してほしいと求めました。一点、トコジラミで今年はお休みしていたところは、別のところに行かれたのでしたかとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-003"},{"speaker":"高橋（伸）委員","kind":"質問","question":"やはり横ばいという形で、一般のお客様だと日光なのだけれども、温泉がないではないですか。今やっているかどうなのか分からないのだけれども、まず区政協力委員の方たちが伊東市まで行かれる町会・自治会というのは、今でもありますか。","respondent":"平原地域活動課長","answer":"品川荘の町会・自治会の利用ですが、委員ご指摘のとおり、コロナ禍を経て、かなり減ったというのは事実ですが、今でも全くなくなったというわけではございませんで、町会単位というようなところでは、何町会かは実施していると聞いているところです。","id":"exchange-004"},{"speaker":"高橋（伸）委員","kind":"質問","question":"近隣区の大田区だと、指定保養施設がたしか３か所あるのですよね。もっと広がり方を１回やってみて、それからまた検討するというのも私はありなのかなと思っているのですが、その辺のご見解をお伺いしたいと思います。","respondent":"平原地域活動課長","answer":"お声としては何回も行ったことがあるというような声を聞いているところでございまして、一定のそういう方々がいらっしゃるものだと考えています。","id":"exchange-005"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"ありがとうございました。今後どうするかもあれですけれども、区民の方に分かりやすく丁寧に説明をして、今後のあり方を検討してほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-006"},{"speaker":"こしば委員","kind":"質問・要望","question":"対話でのサウンディング調査は４社ということですけれども、この時点で、もう既に例のトコジラミの件というのは把握されていたのか。８月５日に発表があったかなと思うのですけれども、この資料を見る限りでは出ていなかったので、そのあたりを教えていただきたい。","respondent":"平原地域活動課長","answer":"サウンディング調査に応募いただきました４社からは、トコジラミの件については特段の意見はございませんでした。今まさに起きている事案というよりは、そういう視点でのご意見を頂戴したところですので、今のところについてというようなお話はなかったところです。","id":"exchange-007"},{"speaker":"こんの委員","kind":"提案","question":"どういった業種の会社だったのかというところが１点と、どういうふうに、その流れも確認をさせてください。区民の方が、そうしたことでご利用されていた方も結構いたかなというのをお聞きすると、こうした提案という角度もどう考えるのかなとの意見を述べました。","respondent":"平原地域活動課長","answer":"そういったところも含めて、今後しっかり検討していかなければならないと思ってあります。今回の保養所としての結論だけではなくて、その先のことも考えた上で参考になるものと考えたところです。","id":"exchange-008"},{"speaker":"こんの委員","kind":"質問","question":"調査ですから、していただくわけですけれども、結果が出てくるのは１１月ぐらいでしたでしょうか。でこの保養所自体をどうするかというところの連携で、その辺の決め方というのでしょうか、説明を求めました。","respondent":"平原地域活動課長","answer":"今回の検討会の事務局体制といったところでも、あくまで保養所というような点で我々がメインに立っております。私どもは進めていく中でも教育委員会としっかりと連携といいましょうか、教育委員会も一緒にやっているとご理解賜ればと考えています。","id":"exchange-009"},{"speaker":"こんの委員","kind":"質問・要望","question":"それをどういう形で残すのか、学校施設といったところは引き続き連携を取っていただきながら、その方向を見いだしていただけたらなと思います。要望です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-010"},{"speaker":"せらく委員","kind":"質問・要望","question":"ただ、区民の方のさまざまな受け止めがあると思いますので、今後しっかり聞いていただきたいなと考えています。この光林荘と品川荘は指定管理者が同じだったと記憶しているのですけれども、指定管理期間というのは、いつに指定されているのか尋ねました。","respondent":"平原地域活動課長","answer":"両施設ですけれども、指定管理方式ではなくて、公有財産の無償貸付け方式による独自運営ということでやらせていただいております。無償貸付契約期間は、令和９年度末の令和１０年３月３１日までということになってあります。","id":"exchange-011"}]},{"id":"topic-02","title":"こみゅにてぃぷらざ八潮における東京ベイｅＳＧプロジェクト 先行プロジェクトの実施","agenda":"こみゅにてぃぷらざ八潮における東京ベイｅＳＧプロジェクト 先行プロジェクトの実施","exchanges":[{"speaker":"おぎの委員","kind":"質問","question":"私から１点だけ、実証実験の段階ということですが、これはいつまでとか、今後の実証実験の予定とか。期限等はあるのか尋ねました。","respondent":"今井八潮まちづくり担当課長","answer":"こちらは、こちらの中で予算を受けて民間企業が実施するものというスキームになっております。東京ベイｅＳＧプロジェクトの補助期限は、令和８年度末ということになっております。","id":"exchange-012"},{"speaker":"おぎの委員","kind":"質問・要望","question":"誰でも利用できるようなスペースを作ってほしい」という意見が出ておりましたが、まさにこれから八潮の出番かなと思っています。最後は要望です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-013"}]},{"id":"topic-03","title":"臨海斎場における増築基本設計の中間報告等","agenda":"臨海斎場における増築基本設計の中間報告等","exchanges":[{"speaker":"こしば委員","kind":"質問","question":"スケジュールを見ますと、待合室の内装改修が１１月頃から始まるということですが、その間は待合室は確保するのかというのがわからなかった。その間、車で待つようなケースもあったりするそうなのですけれども、その辺の場所の確保をお聞きしたいと思います。","respondent":"築山戸籍住民課長","answer":"改修についてなのですけれども、年数回施設の点検や補修のために休館日を設けておりまして、その休館日で対応するというように聞いております。式場としても転用するようにいたしますので、改修等の期間、既存の火葬待合室の利用には影響がないと聞いております。","id":"exchange-014"},{"speaker":"こしば委員","kind":"質問・要望","question":"そこに建てるということで、駐車場が減ったとしても、それほど影響はないだろうというところですね。動線も含めて確保をお願いしたいと思うのですけれども、そのあたりについてお考えがありましたら教えてほしいと求めました。","respondent":"築山戸籍住民課長","answer":"一方、現状としまして、家族葬が増えているということで、タクシー等の乗り合いでいらっしゃる方が多いというような状況です。こういったことを踏まえまして、今後組織区とともにアクセスについてどうするかというのは、引き続き考えていきたいと考えています。","id":"exchange-015"},{"speaker":"こしば委員","kind":"質問・要望","question":"南側に駐車場が１６４台分ありますので、今後、その辺のアクセスは決して悪くはないかなと思います。区民の方で少し遠く感じる方にとっても利用しやすいよう、ぜひ周知のほうもしてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-016"},{"speaker":"こんの委員","kind":"質問・要望","question":"２０分ぐらいですかね、ここのお部屋も結構待ちだったりして、稼働率がというお声も聞いています。ここは非常に活用されるケースが多いと考えられるので、その辺はどんなふうにお考えなのか、この機会なので確認をさせていただきたい。","respondent":"築山戸籍住民課長","answer":"左側に写真が載っているのですけれども、こちらは部屋が分かれておりませんので、プライベート空間ではありません。今回新たな増築によって、この辺のプライベート空間を作ることによってお別れの場を設けるというような形で計画されているものです。","id":"exchange-017"},{"speaker":"こんの委員","kind":"質問・要望","question":"今の時代はどうなのかなと思ってお聞きしたのですが、やっぱり確かにご家族の方がくつろげるお部屋というのは必要かなと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-018"},{"speaker":"高橋（伸）委員","kind":"質問","question":"私、ちょっとイメージが湧かなくて、既存の臨海斎場にひさしがあるではないですか。そこを。","respondent":"築山戸籍住民課長","answer":"１階がピロティになりますので、このピロティ部分の上が２階平面図の多目的室や待合室が設置される場所になるという配置計画になっております。２階部分が出っ張るようなイメージになりますけれども、構造上は、これについては問題がないというところで聞いております。","id":"exchange-019"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"それと、５番の火葬炉計画で、超大型炉が１基と。ちょっと分からなかったのですが、今でも臨海斎場に超大型炉が１基あるということでいいのですか、説明を求めました。","respondent":"築山戸籍住民課長","answer":"臨海斎場にはありませんので、都内で超大型炉を設置しているのが、そちらのほうで火葬するというようなことで調整を図っているところです。","id":"exchange-020"},{"speaker":"こんの委員","kind":"意見","question":"そうすると、町屋にしか今はない。５区の臨海斎場にもう１基できるということは、臨海斎場を使うということは、５区以外はないということでいいのですよねとの意見を述べました。","respondent":"築山戸籍住民課長","answer":"ただし、金額を組織区内料金と組織区外料金で分けておりますので、そういったところで差別化が図られております。組織区の方が利用しやすいように、そういった値段設定とさせていただいているところです。","id":"exchange-021"},{"speaker":"こんの委員","kind":"質問","question":"都内に２つしかそれがないとなると、その増えていくところも考えていかなければいけないのだな、捉えていかなければいけないのだなと思ったのです。その辺は大丈夫なのですよねといっても、見通しは今つかないと思うのですが、そういうのも対応していくという葬儀場になるということですかね。","respondent":"築山戸籍住民課長","answer":"この令和１２年度の計画によりまして火葬炉も増えますし、式場も増えます。保冷庫も増えますので、そういったところで今後の火葬需要に応えていくということで臨海斎場のほうから聞いているところです。","id":"exchange-022"},{"speaker":"せらく委員","kind":"質問・要望","question":"細かいことかもしれないのですけれども、私からは４の平面計画から質問させてほしいと求めました。増築する部分は３階建てになっておりまして、３階の平面図を見ると、それ以外の部分はどのようなスペースになるのか尋ねました。","respondent":"築山戸籍住民課長","answer":"３階のスペースは、主に設備を置くスペースになっておりますので、機械室になるかと思います。１階、機械設置のスペースを確保できなかったというところで、３階のほうでそこの分は対応すると聞いております。","id":"exchange-023"},{"speaker":"せらく委員","kind":"意見","question":"機械設備の置き場ということで、特に少し座って休めるスペースができるとかではなく、ただ置き場のフロアをつくっていくと、そんなところですねとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-024"}]},{"id":"topic-04","title":"令和６年度指定管理者による管理に対するモニタリング・評価の結果","agenda":"令和６年度指定管理者による管理に対するモニタリング・評価の結果","exchanges":[{"speaker":"こんの委員","kind":"質問","question":"これはやっぱり難しいのですかね。その辺、改善の視点に書かれていることを、もう少し詳しく教えてもらえますか尋ねました。","respondent":"大森文化観光戦略課長","answer":"もっと大きな施設でありますきゅりあんに関しましても、積極的に入れていきたいなということで考えております。受託者側のほうから、なるべく会場に足を運ぶ回数を少なくして、お支払いや予約等をしていただけるように取り組んでいきたいと考えております。","id":"exchange-025"},{"speaker":"こんの委員","kind":"質問","question":"単純にはいかない、業務改善が必要というところなのですかね。その辺のところ、区民の方にご理解をいただける、何が詰まっていてできないのかというところをもう少しご説明いただけますか尋ねました。","respondent":"大森文化観光戦略課長","answer":"少し改良しているというようなところをデジタル推進課などと個別にやり取りをしているというところがあります。出さないというところで帳票の様式などの変更や、導入の検討を申し入れるというようなことをしていかないといけないのかなと考えています。","id":"exchange-026"},{"speaker":"こんの委員","kind":"質問","question":"状況が少し分かりました。早く帳票にというか、いわゆる借りる側の方に出す明細というところですかね、引き続きご努力をお願いしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-027"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"それともう一点なのですけれども、戸越体育館はもう築３０年以上たっていますよね。大雨のときは雨漏りがなかったのかどうか、そこを教えていただきたい。","respondent":"守屋スポーツ推進課長","answer":"先日の大雨のときには、特に雨漏り等の被害はなかったということで確認しております。","id":"exchange-028"},{"speaker":"高橋（伸）委員","kind":"確認","question":"確認できました。これからも運営を。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-029"},{"speaker":"おぎの委員","kind":"質問・要望","question":"私のほうからも何点か。合同防災訓練を行っていたというお話があったと思うのですが、どのような防災訓練が行われているのか少しお聞かせほしいと求めました。","respondent":"大森文化観光戦略課長","answer":"きゅりあんで行われている合同防災訓練は、大ホールで講演会をしております。コンサートを再開するという流れの訓練を、お客様とともに、施設側が行ったという経過です。","id":"exchange-030"},{"speaker":"おぎの委員","kind":"質問","question":"その訓練というのは、ホールの管理をお任せしているところと、区の職員がされたということか尋ねました。","respondent":"大森文化観光戦略課長","answer":"区の職員は見に行った参加者側のほうになりまして、やっているのは受託者側と防災センターで詰めている従業員ですとか、そういったところの協力を得ながら誘導するというような流れになります。","id":"exchange-031"},{"speaker":"おぎの委員","kind":"提案","question":"一緒になって、実際にどういう動きで避難させたらいいかというレクチャー等も、少し丁寧な説明をしていただけたらいいなと思います。やり方等に関して、私も何かいい提案があったら提案させていただきたいなと思いますが、どうか尋ねました。","respondent":"大森文化観光戦略課長","answer":"１か月よりも前に、そういった説明ができるかどうかということを、公演に呼んでいただくというようなことをしてまいりたいと思います。","id":"exchange-032"}]},{"id":"topic-05","title":"品川歴史館開館４０周年記念特別展「御殿山」","agenda":"品川歴史館開館４０周年記念特別展「御殿山」","exchanges":[{"speaker":"こんの委員","kind":"質問","question":"１１月３日を予定されているということなのですが、この御殿山の展示をされているさなかに１日だけ、１日５回ということです。使い方はやっぱりイベント、その協会の人たちがいないと使えない感じなのですか、どんな感じなのか尋ねました。","respondent":"大森文化観光戦略課長","answer":"ある程度お願いする団体等が必要になってくるのかなと思いますので、その辺りは検討させていただければと思います。こちらの特別展の招待券を区民委員会の皆様と正副議長に郵送する予定ですので、ぜひ皆様期間中にお時間があれば来ていただければと思います。","id":"exchange-033"},{"speaker":"こんの委員","kind":"意見","question":"イベントはイベントだけではなく、全ての施設の中身を連動して使えるようなこともあると来館者も増えていくのではないかなと考えたところですとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-034"}]},{"id":"topic-06","title":"その他","agenda":"その他","exchanges":[{"speaker":"藤原副委員長","kind":"質問","question":"客引きの条例が品川区の中にある。その関係性において、地域で言うと五反田ですが、どういうふうな状況になっているのかということを改めてお伺いしたいと思います。","respondent":"澤邉生活安全担当課長","answer":"品川区内の客引きの状況等について、改めてご説明します。よって、副委員長がご懸念のような町会の方が客引きを直接排除するようなものではないと考えておりますので、今後ともよろしくお願いいたします。","id":"exchange-035"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/414982?Template=document&Id=7171#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=6&TermStart=2025-01-01&TermEnd=2025-12-31"}],"sourceMeta":{"pages":0,"characters":43712,"voices":116}},{"id":"r07-20250924-7","meetingId":"r07-cm09","date":"2025年9月24日","dateIso":"2025-09-24","committee":"厚生委員会","time":"午前１０時００分～午後 ２時３４分","status":"正式会議録","sourceType":"formal","overview":"厚生委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を51件整理しています。","topics":[{"id":"topic-01","title":"小山台住宅等跡地複合施設の開設時期の変更","agenda":"小山台住宅等跡地複合施設の開設時期の変更","exchanges":[{"speaker":"鈴木委員","kind":"質問・要望","question":"高齢者のほうはかなり早い段階で決まったと思うのですけれども、これだけ早く決めるという理由についても伺いたいと思います。もう一つ、地域に対しての説明会というのはどういうスケジュールで行うのか、その点についてもお願いします。","respondent":"東野福祉計画課長、佐藤障害者施策推進課長","answer":"東京都との補助協議を早い段階で進めないといけない、予定している事業者の意見を取り入れていきたいというところで、早めに選定したものです。追ってこの委員会でもご説明したいと思うのですけれども、現在… 障害者施設の事業者につきましては、今、福祉計画課長からあったとおりではありますが、時期としましては、令和８年度の前半、４月以降なるべく早めにというところで、事業者の公募を予定しています。","id":"exchange-001"},{"speaker":"鈴木委員","kind":"質問","question":"障害者のほうは、補助金の協議だったりとか、東京都との高齢者と同じような形でのやり取りというのはないということなのでしょうか。どういう中身の設計にするのかというあたりは、その点、伺いたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-002"},{"speaker":"鈴木委員","kind":"確認","question":"そういうのは令和８年の前半での公募で、そうすると、決定するのはいつぐらいになるのか。それで、細かいところというのは後からでも間に合うというスケジュール感でいいのか、その確認だけお願いします。","respondent":"佐藤障害者施策推進課長","answer":"先ほど申し上げた令和８年度前半から事業者の公募を行いまして、中頃、予定としましては組んでいるところです。一般的に各種別の障害者のサービスのメニューが一定程度想定できるものは見込んで設計をしているところになりますので、そういう意味では。","id":"exchange-003"},{"speaker":"鈴木委員","kind":"質問・要望","question":"いろいろ就労継続支援Ｂ型の中身というのはあると思うのですけれども、ぜひ公募して、事業者の意見が本当にしっかりと取り入れられるようなスケジュール感も含めて、進めていただきたいということでお願いをしておきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-004"},{"speaker":"吉田委員","kind":"質問・要望","question":"でも、建物としては複合と理解しているのですけれども、まるっきり別々に工事が行われるということなのでしょうか。複合施設なわけですから、教えていただきたいのですけれども、いかがか尋ねました。","respondent":"佐藤障害者施策推進課長","answer":"工事等の詳細も出てきましたので、開設時期というところで改めて詳細、月のところまでお示しさせていただいたです。４月以降、なるべく速やかに公募を行いまして、８月９月１０月あたりには事業者選定が終えられればというところで予定しています。","id":"exchange-005"},{"speaker":"吉田委員","kind":"提案","question":"私は、もちろん事業者の提案も、やはりどういう事業を望んでいる方が多いかというのが大事なのではないかと。近隣というか、利用を予定されている方たちのご要望と、その辺についてはどのようにお考えか尋ねました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-006"},{"speaker":"あくつ委員","kind":"質問・要望","question":"委員の要望であるとか、今回の複合施設については何でも質問していいということになってしまうので、各委員の思いは多分あると思うのです。長くなりました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-007"},{"speaker":"吉田委員","kind":"提案","question":"ただ、どうしても複合施設で提案されているので、複合施設で片方の機能だけの開設時期が延びるという報告は、多くの人が違和感を持ちます。そういうことだと理解ができますので、複合で打ち出した以上、そのように計画を進めていただきたいという趣旨で質問させていただきましたとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-008"},{"speaker":"あくつ委員","kind":"質問・要望","question":"もう少し詳細に教えていただきたいのですが、施設の開設準備期間を勘案すると、年度末の開設は人材確保が困難であるためと。普通に見れば、人材確保が困難だというのはどういう意味なのか、もう少し詳細なご説明をお願いしたいと思います。","respondent":"東野福祉計画課長","answer":"３月の時点で、まだ卒業もしていないというようなところもありますので、そこの時点で新たに人を確保するというのが難しい。その点をやはり勘案しないと、事業というのはうまくいかないのだろうということで、４月、もう１か月延ばしたというような実情です。","id":"exchange-009"},{"speaker":"大倉委員","kind":"質問・要望","question":"あそこの小山台２丁目のところの道路を考えると、道の幅とかの課題もあるのかというところで、教えてほしいと求めました。３か月工期延長ということで、費用とかというのは３か月延長するとどうなのかというのが分かれば、教えてほしいと求めました。","respondent":"東野福祉計画課長","answer":"それから、契約につきましては、今回の定例会でも提案をさせていただいているのですけれども、契約期間の延長も含めた形での契約を上程しています。ですから、３か月延びた分につきましても、その契約の中で全部入っているというようなものです。","id":"exchange-010"},{"speaker":"大倉委員","kind":"意見","question":"地域の交通渋滞が起きないようにとか、いろいろ配慮してそのように切り回しをされているのだと思いますが、その辺はぜひよろしくお願いします。工期の延期については、人件費を含めて契約ということで理解しましたとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-011"},{"speaker":"鈴木委員","kind":"質問・要望","question":"なぜ高齢者と障害者がそのようにずれているのか、今後いつどれくらいの時期にどうするのかという説明というのは厚生委員会に全くなかったのです。そういうところもしっかりと厚生委員会の中でも今後も説明をぜひしてほしいと求めましたけれども、その点だけ確認だけお願いしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-012"},{"speaker":"鈴木委員","kind":"質問","question":"そうですか。では、委員長によろしくお願いしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-013"}]},{"id":"topic-02","title":"品川区立八潮在宅サービスセンターの移転（予定）","agenda":"品川区立八潮在宅サービスセンターの移転（予定）","exchanges":[{"speaker":"あくつ委員","kind":"確認","question":"八潮が地元でもないということもあるのですが、これは何か福祉計画とか、そういったもので既に位置づけられていたものなのでしょうか。そこだけ気になったので、確認したいと求めました。","respondent":"東野福祉計画課長","answer":"障害者施設も入りますので、福祉の総合拠点施設ということでのＰＲを図っていきたいと。こちらにつきましては、今後、介護保険事業計画ですとか地域福祉計画の改定のときには、そういった表現をしていきたいと考えております。","id":"exchange-014"},{"speaker":"あくつ委員","kind":"質問","question":"分かりました。少し気になって質問しましたけれども、これから八潮にお住まいの方も含めて必要かと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-015"},{"speaker":"鈴木委員","kind":"質問","question":"３０名と書いてあるのですけれども、どちらなのかというのが１点なのですけれども、定員も３５名よりももっと増やしていくということになるのか。そこの点を説明するよう求めました。","respondent":"菅野高齢者福祉課長","answer":"こちらの資料で定員３０名となっておりますが、現在は３５名の定員ですので、どういうやり方がいいかというのは今後検討していきたいと思います。","id":"exchange-016"},{"speaker":"鈴木委員","kind":"質問・要望","question":"２か所しかデイサービスはないという状況なので、これから私はもっとやり方の充実をさせていく中で増やしていくことができるのではないかと。ぜひ地域の要望に応えられるような、そういう在宅サービスセンターに、デイサービスになるようにということでお願いしておきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-017"}]},{"id":"topic-03","title":"令和６年度指定管理者の管理に対するモニタリング・評価の結果","agenda":"令和６年度指定管理者の管理に対するモニタリング・評価の結果","exchanges":[{"speaker":"鈴木委員","kind":"質問・要望","question":"障害者の施設について伺いたいのですけれども、全体のところで、生活介護の中で生産活動がされている事業所というのは何か所ぐらいあるのか。どういう活動がされているのかというのは、モニタリングのチェック項目の中にも入るものなのかどうなのか、その点についてまず伺いたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-018"},{"speaker":"鈴木委員","kind":"質問・要望","question":"でも、されているのかどうなのか、生産活動が生活介護の中で位置づけられてされているのかというあたりを伺いたいと思いました。そこら辺のところはどういう状況になっているのかも伺いたいと思います。","respondent":"松山障害者支援課長","answer":"意欲の面というものを重視して取り組むものですので、そこの現場で必要な方に、何かマッチするものができないかということで作っているものです。","id":"exchange-019"},{"speaker":"鈴木委員","kind":"質問","question":"１.５対１という体制を取ったというのは、２対１から１.５対１にしたことによって、もし分かったら教えていただけたらと思います。","respondent":"松山障害者支援課長","answer":"１.５対１にしていただいたというのは非常にありがたく、かなり法人のほう、努力していただいたことです。","id":"exchange-020"},{"speaker":"鈴木委員","kind":"質問","question":"それで、かなり赤字も増えているということなのですけれども、これはなぜこんな状況になっているのかということを伺いたいと思います。今は現状、誰が利用して、利用状況というのはどれくらいになっているのかということについて伺いたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-021"},{"speaker":"あくつ委員","kind":"確認","question":"これ、レスパイトの皆さんとかは利用しにくいということは以前確認をさせていただいたことがあると思うのですけれども、ここについての区の認識と。以上、確認したいと求めました。","respondent":"松山障害者支援課長","answer":"レスパイトに対する区の認識ですが、出石のほうで児童のレスパイトのほうを対応してくださる方針であるということのお答えはいただいております。まだまだ周知はこれからですので、児童のレスパイトも少しずつ対応していきたいと考えています。","id":"exchange-022"},{"speaker":"吉田委員","kind":"質問・要望","question":"見解を伺いたいのですけれども、私はずっと求めてきて、やはり働く人への労務の視点というのはどうしても必要なのではないかと思います。今まで求めていたのは、業務改善の取組が奏功し、超過勤務を２０％削減することができたという。","respondent":"松山障害者支援課長","answer":"社会保険労務士による労働環境チェックですと、区全体で３年目に行うというところで決め事がありますので、それに従っているものです。","id":"exchange-023"},{"speaker":"吉田委員","kind":"質問・要望","question":"今後の要望としては、そういうところは、その視点を今後のモニタリングの中では入れてほしいと求めました。これは要望にとどめます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-024"},{"speaker":"やなぎさわ委員","kind":"質問","question":"これに関して、このモニタリングで、そのアンケート結果というのは参考にされたりしているのでしょうか。お伺いします。","respondent":"菅野高齢者福祉課長","answer":"区のほうで通知を受けて、特別養護老人ホームについては３年に１回、グループホームは毎年ということで第三者評価を実施しています。次の指定の方針だとか、今回のこのモニタリング評価や指定については、こちらのほうは加味していないとお答えします。","id":"exchange-025"},{"speaker":"やなぎさわ委員","kind":"質問・要望","question":"利用者や家族の状況や要望を聞かれているかで、「いいえ」が１００％というところで、かなり偏っていたと。この３つは令和６年に行われている直近のものでして、もう一回この中にしっかり入れていただきたいと思うのですけれども、いかがか尋ねました。","respondent":"菅野高齢者福祉課長","answer":"特別養護老人ホームの方、特に要介護３以上ということになるので、対面で調査をする難しさもあるのかとも感じています。今後、基準に沿った形ではありますけれども、より効果的な評価となるような内容の検証もしていかなくてはいけないかとは感じているところです。","id":"exchange-026"},{"speaker":"やなぎさわ委員","kind":"質問","question":"推測ですけれども、思うので、やはりこの辺の偏りというのは少し調査する必要もあると思うので、ぜひこの点を留意してほしいと求めました。少し指標というか、中に入れてほしいと思うのですけれども、その点はいかがか尋ねました。","respondent":"菅野高齢者福祉課長","answer":"特別養護老人ホームの幾つかのところにおいては、処遇改善加算がＩの一番いい条件のものが取れていないというところもあります。こういったモニタリング等を通して、少し改善されるようにということで、各施設には働きかけをしてまいりたいと思います。","id":"exchange-027"},{"speaker":"やなぎさわ委員","kind":"確認","question":"個別の細かいところでお伺いしたいのですけれども、平塚橋特別養護老人ホームのを確認させてもらったところ、人件費が３億４,０００万円あって。２割ぐらいは派遣職員のお金に消えているというところになっていると思うのですけれども、なかなか難しいと思うのですが、その辺はいかがか尋ねました。","respondent":"菅野高齢者福祉課長","answer":"少しでも受入れを拡充するというか、多くの方を受け入れてもらうというところで、すごく苦慮している状況なのだと思います。常勤の職員がいて、区として支援できることも何か支援をしていきながら改善していけるように努めていきたいと思います。","id":"exchange-028"},{"speaker":"やなぎさわ委員","kind":"確認","question":"東京都の公表情報を確認したのですが、職員の退職者数が２３名で、入職者数が１２名と書いてあるのです。入職者が１２名、公表情報の数字を確認されているのかどうかも含めてお伺いしたいと思うのですけれども、いかがか尋ねました。","respondent":"菅野高齢者福祉課長","answer":"立地もいいのか、かなり他業種に転職される方とか、そういったことが多いというのは以前聞いたことがあります。そういった中で採用活動をして、稼働率を上げるという努力をしていただいていることなのかと捉えております。","id":"exchange-029"},{"speaker":"やなぎさわ委員","kind":"質問・要望","question":"区としても注視してほしいと思いますし、やはり少しこの辺も注視してほしいと求めましたので、その辺はぜひ注目してほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-030"},{"speaker":"鈴木委員","kind":"質問・要望","question":"高齢者のほうも質問させていただきたいのですけれども、高齢者のデイサービスが８か所なのですが、あとは全部マイナスという状況になっているのです。９割を超えているところもほとんどという状況ですし、そういう中でなぜこういう、区としてどう捉えられているのか。","respondent":"菅野高齢者福祉課長","answer":"少し要支援の方が増えてしまったという実情もありますし、あと、在宅サービスセンターの要支援の方の割合も変わっていくのかと思っているところです。","id":"exchange-031"},{"speaker":"鈴木委員","kind":"意見","question":"本当に介護の構造的な問題というのが、このモニタリングにも様々表れていると思います。そういう中で、実態に合わせた介護度の認定が出るようにというところでは、ぜひ今後の改善をしていただきますようにお願いをしておきたいと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-032"},{"speaker":"やなぎさわ委員","kind":"質問・要望","question":"就労継続支援Ｂ型の公園清掃の際に、熱中症予防でアイスベストを着用したという記載がありました。そういったものを積極的に区としても推奨してほしいとか、モニタリングにも反映していただきたいと思うのですけれども、その点いかがか尋ねました。","respondent":"松山障害者支援課長","answer":"就労継続支援Ｂ型等の公園清掃の熱中症予防対策なのですけれども、何らかの工夫ができないかというのは各施設にお願いしているところです。ファンつきというのも検討はされたのですが、今後も工夫していただいて、区としても積極的に働きかけを行ってまいります。","id":"exchange-033"}]},{"id":"topic-04","title":"旧リボン旗の台店跡地における障害者就労体験事業の実施","agenda":"旧リボン旗の台店跡地における障害者就労体験事業の実施","exchanges":[{"speaker":"あくつ委員","kind":"提案","question":"冒頭、議会でもご提案をしたりもしていたのですけれども、どのような形になるのかというところを幾つか伺います。今お伺いしたことについて、現段階で決まっているところを説明するよう求めました。","respondent":"松山障害者支援課長","answer":"ああいったようなノウハウをいただきまして、今回のこちらの就労体験事業の実施場所には、それを取り入れた形で活かさせていただきました。既に分身ロボットを配置しておりまして、ただ、パイロットのほうはまだこれから募集するという段取りになっております。","id":"exchange-034"},{"speaker":"あくつ委員","kind":"質問・要望","question":"品川区では、まずはそこで体験ができるということと、これからパイロットが募集されるということで確認しました。実はオリィ研究所に私この８月に行って、吉藤オリィさん、本名が健太朗さんですかね。","respondent":"松山障害者支援課長","answer":"分身ロボットＯｒｉＨｉｍｅを活用した超短時間雇用、それ以外の超短時間雇用も、こちらの就労体験事業のほうでは行っていただく予定でございました。今後、委員おっしゃられるような様々なお仕事があると思いますので、可能性を広げていきたいと考えています。","id":"exchange-035"},{"speaker":"吉田委員","kind":"質問・要望","question":"どうしても偏るので、共同受注の窓口というのを求めたので、共同受注のやり方という。失礼ながら思ってしまうのですけれども、その点は確認されているか、それぞれ伺います。","respondent":"松山障害者支援課長","answer":"１つ大口の菓子を納入してくださいという企業からのオーダーが来ましたら、複数箇所の施設に分けて受注の調整をするといったところがこちらです。新たに職員をこの事業用につけていただくということで、常勤３人、非常勤３人の体制で行う予定です。","id":"exchange-036"},{"speaker":"吉田委員","kind":"質問・要望","question":"これは要望になってしまうかもしれないのですけれども、私が質問したときに求めた共同受注というのは、作業があるではないですか。そういうイメージだったのですけれども、そういう共同受注はしないのでしょうかというのも伺いたいと思います。","respondent":"松山障害者支援課長","answer":"かなり区内の障害者施設ですとか、そういった意味では、いろいろな連携を取ってイベントを盛り上げるということも考えております。既に受注先との連携もできておりますので、企業等に開拓をしていただきたいということがございまして、そちらのほうもやっていただく予定です。","id":"exchange-037"},{"speaker":"吉田委員","kind":"質問・要望","question":"それぞれの生活介護の施設に仕事を集めてくるというのまで求めるのは難しいから、以前、一般質問で共同受注の仕組みが欲しいというのを伺いました。それぞれにふさわしい仕事が受注できるような共同受注の窓口を目指していただきたいのですけれども、区の方針としては、その辺いかがか尋ねました。","respondent":"松山障害者支援課長","answer":"共同受注窓口に対する区の方針についてです。品川区には初めてこちらに共同受注窓口を設置することになりましたので、今後、就労継続支援Ａ型や就労継続支援Ｂ型の方々にもきちんとした作業が。","id":"exchange-038"},{"speaker":"吉田委員","kind":"質問・要望","question":"何か封入作業とか、お仕事はありませんかと。ただ、こういう区として共同受注の仕組みができるというのは本当に歓迎しておりますので、先を見据えてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-039"},{"speaker":"鈴木委員","kind":"質問・要望","question":"その他９４０万円ということであるのですけれども、１点、確認をさせてほしいと求めました。その点についても説明を求めました。","respondent":"松山障害者支援課長","answer":"そちらを活用する予定です。障害者就労支援センターの登録者数が年々増加しておりまして、考えられる原因としましては、企業での就労経験がない。","id":"exchange-040"},{"speaker":"鈴木委員","kind":"質問","question":"げんきが１者だけ応募したということになると思うのですが、そういう応募が１者しかないという理由、そこら辺は区としてどう考えられているのか伺います。","respondent":"松山障害者支援課長","answer":"現地見学もしていただいたのですけれども、３事業所から辞退があり、最終的には１事業所について審査をしたという結果になります。なお、辞退の理由は、人材確保が難しいという理由でございました。","id":"exchange-041"}]},{"id":"topic-05","title":"令和８年度分品川区立高齢者住宅（単身用）補欠登録者の募集","agenda":"令和８年度分品川区立高齢者住宅（単身用）補欠登録者の募集","exchanges":[{"speaker":"鈴木委員","kind":"質問","question":"高齢者住宅２１７戸ですけれども、令和６年の申請者数と、その中で入れた人数だけ説明を求めました。","respondent":"樫村高齢者地域支援課長","answer":"令和６年度の申込み状況ですけれども、６２名の方に申込みをいただきまして、うち１名が辞退をされました。つきまして、審査対象としては６１名の方が審査対象となっておりまして、入居された方につきましては、２８名の方が入居されたといったところです。","id":"exchange-042"},{"speaker":"鈴木委員","kind":"質問","question":"２８名というのは、大体２０名ぐらいが例年だったと思うのですけれども、分かったら説明を求めました。","respondent":"樫村高齢者地域支援課長","answer":"入居された方の内訳ですが、細かいところの数字はないのですけれども、基本的には名簿の登録順位としては、立ち退きの方を優先に点数自体が高くなりますので、立ち退きの方のほうが高いといった形になります。","id":"exchange-043"},{"speaker":"あくつ委員","kind":"質問","question":"ご説明のとおりだと思うのですけれども、１点だけ、前々からお聞きしたかったのですが、よくご紹介をするのですが、相談者の方に。これは保安上というのはどういうことを示して保安上というのを申請条件にされているのか、少し詳しく説明を求めました。","respondent":"樫村高齢者地域支援課長","answer":"保安上ですけれども、委員ご指摘のとおり、やはりセキュリティ面ですとか、そういったところも含んだ形での内容としています。","id":"exchange-044"},{"speaker":"あくつ委員","kind":"質問","question":"これは単身のあれでしょうから、これ以上多分質問してもなかなか、そこについては客観的な要件が必要ということなのですかね。そこだけ説明を求めました。","respondent":"樫村高齢者地域支援課長","answer":"職員と、委託している東京都宅地建物取引業協会の方と実際にご自宅に伺って、そういったところの状況を確認させていただいた上での審査という形になります。","id":"exchange-045"},{"speaker":"やなぎさわ委員","kind":"質問","question":"すみません。今の質問に関連するかもしれないのですけれども、今のここに住めないみたいな、そういった方は条件としては入る可能性はあるのか尋ねました。","respondent":"樫村高齢者地域支援課長","answer":"あくまでも優先順位をつけてということになりますので、その方がどの優先順位になるかというところはあれなのですけれども、そういった状況を聞き取った上での審査をするといったところです。","id":"exchange-046"}]},{"id":"topic-06","title":"議会閉会中継続審査調査事項","agenda":"議会閉会中継続審査調査事項","exchanges":[{"speaker":"あくつ委員","kind":"質問","question":"私のところに来ているのは、追加も含めて、非常に様々なことを本当に献身的にやっていただけたと考えています。例えば消毒に関して言えば、一体いつまでこれは受けていただけるのか、説明を求めました。","respondent":"赤木生活衛生課長","answer":"先日の９月２１日日曜日で電子申請自体は終了しておりまして、保健所の生活衛生課環境衛生担当で、個別に対応させていただいているところです。","id":"exchange-047"},{"speaker":"あくつ委員","kind":"質問・要望","question":"先週の末ですか、丁寧に対応していただきたいということ、がっかりしないような対応をぜひお願いしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-048"},{"speaker":"鈴木委員","kind":"質問・要望","question":"結構、地下駐車場だったり、そういうところもやっていただくということで確認させていただいていいでしょうか。それと、あとは、外壁みたいなところもぜひやっていただきたいというご要望もあったのですけれども、そこら辺のところに対してはいかがか尋ねました。","respondent":"赤木生活衛生課長","answer":"屋外の場所の消毒をご希望される方も一定数いると我々としても認識はしているのですけれども、今回、区内のかなり広範囲にわたって発生していると。まずは人が通常居住する場所、先ほど申し上げたような場所を優先的に実施するというところで業者には指示をしています。","id":"exchange-049"}]},{"id":"topic-07","title":"行政視察","agenda":"行政視察","exchanges":[{"speaker":"あくつ委員","kind":"確認","question":"今回のこの視察先というのが４か所、例えば、その辺りはどのようなコンセプトなのかというところを確認した上で行ったほうが有意義かと。質問をつくるにしても。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-050"},{"speaker":"あくつ委員","kind":"質問","question":"４か所行く中で、高齢社会に対する取組みたいなものが多かったので、今回はやはりそこがメインなのかと思いながら伺っておりました。分かりました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-051"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/238890?Template=document&Id=7169#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=7&TermStart=2025-01-01&TermEnd=2025-12-31"}],"sourceMeta":{"pages":0,"characters":67545,"voices":160}},{"id":"r07-20250924-8","meetingId":"r07-cm09","date":"2025年9月24日","dateIso":"2025-09-24","committee":"建設委員会","time":"午前１０時００分～午後 ２時０５分","status":"正式会議録","sourceType":"formal","overview":"建設委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を57件整理しています。","topics":[{"id":"topic-01","title":"第３６回東京都道路整備事業推進大会","agenda":"第３６回東京都道路整備事業推進大会","exchanges":[{"speaker":"安藤委員","kind":"質問・要望","question":"開催目的に広域化する交通混雑の緩和とあるのですが、この間、品川区内の交通混雑は悪化しているのか伺いたいと思います。それと、大会では、整備推進を求める道路の中に補助２９号線とか放射２号線などの特定整備路線は含まれているのか伺いたいと思います。","respondent":"高梨都市計画課長","answer":"道路整備には取り組んでいかなければいけないと認識しています。今回のこの道路整備事業推進大会の要求項目には含まれているものということで認識しています。","id":"exchange-001"},{"speaker":"安藤委員","kind":"質問・要望","question":"コミュニティーを壊す、反対の声も強いという特定整備路線の推進を求めるこの道路整備事業推進大会の趣旨に私、共産党は反対です。この場を借りて態度を表明させてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-002"},{"speaker":"中塚委員","kind":"質問・要望","question":"きっとあると思うのですけれども、この交通混雑の緩和というのはどの程度を目指しているのかをご説明ほしいと求めました。どういう大会決議が行われ、それを資料として引き続き頂きたいと思いますけれども、いかがか尋ねました。","respondent":"高梨都市計画課長","answer":"まだ東京都内の都市計画道路の整備率が６割程度といったところもありますので、そういったところを目指して、整備が必要であるという認識です。２つ目の決議文の情報提供等については、今後、考えさせていただきたいと思ってあります。","id":"exchange-003"},{"speaker":"中塚委員","kind":"質問・要望","question":"なぜならば、日常的に幹線道路を走っている方々に話を聞くと、昔の渋滞に比べて最近は都心に道路が減ってきたのだという話をよく伺うのです。そういう都市計画道路がいよいよ重点化されてくると、私自身は思っているのですけれども、区の見解を伺いたいと思います。","respondent":"高梨都市計画課長","answer":"平均的な速度が、例えば２０km／ｈ以下であるとかということで、定量的な指標はあります。そういった指標で、都内のどういったところで渋滞が発生しているのか等々は、東京都はじめ、様々調査が行われているものという認識です。","id":"exchange-004"},{"speaker":"中塚委員","kind":"提案","question":"平均時速２０km／ｈ以下。根拠になっているのが申合せ確認事項ということになりますので、議運の委員長に申合せ確認事項の改定をぜひ提案していただきたいとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-005"}]},{"id":"topic-02","title":"令和７年１１月都営住宅入居者募集","agenda":"令和７年１１月都営住宅入居者募集","exchanges":[{"speaker":"安藤委員","kind":"質問・要望","question":"品川区としてはこの制度をどう認識しているのか、あと検討したことがあるのでしょうかということを伺いたいと思います。改めて区営住宅の入居の際の連帯保証人も不要にすることを求めますが、そちらについてはいかがか尋ねました。","respondent":"川原住宅課長","answer":"引き続き研究・検証をして、今後の保証人の在り方を考えていきたいと思いますが、現時点においては今すぐやめるといった予定はございません。ただ、家賃がなかなか払いづらいといったご相談があった際には、引き続き、丁寧に対応しています。","id":"exchange-006"},{"speaker":"安藤委員","kind":"質問・要望","question":"人権の観点から、やはり住宅に困窮する若い方も含むモデル事業ということですので、研究してほしいと求めました。保証制度についても再検討していただきたいと、重ねてお願い申し上げます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-007"},{"speaker":"中塚委員","kind":"質問","question":"都営住宅入居者募集に関わって、区営住宅も同様なのか伺いたいのですけれども、都営住宅の家賃、また区営住宅の家賃はどのように決まっているのか。多分、全体的な仕組みはほぼ同じような感じなのかと思うのですけれども、家賃がどのように決まっているのかを伺いたいと思います。","respondent":"川原住宅課長","answer":"残念ながら、使用料決定等については区のほうは関与してございませんので、区営住宅についてでご説明させていただければと思います。","id":"exchange-008"},{"speaker":"中塚委員","kind":"質問","question":"仮に区営住宅の話でいうと、これを決めているのは条例なのですか、要綱なのですか。いろいろ私も伺ってはいるのですが、近傍家賃との関係で、最後にこれだけ一緒にご説明いただけたらと思います。","respondent":"川原住宅課長","answer":"２点目は区民住宅の近傍同種の家賃で、近年の家賃の値上げ等は影響を受けるのかですが、現在のところは値上げを考えてはおりません。令和２年に、引き続き現在の使用料で、区民住宅の提供は行っていきたいと考えているところです。","id":"exchange-009"}]},{"id":"topic-03","title":"令和６年度指定管理者による管理に対するモニタリング・評価","agenda":"令和６年度指定管理者による管理に対するモニタリング・評価","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"少し近傍民間物件と比べて、それぞれ間取りとか広さとか賃料というのはどうなのか、どう違うのかを少し最初に伺いたいと思います。総括のところに、職員が巡回頻度を上げてとあるのですけれども、これはどこら辺の住宅の誰を対象にどのような頻度で巡回しているのか説明を求めました。","respondent":"川原住宅課長","answer":"少し一概に申し上げることは難しいのですけれども、広い３ＬＤＫクラスの広い使用料のもので２０万円弱プラス管理費がかかるといったところです。維持管理経費が昨年より大きいところはといった理由ですが、こちら、令和６年度は外壁の改修が非常に多かったです。","id":"exchange-010"},{"speaker":"安藤委員","kind":"質問・要望","question":"要望に対してというところがありますが、どういう要望が寄せられているのか、どのように対応しているのか伺いたいと思います。こうした居住者からの意見とか要望がどれぐらいあったということを数として載せてほしいと思うのですけれども、いかがでしょうかと思います。","respondent":"川原住宅課長","answer":"ただ、現場にすぐに行っていただいて、細かく対応していただいているといったところは把握をしています。もしくはこういった形で、やはり現場に伺って個別対応しているケースが多いといったところであるかと思います。","id":"exchange-011"},{"speaker":"安藤委員","kind":"質問・要望","question":"入居者から得た主な意見や要望があると書いてあったもので、どういう相談が寄せられているものなのかなというそこだけ伺いたいと思います。そういうものの連携というのでしょうか、そこら辺というのはどうなっているのか。","respondent":"川原住宅課長、中西環境課長","answer":"どちらかというと、私が把握している限りでは個別の入居者の方のご相談が非常に多いです。上の方の音であるとか、振動であるとか、そういったところの細かいご意見をいただいたりといったところが非常にあると把握しています。３点目、環境課との連携といったところですが、環境課とエコルとごし指定管理者に関しましても、月に１度、毎月定例会を開催しています。","id":"exchange-012"},{"speaker":"安藤委員","kind":"確認","question":"エネルギー削減率９３.９％という数字が出ているのですが、これは当初の目標に照らしてどういう数字で、どのような評価をしているのでしょうか。短時間無料設定というのは、このときはモデル事業だったと思うのですが、現在は全ての駐輪場で導入されているのか確認したいと求めました。","respondent":"中西環境課長、山下交通安全担当課長","answer":"もNearly ＺＥＢの７５％をはるかに上回る数字が削減できているといったところでは、一定施設として効果的なのかと思ってあります。どういうふうな環境を整えていくかといったことは、適宜… １点目ですが、当日と定期のバランスを今後、変えていく予定かというところです。５駅８施設で行いましたところ、本年４月１日から全ての当日利用ができる駐輪場におきまして、２時間以内の無料設定を実施しています。","id":"exchange-013"},{"speaker":"安藤委員","kind":"質問・要望","question":"ですから、ぜひそういった公共施設でのさらなる活用といいますか、普及を進めていただくよう要望したいと思います。どういう意見が集まっているのかをちょっと伺いたいと思います。","respondent":"山下交通安全担当課長","answer":"配布枚数は７,０００枚に対して回答数が６０５枚、このうち回答率はウェブ回答が９７％、紙回答が３％となっております。このほか、あとは中には態度が悪い管理人がいるですとか、定期利用も電子マネーを使えるようにしてほしいとかいったお声を頂いているところです。","id":"exchange-014"},{"speaker":"ゆきた委員","kind":"質問","question":"私からは、住宅課のところだけお聞きしたいと思います。この括弧書きでエレベーターと表記されていないところには、エレベーターがついていないという認識で合っているのかお聞きしたいと思います。","respondent":"川原住宅課長","answer":"エレベーターありと表記がないところはエレベーターがない住宅という形になります。","id":"exchange-015"},{"speaker":"ゆきた委員","kind":"確認","question":"５階建てで、エレベーターがついていない荏原７丁目住宅などでお話を伺っているのですけれども、こちらも上り下りが大変だという声を伺っています。確かに西大井６丁目の区営住宅だと、困難なところもあるのだと思われますが、この課題についてどう捉えているのかお聞きできればと思います。","respondent":"川原住宅課長","answer":"この区営住宅が非常に古い時代に建てられた住宅でして、エレベーターが後から増設ができないような規制になってしまっているような状況です。","id":"exchange-016"},{"speaker":"ゆきた委員","kind":"質問","question":"もう１点で、区営住宅の建設年度が昭和４０年代のところが幾つかありますが、こういった建物は旧耐震基準で建てられた建築物だと思われます。一般的になされていると思われるのですけれども、これについてどういう対策をしてこられているのか、この点についてお聞きできればと思います。","respondent":"川原住宅課長","answer":"昭和４０年代に建築された住宅に対しては、耐震化の基準については全て満たしていることを確認しています。そのほか、そこは適切な維持管理というところで、計画的に修繕を引き続き実施して維持管理をしていきたいと考えています。","id":"exchange-017"}]},{"id":"topic-04","title":"第二戸越幹線整備工事（取水および空気抜き設備等整備）","agenda":"第二戸越幹線整備工事（取水および空気抜き設備等整備）","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"この第二戸越幹線整備工事の施工途中、９月１１日に短時間豪雨に見舞われてしまったわけなのです。今回の大雨による被害との関係が、これが完成した場合、どのような雨量に耐えられることになるのかを伺いたいと思います。","respondent":"関根河川下水道課長","answer":"ご説明申し上げたように、まだ施工中ということで、そういったものがまだ稼働してない中での豪雨あるいは浸水被害になると認識しています。１時間５０ミリを超える降雨に対しても浸水被害を軽減することができると認識をしています。","id":"exchange-018"},{"speaker":"安藤委員","kind":"確認","question":"少し確認なのですけれども、使ってはいたのだけれども、今回の雨では冠水してしまったということなのか。これが今回、全て完成すると、全部、目黒川でつながるということになると、改善をされるものなのか伺いたいと思います。","respondent":"関根河川下水道課長","answer":"これらに加えて、新たに目黒川に水を流すことができる管が新しく１本増えるという形になりますので、浸水害は改善されるものと認識しています。最後に戸越幹線はどこかということで、ご説明が不足していて申し訳ございませんでした。","id":"exchange-019"},{"speaker":"中塚委員","kind":"質問・要望","question":"建設委員会の報告にもなりますので、その辺の概要は冒頭、触れてもよかったのかと思いますので、そこを伺います。これだけの規模のものの空気抜きですから、どういう構造なのか、ご説明ほしいと求めました。","respondent":"関根河川下水道課長","answer":"続きまして、今後、こうしたご説明の際には冒頭にご説明させていただければと考えています。変更等、必要な人が容易に立ち入れないような場所に設置をする、安全上の工夫は行っていく予定です。","id":"exchange-020"},{"speaker":"中塚委員","kind":"質問・要望","question":"物すごい勢いで空気が出ていると怖いと思うのも当然だと思いますので、安全対策を十分に、しっかり進めてほしいと求めました。近隣の方からご意見があったら、丁寧に説明をしていただけたらと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-021"}]},{"id":"topic-05","title":"所管事務調査","agenda":"所管事務調査","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"区民避難所のほうに避難してきた場合の受入れのルールというのはどうなっているのか伺いたいと思います。復旧まで、期間はどれぐらいかかるのか、区としてはこれは把握しておられるのでしょうか、伺いたいと思います。","respondent":"羽鳥防災課長","answer":"首都直下地震の場合の被害想定といたしましては、エレベーター停止の台数が８８７件ということで数字が出ております。９５％を超えるエレベーターが発災後２日以内に復旧を完了したという過去の震災の情報がありますので、早い段階で復旧できるとは認識しています。","id":"exchange-022"},{"speaker":"安藤委員","kind":"質問","question":"ここら辺について、超高層マンションについてのエレベーター停止予測はしておくべきではありませんかと伺いたいと思います。そこについても２点目として伺いたいと思います。","respondent":"羽鳥防災課長","answer":"東京都も今後、被害想定の見直し等もあると思いますので、そういった動向も注視しながら見てまいりたいとは考えてあります。そういった動きの中で、築年数に応じて、きちんと管理されているかというところは、一定の担保がとれているのかと考えています。","id":"exchange-023"},{"speaker":"安藤委員","kind":"質問・要望","question":"エレベーターどうですか、実際どうなのですかということを、まずやってほしいと求めました。この２点について、もう一度お伺いしたいと思います。","respondent":"羽鳥防災課長、川原住宅課長","answer":"区といたしまして、しながわ防災学校等で管理組合・理事会向けのコースも実施しております。次の老朽化マンションへの課題ですが、これは各課と連携して、今後、対応について、話し合ってまいりたいと考えております。 住宅課で把握しているマンション管理支援事業といった一環からのご説明になります。老朽化に対する支援も防災課とも連携をしながら、相談にも細かく応じて、何ができるかというところは連携して考えていきたいと思います。","id":"exchange-024"},{"speaker":"安藤委員","kind":"質問・要望","question":"やはり再開発誘導を位置づけて、区が率先して、新たに超高層マンション建設を進めるというのは私はやはりやるべきではないなと。そして居住の住まいの権利を守るという立派な立場があるわけですから、私はそういった点で、この場を借りて改めて求めたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-025"},{"speaker":"中塚委員","kind":"質問・要望","question":"以前にも議論いたしましたように、感震ブレーカーの助成について、ぜひマンションも対象にしていただきたいということです。ぜひマンションにも感震ブレーカー、分電盤の設置助成の対象を広げていただきたいと改めて求めますけれども、いかがか尋ねました。","respondent":"遠藤防災体制整備担当課長","answer":"は在宅避難の感震ブレーカー設置に向けて、検討はしておるのですが、まずは家具転倒防止を進めていただくといったところです。こちらの動向を見ながら、区として在宅避難者に向けた感震ブレーカーの支援についてどのようにすればいいのかを検討していきたいと考えています。","id":"exchange-026"},{"speaker":"中塚委員","kind":"質問・要望","question":"ぜひ、マンションもぜひ対象にしていただきたいと改めて思いますが、いかがでしょうか。マンションも対象にすることは、緊急の課題だと私は思いますけれども、改めていかがか尋ねました。","respondent":"遠藤防災体制整備担当課長","answer":"そういったところで、まずマンション防災に関しては、一旦検討するというところで考えているところです。こちらのほうも注視しながら、マンション防災における感震ブレーカーの設置を今後、検討してまいりたいと考えております。","id":"exchange-027"},{"speaker":"中塚委員","kind":"質問・要望","question":"財源がかかることでありますので、国や都に十分な財源を求めていくことを改めて要望したいと思います。そのため、質問するのと、具体的な対策についても併せて伺いたいと思います。","respondent":"羽鳥防災課長","answer":"こちらは非常に大きな課題だという認識でございまして、マンション防災ハンドブックにも書かせていただいております。先日も開催されましたマンションの管理組合・理事会向けのしながわ防災学校のマンションコースでもその説明をしていたところです。","id":"exchange-028"},{"speaker":"中塚委員","kind":"質問・要望","question":"使用できるという確認が、管理会社が１軒１軒回ったにしても、首都直下型大震災のように一斉に起きる地震に対しては対象となる棟数が多いですから。少し１週間というのは、マンションにお住まいの方々に周知をすることが必要だと思いますけれども、改めて伺いたいと思います。","respondent":"羽鳥防災課長","answer":"区といたしましては、在宅避難の推奨、家庭内備蓄１週間分ということで、引き続き周知啓発に努めてまいりたいと思います。都も含めて、今後、対策が進められるように連携してまいりたいと考えています。","id":"exchange-029"},{"speaker":"中塚委員","kind":"質問・要望","question":"やはり８割の方がマンションなわけですから、こういう取組が始まっています、多くの支援もありますというニュースを発行する。この点いかがか尋ねました。","respondent":"羽鳥防災課長","answer":"マンションのマニュアルを作成して、それをさらに作成した上で地域とのつながり、訓練を実施するというところが最終目標ではないのかと考えています。周知啓発の手法をとるかというところは今後、検討しながら、しっかり評価してまいりたいと考えています。","id":"exchange-030"},{"speaker":"中塚委員","kind":"質問・要望","question":"延べでは把握しているということですが、ぜひここは思い切って、全てのマンション管理組合にアンケート調査をしていただきたい。それを力に周知や事業の規模も強化してほしいと求めましたが、最後にアンケートの件だけ、いかがか尋ねました。","respondent":"羽鳥防災課長","answer":"そういったところに対して、防災課として支援をしっかり届けていくというところが、大切になると考えます。３段階に分けて、きめ細やかな支援をやっていくという狙いがありますので、今年度は注力してまいりたいとは考えています。","id":"exchange-031"},{"speaker":"ゆきた委員","kind":"質問","question":"４の（３）のステップ３で、東京とどまるマンションでの成功事例とか、あるいは東京都内の成功事例とかあれば教えてほしいと求めました。品川区は他区に比べても件数が先行していますが、登録を促してきた現在までの取組があればお聞きできればと思います。","respondent":"羽鳥防災課長","answer":"ステップ３の取組を区の成功事例として、今後、新たに取組を展開してまいりたいと考えています。引き続き、マンション防災の取組の啓発に努めてまいりたいと考えています。","id":"exchange-032"},{"speaker":"ゆきた委員","kind":"質問","question":"町会、自治会などと連携して、合同の防災訓練を行う場合に、１００万円の全額補助もあります。ここについて、品川区でお考えが何かあれば、お聞きできればと思います。","respondent":"羽鳥防災課長","answer":"マニュアルを策定した上で、地域と連携した防災訓練を実施することで、ソフト対策は１つ基準をクリアすることができる。そういった支援も、区としても進めてまいりたいと考えています。","id":"exchange-033"},{"speaker":"ゆきた委員","kind":"質問","question":"東京とどまるマンションでのソフト面の対策で３日分の備蓄について、各住戸で供えればここは達成できるというところもあったと思います。発電機は最大１,５００万円、蓄電池は上限１,３１６万円の補助があることの周知も併せて、改めてこの辺についてお聞きできればと思います。","respondent":"羽鳥防災課長","answer":"今、お話がありましたとおり、マンション防災に関しまして、都で様々な取組を進めており、区も防災課以外の各課の様々な取組があります。そういったところをひとつ分かりやすくまとめて発信していくということは重要なことだと思いますので、今後、検討してまいります。","id":"exchange-034"},{"speaker":"ゆきた委員","kind":"質問","question":"品川区内でも東品川３丁目、４丁目では、町会員の９９％がマンション住人という状況もあります。今後、この在り方として何か最後にお聞きできればと思います。","respondent":"羽鳥防災課長","answer":"品川区といたしましては、防災区民組織が２００組織ありまして、これまでも訓練、会議等で活動していただいております。品川区内では地域の防災区民組織の方の活動が活発ですので、その活動を基に様々なマンション防災を含めて、支援は進めていければと考えています。","id":"exchange-035"}]},{"id":"topic-06","title":"行政視察","agenda":"行政視察","exchanges":[{"speaker":"中塚委員","kind":"質問・要望","question":"昨日、質問したとおりなのですけれども、羽田新ルートについての答弁で、国が示したルートに限定せずということだったのですが、国が示すルートに限定せずとした意図、理由、背景を質問させてほしいと求めました。","respondent":"高梨都市計画課長","answer":"本年中、いわゆる海上ルートの実現に資する方策など区民負担軽減につながる具体的な方策の提示とその実施を早期に行うよう求めたものです。","id":"exchange-036"},{"speaker":"中塚委員","kind":"質問・要望","question":"一貫して、私は、いわゆる今まで羽田空港を飛んでいた従来の海上ルートを求めてほしいと言ってきました。前回の８月２５日の質疑からも１カ月ぐらいたっておりますけれども、どこがどう新しいのか、もう少しご説明ほしいと求めました。","respondent":"高梨都市計画課長","answer":"態度につきましては、区民負担軽減につながる具体的な方策の提示とその実施を早期に行っていただきたいということを繰り返し求めてまいりました。それを実行していただきたいという態度につきましては、以前から継続して求めている態度であるところです。","id":"exchange-037"},{"speaker":"中塚委員","kind":"質問・要望","question":"区民負担の軽減を示してほしいということですけれども、区民負担の軽減を示す方策の１つに、海上ルートを求めていくというのが区の立場なのか。これを品川区として国に求めるのが、森澤区長の立場なのか、そこを伺いたいと思います。","respondent":"高梨都市計画課長","answer":"２つ目のルートについてですけれども、区は実際に飛行機が飛ぶルートについて、調査研究する機関ではございません。実績、知見を持ち合わせていないといったところは変わらず認識しています。","id":"exchange-038"},{"speaker":"中塚委員","kind":"質問・要望","question":"ただ、本会議で区民負担の軽減というところで、海からのルートを求めていく云々とご説明があったので、ここを改めて伺いたいと思います。７月３１日の区長が大臣に要望した中身なのか、要望した中身を少し解説したものなのか、そこもご説明ほしいと求めました。","respondent":"高梨都市計画課長","answer":"実施している固定化回避検討会で、国は海上ルートの実現に資する方策について、調査研究を実施すると言っております。そこはしっかりと検討してまいりたいというところと、国より早期に提示し、実施していただきたい。","id":"exchange-039"},{"speaker":"中塚委員","kind":"質問・要望","question":"当日、区長が大臣に話した中身と今回の一般質問答弁が違ったので、新たに説明したというか、解説したということですね。国への要望なのですけれども、品川区として国に求めているのか、ここをずばり伺いたいと思います。","respondent":"高梨都市計画課長","answer":"区といたしましては、具体的な使用滑走路やルートを指し示しているのではなく、海から離着陸するルートも含めて、品川区民の区民負担軽減につながる取組について、国へ求めてまいる考えです。","id":"exchange-040"},{"speaker":"中塚委員","kind":"提案","question":"なので、最後に改めて、ぜひ品川区として、国に対して従来の海上ルートに戻すよう要望していただきたいと改めて質問いたしますが、いかがでしょうか。そのことを品川区として国に求めてほしいと改めて要望いたしますけれども、いかがか尋ねました。","respondent":"高梨都市計画課長","answer":"区民の方々から日々、品川区上空を飛ぶ羽田新飛行ルート、お困りの声があるといったところは、区としても十分認識しています。指し示しているものではなく、品川区の区民の負担軽減に取り組む、１日も早く実現をしていただくといったところを国に対して求めてまいります。","id":"exchange-041"},{"speaker":"安藤委員","kind":"質問・要望","question":"少し伺いたいのですが、区長が求めた国のルートに限定せず海上ルートをということなのですけれども。元の海上ルートに戻すというのはもうこれは含まれているのではないのですかというところを伺いたいと思います。","respondent":"高梨都市計画課長","answer":"区としましては、具体的なルートを指し示しているものではなく、いずれにしても品川区民負担軽減に資する取組を進めていただきたいといった思いで、今回の答弁をさせていただいているということです。","id":"exchange-042"},{"speaker":"安藤委員","kind":"質問","question":"だから元の海上ルートに戻すということは当然含まれているのではないのですか、区長の答弁は。区長というか今回の区の答弁は、と思うのですけれども、いかがか尋ねました。","respondent":"高梨都市計画課長","answer":"繰り返しになりますけれども、具体的なルートを指し示しているものではございません。品川区民の負担軽減に向けた具体的な取組の提示と実施を、国に対して求めてまいりたいです。","id":"exchange-043"},{"speaker":"安藤委員","kind":"質問","question":"私たち共産党が伺ったのは、区長が何を要請したのですかという質問をしたので、それがずれていると私は困るのです。私はずれているとなるとおかしな話になってくると思うのですけれども、いかがか尋ねました。","respondent":"高梨都市計画課長","answer":"先ほどの答弁では、７月３１日の大臣面会の際に、そのような言葉では言っていないということで捉えたものです。実施するといったところは、７月３１日の大臣面会で求めていますし、今回の一般質問でも答弁させていただいたところです。","id":"exchange-044"},{"speaker":"安藤委員","kind":"質問・要望","question":"その言葉の中にはそういうことを区として求めた考えなのですということを表明したという、本会議ではそういうことなのでしょうか。そういうことでよろしいのでしょうか、解釈は。","respondent":"高梨都市計画課長","answer":"７月３１日に大臣面会で求めたことと、今回の一般質問で、区として態度を変えているといったところはございません。","id":"exchange-045"},{"speaker":"安藤委員","kind":"質問・要望","question":"変えていないということであれば、あの本会議答弁は何だったのかというと、言葉では言っていないけれども、区としては固定化回避検討会で検討している海上ルートに限定されない海上ルートというのを公式にあの場で国に求めたのですということを表明したということでよろしいか尋ねました。","respondent":"高梨都市計画課長","answer":"いずれの機会におきましても、区としましては品川区民の区民負担軽減につながる具体的な方策の提示と取組を早期に提示し、実施していただくように求めたいという態度については変わってございません。","id":"exchange-046"},{"speaker":"安藤委員","kind":"質問・要望","question":"そこにはとらわれない、限定しない海上ルートを求めたということを、品川区が国に７月３１日に伝えたと。改めて区民向けに少し発信していただきたいのですが、特にお願いしたいと思いますが、いかがか尋ねました。","respondent":"高梨都市計画課長","answer":"７月３１日の大臣面会については、ホームページ等で区民向けに発信をさせていただいているところです。ご提案の内容につきましても、今後、検討させていただいと思います。","id":"exchange-047"},{"speaker":"安藤委員","kind":"質問・要望","question":"やはり品川区の自治体、品川区区長を含めた品川区がどういう意見を言うか、メッセージを発するかというのは本当に大きな影響力を持ってきます。ですから、ぜひ検討をしていただきたいですし、これからもさらに踏み込んだ発言をどんどんしていってほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-048"},{"speaker":"安藤委員","kind":"質問","question":"９月１８日、こしば区議の一般質問の中で、コミュニティーバスの大崎ルートについても質問がありました。品川区からは令和８年度、そして現時点での検討内容などを教えていただけるところがあれば、ぜひ説明を求めました。","respondent":"櫻木地域交通政策課長","answer":"大崎地区につきましても、デマンド交通の実証運行の可能性について、令和８年の下半期を視野に入れて、検討を進めている予定です。これまで経緯としましては、警察等の協議または実地の調査等を踏まえて、現在の中型バスの状況だと、なかなか課題が多いという検討状況です。","id":"exchange-049"},{"speaker":"安藤委員","kind":"質問","question":"ご説明ありがとうございました。たびたび議会でも質問が出されておりましたけれども、どのようなところで、会議体で検討してきたのかをお伺いしたいと思います。","respondent":"櫻木地域交通政策課長","answer":"様々な可能性を従前より検討しておりまして、コミュニティーバスおよびデマンド交通というところも可能性としては検討してきたところです。７月９日より実証運行を開始して、大崎地区でも可能性があるのではないかということで、より具体的に検討を進めているという状況です。","id":"exchange-050"},{"speaker":"安藤委員","kind":"質問","question":"コミュニティーバスの可能性というのはもう放棄したということなのかということを伺います。それとデマンド交通にしようと思った理由について、もう少し伺いたいと思います。","respondent":"櫻木地域交通政策課長","answer":"それとコミュニティーバスの考えを放棄したというご質問ですが、先ほど申し上げましたとおり、大井ルートの運行状況を踏まえて検討するです。はデマンドに決めた理由ですが、その中でどういう形がいいのかということを模索した一つの案です。","id":"exchange-051"},{"speaker":"安藤委員","kind":"質問","question":"それとはまた別といいますか、西品川の地域辺りでデマンド交通をちょっと今、検討しているというイメージでよろしいか尋ねました。","respondent":"櫻木地域交通政策課長","answer":"現在の区の考え方としましては、大崎ルートにつきましては、コミュニティーバスの大井ルートの試行運行の状況を踏まえて検討していく。ただし、非常に課題が多い状況です。","id":"exchange-052"},{"speaker":"安藤委員","kind":"質問・要望","question":"それをしっかり確保していくと。移動も保障しつつ、やはり私はぜひコミュニティーバス大崎ルートの可能性を最後まで追求していただきたいし、実現してほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-053"},{"speaker":"中塚委員","kind":"質問・要望","question":"大崎でデマンド交通の検討を進めていくという説明がありましたので、西大井はどうなのかということを質問させてほしいと求めました。デマンド交通でいえばゼロではないから何％ぐらいになったのかという現状を伺いたいと思います。","respondent":"櫻木地域交通政策課長","answer":"いわゆる西大井循環ルートですが、本会議でも答弁申し上げたとおり、標高差等もあって、交通に課題のある地区として、区としても認識しています。今後もどのような交通がふさわしいかにつきましては、他地区の運行状況を踏まえながら研究していきたいです。","id":"exchange-054"},{"speaker":"中塚委員","kind":"質問・要望","question":"西大井循環ルートは１回示されただけに、１回、どうなっているのだという話も伺います。手法は様々あると思いますけれども、実現してほしいと求めましたが、最後にいかがか尋ねました。","respondent":"櫻木地域交通政策課長","answer":"年に１回、ご説明する中でも、地域の方から非常に強いご要望を受けているのは承知しております。そのような状況も踏まえて、どのようなことができるかというのは考えていきたいと考えています。","id":"exchange-055"},{"speaker":"中塚委員","kind":"質問","question":"視察先の質問は、１０月１日までというお話でしたけれども、今、この場で、口頭も大丈夫なのか尋ねました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-056"},{"speaker":"中塚委員","kind":"質問・要望","question":"全体通じてというところにはなるのですが、やはり大変な災害を経験された自治体の方に、国や県への要望がもしあれば伺いたいと思います。もう１つはこれも全体に関わるのですけれども、やはり高齢者と障害者の被害の実態と支援の視点でのお話を伺いたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-057"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/109228?Template=document&Id=7211#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=8&TermStart=2025-01-01&TermEnd=2025-12-31"}],"sourceMeta":{"pages":0,"characters":57728,"voices":164}},{"id":"r07-20250924-9","meetingId":"r07-cm09","date":"2025年9月24日","dateIso":"2025-09-24","committee":"文教委員会","time":"午前１０時００分～午後 ３時２０分","status":"正式会議録","sourceType":"formal","overview":"文教委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を77件整理しています。","topics":[{"id":"topic-01","title":"教育委員会ＳＮＳの開設","agenda":"教育委員会ＳＮＳの開設","exchanges":[{"speaker":"のだて委員","kind":"質問","question":"この２つにした理由を伺いたいのと、これは研修をやっている様子、中身を紹介するということですか。どういった形かということを伺いたいと思います。","respondent":"舩木庶務課長","answer":"やはり先ほどご説明いたしましたように、先ほど申し上げました目的を達成するためには、この２つの媒体がまずは適切と判断をしたものです。１つ、いろいろ検討したいと考えておりますが、より品川区の教育の様子を発信していければと考えております。","id":"exchange-001"},{"speaker":"横山委員","kind":"質問","question":"教員数を増やす目的のもと、教員を目指す大学生であったり、社会人の方であったりというようなイメージでよろしいのでしょうか。教育委員会のＳＮＳの運用指針は設定されているのか尋ねました。","respondent":"舩木庶務課長","answer":"充実的なものにしていくためにいろいろ検討はしていきたいと考えておりますが、現時点では、そのようなターゲットとして考えているです。","id":"exchange-002"},{"speaker":"まつざわ委員","kind":"質問","question":"何かあったときにどうするのか、教育委員会が独自というお話でしたけれども、どの部署の方が何人ぐらいで対応するのか。例えばそこら辺としっかりと連携してやっていくほうが、より強固になると個人的に思ったので、そこら辺を説明するよう求めました。","respondent":"舩木庶務課長","answer":"第一義的には、常に情報の反応などを踏まえて、適切に管理をしてまいりたいと考えております。対応につきましては、それぞれ学校ごとにこの配信の対応をするのか、そういった体制で臨んでいるところです。","id":"exchange-003"},{"speaker":"まつざわ委員","kind":"質問・要望","question":"こうやって分かるような機会があるといいというのが要望なのですけれども、先生の生の声、現場の声はすごく貴重だと思うのです。それが一番、ぜひそういったものも積極的にアプローチしてほしいと求めましたけれども、いかがか尋ねました。","respondent":"舩木庶務課長","answer":"この教育委員会ＳＮＳを運用開始してまだ一月しかたっておりませんけれども、伝わるものの１つだと考えますので、そういったことも含めて情報素材の検討をしてまいりたいと考えます。","id":"exchange-004"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"９月１１日の大雨のときに、児童は帰りました、そういうタイムリーな話がここでできると思うのです。ですから、もちろん発信していただきたいのですが、その辺りはいかがか尋ねました。","respondent":"舩木庶務課長","answer":"今、現時点では、特色ある教育活動の取組であったりを理解していただくことに重きを置いて進めてまいりたいと考えております。いろいろな情報の取扱いをどうするかについては、今後の検討課題としてまいりたいと考えます。","id":"exchange-005"},{"speaker":"高橋（し）委員","kind":"質問","question":"８月５日に起きて、現在どうだということをきちんと知らせる重要なツールだと思うので、保護者の方とかもたくさんご覧になるようになると思うのです。マイナスのことが起きたときに、きちんとフォローしているということを示す必要があると思うのですが、その点についてはいかがか尋ねました。","respondent":"舩木庶務課長","answer":"様々な危機管理対応にしっかりと教育委員会で対応できていることを発信することで、先々、教育委員会事務局内でも検討してまいりたいと思います。重きを置いて、この教育委員会ＳＮＳを運用してまいりたいと、現時点ではそのように考えております。","id":"exchange-006"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"これで最後ですけれども、いいことをＰＲする大本営発表だけしても、本当の品川区の教育がきちんとしていることにはならないと思うので、ぜひ、現時点ではということですから、そういったきちんとした対応も発信していく必要があると思うので、これは要望して終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-007"},{"speaker":"筒井副委員長","kind":"質問","question":"これは、いちいちそれを取り上げていたらボリュームが多過ぎる、そうした理由なのでしょうか。このただし書の掲載対象外とした理由を示すよう求めました。","respondent":"舩木庶務課長","answer":"より特色のある教育活動をアピールすることを予定しておりまして、それが４０何校分になるわけですけれども、そういったことに主眼を置いて掲載の題材整理をしてまいりたいと考えております。","id":"exchange-008"},{"speaker":"横山委員","kind":"質問・要望","question":"こういった内容をぜひ掲載してほしいというような、そういったご要望であったりとか、その辺りはどう考えていますか尋ねました。","respondent":"舩木庶務課長","answer":"先ほど１点目でご答弁させていただいた今後の教育委員会ＳＮＳの検証の在り方のうちの１つとして、収集した上で、始めました教育委員会ＳＮＳがより充実したものとなるように進めてまいりたいと考えます。","id":"exchange-009"},{"speaker":"横山委員","kind":"質問・要望","question":"どういった発信コンテンツがいいのかは、ぜひ充実させてほしいと求めましたので、要望します。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-010"}]},{"id":"topic-02","title":"令和６年度保護者アンケートおよび児童・生徒アンケートの結果","agenda":"令和６年度保護者アンケートおよび児童・生徒アンケートの結果","exchanges":[{"speaker":"のだて委員","kind":"質問","question":"９年生で少し上がってくるのは、区がどう認識されているかということと、いかがでしょうか。これは全体の結果ですが、どのように授業、学校教育に活用していくのか伺いたいと思います。","respondent":"酒川指導課長","answer":"どのような活動が好きかといった質問に対する児童の回答等も踏まえまして、教育界とも連携しながら授業改善を進めていく必要があると考えております。学校が区の結果と自校の結果を比べて、特に課題であるところを認識し、改善に取り組んでいくものと考えています。","id":"exchange-011"},{"speaker":"のだて委員","kind":"質問・要望","question":"理解が９年通して進んできたということで、確かにそういうこともあると思いますし、やはり理解が進むことで好きになるので、子どもたちが、きちんと理解できる授業を進めていただきたい、取組を進めていただきたい、これは要望にしておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-012"},{"speaker":"まつざわ委員","kind":"質問","question":"やはり中学生に入ってくると、微妙にこうやって数字がずれていく、落ちていく、それが俗に言う、中一ギャップですか。こういうものをどう分析して、こういうギャップをどう埋めていくのか、どのように対応しているのかということを説明するよう求めました。","respondent":"酒川指導課長","answer":"特に、例えば、児童・生徒の単年度版の１３ページです。２年生で、この結果について示しながら、改善策をともに探っていきたいと考えています。","id":"exchange-013"},{"speaker":"まつざわ委員","kind":"質問・要望","question":"それを教えていく先生たちは、中学生のときに用意スタートで始めたものですから、引き続き埋めていただけたらと思います。９４％です、教育委員会として、どう見ているのか説明を求めました。","respondent":"酒川指導課長","answer":"ここにギャップがあるのは認識しておりまして、町会等とも連携し、実践していくように働きかけていきたいと考えています。","id":"exchange-014"},{"speaker":"まつざわ委員","kind":"質問・要望","question":"ボランティアは、まさにやらされるのではなくて、自分がやりたくなるというのがボランティアの根幹だと思っていますので、ＪＣＡも含めて、地域が一番いいと思っていますので、そういった取組をまたどんどん進めてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-015"},{"speaker":"横山委員","kind":"質問","question":"１８.５％、１６.８％と下がって、教育委員会としてどのように分析されているでしょうか。何か分かりましたら、説明を求めました。","respondent":"酒川指導課長","answer":"下がった要因、正確に理由の把握をしていませんけれども、引き続き、どういった理由があるのかというのは探っていく必要がと考えています。","id":"exchange-016"},{"speaker":"横山委員","kind":"質問・要望","question":"そうしたところの要因ですとか、実態もつかんでいただきながら取組につなげてほしいと求めましたので、よろしくお願いいたします。子どもの権利条約の第３１条では、区教委として、どのようにこの結果を受け止めているのかお考えを説明するよう求めました。","respondent":"酒川指導課長","answer":"各ご家庭の方針といったものがあるので、こういう現状については、校長を通じて伝えさせていただこうと考えております。","id":"exchange-017"},{"speaker":"横山委員","kind":"質問","question":"今こういったことがどうしてもしたい、７日間、その辺りいかがか尋ねました。","respondent":"酒川指導課長","answer":"一人一人に個別にケアして対応していく、個別に家庭と連携していくといった辺りを、ぜひ大事にしていってほしいということは伝えていきたいと考えております。","id":"exchange-018"},{"speaker":"高橋（し）委員","kind":"質問","question":"１つ目は、そこを市民科公開授業でしょうか、公開授業との関係で保護者の方の理解が進んだのでしょうかということです。１年生から６年生と遊ぶというのは置いておいて、それなのにこういう数字との関係が分かればですけれども、お願いします。","respondent":"酒川指導課長","answer":"それぞれの校区で一貫教育は進めておりますので、小学校と中学校だけではなく、様々な接続もしっかり発展的に取り組んでいきたいと思っています。９年生、部活動が何か弊害になっているとは認識しておりませんけれども、これは課題だと認識しております。","id":"exchange-019"},{"speaker":"高橋（し）委員","kind":"意見","question":"地域の町会なり、地域のそういった活動もやはりうまくやって、多くの児童・生徒が参加できるようにしていくといいと思います。８年生、９年生の他学年との交流は、課長がおっしゃったような形で交流が進めていけるといいと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-020"}]},{"id":"topic-03","title":"区立学校におけるいじめの重大事態の発生状況および調査結果","agenda":"区立学校におけるいじめの重大事態の発生状況および調査結果","exchanges":[{"speaker":"のだて委員","kind":"質問・要望","question":"ここを改めて伺いたいのと、あと、保護者が公表を希望しないという理由を区はつかんでいるのかどうか。つかんでいたら、どういった理由なのか話せる範囲で伺えればと思います。","respondent":"丸谷教育総合支援センター長","answer":"１件１件の重大事態は、１件１件の細かな共有は現時点では難しいのですけれども、研修を通して改善に努めているところです。新たな二次被害、風評といったようなことも考えられるということで、非公表を望まれる家庭が現時点では多いのだと捉えております。","id":"exchange-021"},{"speaker":"のだて委員","kind":"質問・要望","question":"それと併せて、議会にも、できるところで公表していただきたいと、これは求めておきたいと思います。研修で十分なのかどうかも含めて伺います。","respondent":"丸谷教育総合支援センター長","answer":"新たにいじめ予防プログラムで実施しておりますけれども、心構えや、そうしたものの理解が進んだということ。まだ導入してから２年目ですので、引き続き、継続しながら、品川区のいじめ予防対策を進めていきたいと考えております。","id":"exchange-022"},{"speaker":"のだて委員","kind":"質問・要望","question":"いろいろ教員のほうも子どものほうも進めているということで、引き続き、取り組んでいただいて、子どもたちが健やかに、いじめがないように、そして、いじめがあったとしても、しっかり解決できるような学校にしていくように取り組んでいただきたいと要望しておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-023"},{"speaker":"まつざわ委員","kind":"質問","question":"これを見ると、令和７年８月に３件あるということは、８月だけで、短期間での集中発生なのですか。例えば、この短期間、８月に発生した、３つもあった要因、何かそういった分析はあるのか、まずそれを説明するよう求めました。","respondent":"丸谷教育総合支援センター長","answer":"ずっと対応してきて、割と短期間に進んだものもございまして、そういったものも含めて調査の中で明らかにしていくです。あくまで法律に当てはめて判断したときに、この時期に重なったです。","id":"exchange-024"},{"speaker":"まつざわ委員","kind":"質問・要望","question":"事案番号２だと７か月ぐらい、そこだけは、やはりそういうことは教育委員会としては丁寧に保護者にそうやって話していただきたいとは思っています。前はよく定期的に無記名で子どもたちにアンケートとか、やっていたと思うのですけれども、今はどのような状況なのか尋ねました。","respondent":"丸谷教育総合支援センター長","answer":"非公表となっている事案については、今後は、品川区立学校の中で共有してもよろしいかどうかの確認を丁寧にとってまいりたいと考えております。おおよそ月に１回のペースで、いじめの認知や対応、解決に生かしているという現状です。","id":"exchange-025"},{"speaker":"まつざわ委員","kind":"質問","question":"月１回ということは、すばらしいと思うのですけれども、やはり名前が分かると、なかなかあれですよね。こういうケースに関しても、すぐにこうやって対応していただいたのか、そこの経緯だけ伺いたいと思います。","respondent":"丸谷教育総合支援センター長","answer":"教育総合支援センターに定期的にスクールロイヤー、１件１件、学校や保護者の支援に入っていただいています。中にはＨＥＡＲＴＳが関わるですとか、学校の都費のスクールカウンセラー等とも連携して進めている事例もあります。","id":"exchange-026"},{"speaker":"高橋（し）委員","kind":"意見","question":"事案番号５は、そういった主張、そういったことをされているかどうかとの意見を述べました。","respondent":"丸谷教育総合支援センター長","answer":"文科省が出しているいじめの対応の分類が、6)番でいう金品を隠されたり云々というものに当てはまるので、ご理解をしていただければと考えます。そういった家庭も事案の中にはあるので、この事案番号５がそのとおりではないのですけれども、そういうケースも中にはあるです。","id":"exchange-027"},{"speaker":"横山委員","kind":"確認","question":"品川区の教育委員会として、報告書の中に提言等も入っていると思うのですけれども、どのようにやっていらっしゃるのかを確認したいと求めました。","respondent":"丸谷教育総合支援センター長","answer":"学びの継続では、タブレット上で課題を示したりですとか、その辺りも丁寧に進めているところです。中にはオンラインで授業をつなぐというような取組も行っているケースもありますので、子ども一人一人に寄り添った、合った形で支援を進めてあります。","id":"exchange-028"},{"speaker":"横山委員","kind":"質問・要望","question":"再発防止策については、まだもう少し、もう一歩踏み込んで工夫していただきたいと、お聞きして思ったところがあります。この重大事態調査の目的の１つであると思いますが、ぜひ工夫を重ねていただきたいと思うのですけれども、いかがか尋ねました。","respondent":"丸谷教育総合支援センター長","answer":"事例検討が主になっていきますので、他自治体や、先行事例を織り交ぜた形で行っている現状があります。今後、品川区でも事案が大分重なってきましたので、そういった研修にも生かしていきたいと考えております。","id":"exchange-029"}]},{"id":"topic-04","title":"令和６年度指定管理者による管理に対するモニタリング・評価の結果","agenda":"令和６年度指定管理者による管理に対するモニタリング・評価の結果","exchanges":[{"speaker":"のだて委員","kind":"確認","question":"単純に確認したいところを伺いますが、これはどういったものなのか伺いたいのと、このゲートの故障はどのくらいの期間だったのかを伺います。","respondent":"三ツ橋品川図書館長","answer":"コンシェルジュ３点セットというのは、３つ選定されて、この本がいいですということをお知らせされます。そして、ＢＤＳゲートですが、期間について、１か月程度はかからなかったと考えています。","id":"exchange-030"},{"speaker":"のだて委員","kind":"質問","question":"研修の受講頻度が比較的少ないということだったのですけれども、これはどのくらいの回数なのか、どういう頻度なのか伺います。大井図書館が５年連続で満足度が９０％を超えているのですけれども、この理由はどのように分析されているのか伺いたいと思います。","respondent":"三ツ橋品川図書館長","answer":"例えば、情報セキュリティ関係の研修とか、接遇の研修とか様々ありますので、令和６年度は対応している状況になっています。すごく前々から丁寧な対応で、利用者の満足度がとても丁寧にしていていいという部分で対応していますので、引き続き。","id":"exchange-031"},{"speaker":"のだて委員","kind":"質問・要望","question":"それも生かしながら、全体的に利用拡大を進めていっていただきたい、これは要望しておきたいと思います。２年間ゼロになっていますけれども、その理由を伺いたいのと、実際にどういった事例があったのかを伺いたいと思います。","respondent":"吉野子ども家庭支援センター長","answer":"この中で職員の賃上げを目的に実施されたものになりまして、次年度以降は廃止になっております。最近、特に増えていますお子さんの特性が大分増えてきておりますので、そういったときの対応方法になっております。","id":"exchange-032"},{"speaker":"のだて委員","kind":"質問・要望","question":"人材育成のほうは、ヒヤリ・ハットなどがあったということですか。離職率ですとか、職員の賃金が、十分確保されているのかということを伺いたいと思います。","respondent":"三ツ橋品川図書館長、吉野子ども家庭支援センター長、芝野保育入園調整課長","answer":"離職率に関しましては、調査をしていない状況です。申し訳ありません。 こちらの家庭あんしんセンターですけれども、離職は、ご報告いただいておりません。 ぷりすくーるのほうも、離職率という形では、ご報告はいただいていない状況になります。","id":"exchange-033"},{"speaker":"のだて委員","kind":"質問・要望","question":"賃金が十分なのかということも含めて伺ったので、お聞きしたいと思うのですが、委託費も考慮していただいてやってほしいと求めました。賃金のところを、それぞれ伺いたいと思います。","respondent":"三ツ橋品川図書館長、吉野子ども家庭支援センター長、芝野保育入園調整課長","answer":"こちらの収支報告書にも出ているように、前年度よりも上がっている状況では、人件費の増となっております。 やはり子どもを対応する観点ということで、ある程度、経験が豊富な方を採用しなければならなくなっております。… 職員の処遇ですが、定期昇給分等々、こちらにつきましては、適切に管理運営委託費に積み増して対応させていただいているところです。","id":"exchange-034"},{"speaker":"のだて委員","kind":"質問・要望","question":"職員の処遇も、利用する方にとっては、提供する側の環境が利用者にも影響してくると思いますので、ぜひ賃金や処遇改善、環境をよくしていくこともぜひ視点として見てほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-035"},{"speaker":"まつざわ委員","kind":"意見","question":"トワイライトステイ事業が、年々こうやって利用率が上がっていく一方で、ショートステイがだんだん減っていっていると思うのです。小学校６年生から中学校３年生まで拡充して、この減少した数字の分析はどのようなものなのか説明を求めました。","respondent":"吉野子ども家庭支援センター長","answer":"大体の方が、理由として、育児疲れで利用されるのですけれども、この方たちが２泊とか３泊ではなくて、１泊で利用される方が増えてきています。その分、働き方ということでいきますと、トワイライトステイのほうが、やはり残業などでだんだんと増えてきています。","id":"exchange-036"},{"speaker":"まつざわ委員","kind":"意見","question":"それと、先ほどお話の中でも、支出、１,４００万円が２,３００万円まで大分上がってきている人件費の課題があるというお話を聞きました。どう区と話し合って、どういう方向性でこうやっていきましょうという、どのようにされているのかとの意見を述べました。","respondent":"吉野子ども家庭支援センター長","answer":"こちらの家庭あんしんセンターですけれども、毎月、お話しできる機会があります。そのときに、こういった収支の状況ですとか、あと、事業の報告会がありますので、そこで課題を拾っていきたいと考えています。","id":"exchange-037"},{"speaker":"まつざわ委員","kind":"質問","question":"最後に、ファミリー・サポート・センターの提供会員の強化とありますけれども、やっていたらすみません。今までの３割よりも、これを読んでいて思ったのですけれども、そこら辺はいかがか尋ねました。","respondent":"吉野子ども家庭支援センター長","answer":"ＮＰＯ法人とか、主任児童委員とかもありますので、そちらに働きかけていきたいと思っています。令和７年度から、こちらに関しましても、大学や専門学校にも働きかけていきたいと考えております。","id":"exchange-038"},{"speaker":"横山委員","kind":"質問・要望","question":"レファレンスの数が伸びているのですけれども、内容、サービスの質に何か変化があるのでしょうか。レファレンスサービスの研修についてなのですけれども、現在、どのような学習が行われているのかということも確認したいと求めました。","respondent":"三ツ橋品川図書館長","answer":"区と指定管理業者との月１回の館長会とか、そちらに関しても、向上は実施していただけるように働きかけをしています。それぞれ連携している団体、企業との連携などがありますので、そちらで何かレファレンスのご要望があるときには対応しております。","id":"exchange-039"},{"speaker":"横山委員","kind":"質問・要望","question":"そうしたケースに対して、今後どのような仕組みの構築が必要だと区は考えていますでしょうか。どういったものがあるのか、今後、どういうものが必要になってくるのかも示すよう求めました。","respondent":"吉野子ども家庭支援センター長","answer":"最近ですけれども、ひまわり荘でのニーズとしまして、入所のお子さんが、３歳未満のお子さんが大分増えてきています。子どもへの望ましい声かけであったりなど、いわゆる子育てのノウハウの研修をして、それをお母様たちに伝える対応をしております。","id":"exchange-040"},{"speaker":"横山委員","kind":"質問・要望","question":"今後はそういったものも増やしていただけるといいと考えていますので、ぜひ検討していただきたいと思うのですが、その辺りいかがか尋ねました。","respondent":"吉野子ども家庭支援センター長","answer":"こちらの家庭あんしんセンターなのですけれども、月に１回、私どもの課と連携、そういった話合いの場は設けております。そのときに、１件１件課題を出していただいて、それで解決策を見いだしております。","id":"exchange-041"},{"speaker":"横山委員","kind":"質問","question":"１名、採用があったことで、こちらは予定していなかった採用が発生してしまった背景があるのでしょうか。その辺りを少しご説明いただけたらと思います。","respondent":"芝野保育入園調整課長","answer":"職員の採用の件についてですが、年度途中に、よりよい乳幼児教育活動をするためということで、法人で１名採用したと聞いております。それが金額的にはね返っておりまして、令和７年度については、しっかりそれを委託費の中に入れて対応させていただいてあります。","id":"exchange-042"},{"speaker":"高橋（し）委員","kind":"質問","question":"地域を図書館がつくっていく、まちづくりをしていくという観点で、今後どのような形で指定管理者に突き詰めていくのかということが１つ。それからもう１つは、滞在時間でたくさん利用していただけるということは大変いいことなので、それに関してのお考えを伺います。","respondent":"三ツ橋品川図書館長","answer":"知識のいろいろな取組もしていただければと考えていますので、今後も、まちづくりに一緒に連携していきたいと考えています。新聞を読まれている方、様々な方がいらっしゃいますので、そちらに関しては今後の研究課題と考えています。","id":"exchange-043"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"まちづくりに、地域に協力するというよりも、図書館が中心となって、ぜひまちづくりを進めていってほしいと求めました。滞在時間については、いろいろな指標があるので、１つ参考になると思うので、測定方法を少し検討してほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-044"},{"speaker":"筒井副委員長","kind":"質問","question":"何点か伺いたいと思いますけれども、それについて予算執行の視点で触れられていないのですけれども、その原因について詳しくお知らせください。指定管理者からの賃上げの要求とか、そうしたことを示すよう求めました。","respondent":"三ツ橋品川図書館長","answer":"人件費の増に関しましては、やはり最低賃金の増に伴って上昇しています。","id":"exchange-045"}]},{"id":"topic-05","title":"令和８年度末における小規模保育事業の閉園","agenda":"令和８年度末における小規模保育事業の閉園","exchanges":[{"speaker":"のだて委員","kind":"質問","question":"今回、建物の老朽化で立ち退きになってしまったということですけれども、ほかの何か経営的な問題とか、そうした理由は特にないのかどうかと、今までにこうした保育園が閉園になるということはあったのか伺いたいと思います。","respondent":"佐藤保育事業担当課長","answer":"経営の資源をほかの事業、認可保育園等に集中させていきたいというお考えがあったと伺っております。今年度の末に１園、小規模保育事業所で閉園の予定がございまして、こちらは昨年度の文教委員会においてご説明をさせていただいているものです。","id":"exchange-046"},{"speaker":"横山委員","kind":"確認","question":"確認なのですけれども、この後、令和８年度４月の０歳児クラスですとか、あとは、年度途中で転園してきたお子さんに対しても、転園時の加点を実施するという対応になるのでしょうか、その辺りを確認したいと求めました。","respondent":"佐藤保育事業担当課長","answer":"今後の入園についてですけれども、今後、同一園において卒園ができない児童の年齢に関しましては入園を停止したいという要望を事業者より承っておりますので、そのように対応する予定です。","id":"exchange-047"},{"speaker":"若林委員","kind":"確認","question":"この周辺の０歳児園、１歳児枠は、現状、加点で入れればというお話の趣旨だとは思うのですけれども、確認で状況を、確実に転園がきちんとできますということも確認したい。","respondent":"佐藤保育事業担当課長","answer":"１歳児はなかなか空き枠がございませんので、周辺５００ｍ程度の範囲ですと、１名程度の空きしか今はないというものです。しかし、現在の１歳児、２歳児の方は、来年の４月に閉園になりますので、卒園して継続の連携園への入園が可能となる状況です。","id":"exchange-048"},{"speaker":"高橋（し）委員","kind":"質問","question":"令和８年度末で閉園すると、３月３１日に廃止のような気がするのですけれども、４月１日にもいることにして転園するのですか。この廃止日が令和９年度の４月１日ですよね、そこが少し分からないのですけれども。","respondent":"佐藤保育事業担当課長","answer":"こちら、閉園の記載なのですけれども、４月１日に閉園という記載の方法になっていますので、３月３１日に閉園ではなく、４月１日をもって閉園するという記載となっているものです。","id":"exchange-049"}]},{"id":"topic-06","title":"令和６年度品川区児童相談所運営実績","agenda":"令和６年度品川区児童相談所運営実績","exchanges":[{"speaker":"のだて委員","kind":"質問","question":"課題に書かれておりますけれども、４階バルコニーに児童が出てしまう事故があったということで、出られるようになっていないのか伺います。それと、その下に、特性のある児童が増えているので、職員の育成が急務だということですが、どういった部分が足りないのか伺いたいと思います。","respondent":"長谷川児童相談課長","answer":"まず１点目の課題のところに記載させていただいた事故に関してですけれども、バルコニーにもともと子どもが出られる想定にはしておりません。日々、職員会議等で情報共有しながら、子どもの支援に当たっている状況です。","id":"exchange-050"},{"speaker":"のだて委員","kind":"質問・要望","question":"改めて何かあれば伺いたいと思います。この事故を受けて対応が必要だということで書かれているのか、どういった専門性が必要なのかを伺いたかったのですけれども、いかがか尋ねました。","respondent":"長谷川児童相談課長","answer":"それは現在も継続して実施しておりますので、それ以降、同様の事例は発生しておりません。そこら辺の起こってみて初めて分かる対応策もありますので、より迅速に対応するためにはどうすればいいかという視点での検討は日々行っています。","id":"exchange-051"},{"speaker":"のだて委員","kind":"質問・要望","question":"区内でどういったことが起きている、どういったことをあらわしていることになるのか、そこを伺いたいと思います。いる場合は、何人ぐらいいて、全体の中の何割ぐらいなのか分かれば伺います。","respondent":"長谷川児童相談課長","answer":"入所の措置が増えていったことになりますので、全体的な流れの中で件数がどんどん増えていったということのほうが説明としては正しいと思っています。","id":"exchange-052"},{"speaker":"のだて委員","kind":"質問","question":"同じ区内ですから、そうした施設の設置も進めていかなければいけないと思いますけれども、いかがでしょうか。２か月を超えているのが２３％いらっしゃるということで、この理由はどういったことなのか、理由を伺いたいと思います。","respondent":"長谷川児童相談課長","answer":"１つ申し上げられるのは、当然、児童相談所の職員全員が家庭で生活できるならしたほうがいいと思っています。みんなで知恵を絞って、日々、会議等を重ねている現状です。","id":"exchange-053"},{"speaker":"のだて委員","kind":"質問・要望","question":"長期入所は、職員の方もいろいろ家庭のほうも支援していただきながら、復帰につながるようにやっていってほしいと求めました。退職者などはいらっしゃるのかどうかと、やはりそうしたことがないようにケアをしっかりしていただきたいと思うのですけれども、いかがか尋ねました。","respondent":"長谷川児童相談課長","answer":"適宜調整を図るですとか、知恵を出し合って、やれることを今全力でやっている状況です。最低毎月１回は年休を取ろうという話をしておりますので、調子を伺いながら、健全な職場を維持できるように努めているといった状況です。","id":"exchange-054"},{"speaker":"のだて委員","kind":"質問・要望","question":"様々大変な状況があると思いますので、ぜひ職員の方へのケア、充実させていってほしいと求めました。今の状況、どのくらいの方が、どのぐらいの超勤になっているのか分かれば伺いたいと思います。","respondent":"長谷川児童相談課長","answer":"超勤の状況になりますけれども、平均で言うと、全体の１割ぐらいの方が、４５時間を超えている状況になっております。やはり保護者は支援に乗ってこない難しさもあり、こちらとして対応でき得る限り、可能な限り対応していくことで。","id":"exchange-055"},{"speaker":"横山委員","kind":"確認","question":"質問ですけれども、児童相談所の運営状況等ということで、こちらは特に変更がないということでよろしいのかどうか確認をさせてください。は子ども家庭支援センターの両方のお声があったりするかと思うのですけれども、どういった状況なのか現状を教えてほしいと求めました。","respondent":"長谷川児童相談課長","answer":"一定課題感もありますけれども、とにかく目の前にある１件１件に真摯に向き合って、丁寧に対応していくことに尽きると思っています。","id":"exchange-056"},{"speaker":"横山委員","kind":"質問・要望","question":"どうしていくのがいいのかは、どういった形がいいのかは、お声を聞いていただきながら進めてほしいと求めました。どうだったのか少し気になったのですが、どういった対応をしていくのか、どのように確認されているのかということを説明するよう求めました。","respondent":"長谷川児童相談課長","answer":"普通の子が家庭でできるようなことはできるだけ実施できるように企画、品川区としては、かなり力を入れている部分でもあります。どう対応すべきか、そして誰もが同じ対応ができるように共通認識を持つことを徹底して、極力不穏にならないような対応は心がけている状況です。","id":"exchange-057"},{"speaker":"高橋（し）委員","kind":"意見","question":"１つだけ、ここの中に、どこに入るか分からないのですけれども、子ども家庭支援センターとの連携も捉えていると思うのですけれども、その辺りの、この表の中の数字でなくてもいいので、これまでの連携の実績、協力体制をお話ほしいと求めました。","respondent":"長谷川児童相談課長","answer":"支援機関を決めようというところで、子ども家庭支援センターと、膝つきの検討をして決めた仕組みになります。出ないのですけれども、おおよそこれまで受けていた相談の大体２割ぐらいが、合同会議を経て児童相談所が対応することになっています。","id":"exchange-058"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"今お話を伺って、合同会議と、あと、そういった連携の相談をしながら、児相が２０％受けたとかありますけれども、協力体制が進んでいっているのだと思うので、ぜひ一体となって対応していってほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-059"}]},{"id":"topic-07","title":"所管事務調査","agenda":"所管事務調査","exchanges":[{"speaker":"のだて委員","kind":"質問","question":"１日当たり１０.９人、豊葉の杜学園は０.４人で、どのように考えていらっしゃるのか伺いたいと思います。２か月弱ですけれども、どういうときに利用が多いとか、そういったことはあるのかどうか伺います。","respondent":"上野子ども育成課長","answer":"ご質問２点にお答えいたします。豊葉の杜学園は、お一人の方が週に２回参加しているということで、この平均の状況になっています。","id":"exchange-060"},{"speaker":"のだて委員","kind":"質問","question":"そうすると、特に、こういうときが多いとか、そういうことはないのですね。全校展開に向けて、民間事業者への委託も検討していくということで、これはどういったところに委託をしようと検討されているのか伺います。","respondent":"上野子ども育成課長","answer":"今後、民間委託の委託先ですけれども、人材派遣会社ですとか、警備会社を想定しています。","id":"exchange-061"},{"speaker":"のだて委員","kind":"質問・要望","question":"区の考えを伺いたいのと、あと、朝食です。１点、この円グラフが全く同じ割合なのですけれども、これは何か間違いかどうかをまず確認させていただきたい。","respondent":"上野子ども育成課長","answer":"それから危機管理等についてご説明した上で対応をお願いしていますので、今後、同レベルの研修等を実施して対応をお願いしたいと考えております。もう１つの朝食支援を利用したい、これは間違いではございませんで、たまたま偶然でこういう形になっているものです。","id":"exchange-062"},{"speaker":"のだて委員","kind":"質問","question":"その他もどういったことがあるのかを伺いたいのと、どちらも２５％ということで、どういったことがあるのかということを伺いたいと思います。1)で、献立はどういうものになるのか、どういったものを作成していくのか伺います。","respondent":"上野子ども育成課長","answer":"朝食支援を利用したい理由の中で、特殊な状況への対応についてですけれども、出張による早朝勤務時の対応というものをいただいています。保護者の方がそれをご覧いただいた上で、注文されるかどうかはご判断いただく形で進めてまいりたいと考えております。","id":"exchange-063"},{"speaker":"まつざわ委員","kind":"意見","question":"なかなか３校でやっていて、多分こういうものは、今の試行運営でもばらつきがあると思っているのです。１期をもう１回見てからだと思っているのですけれども、そういう１期でやったときに、基準が今あるのかということを聞かせてくださいとの意見を述べました。","respondent":"上野子ども育成課長","answer":"まだこれから１期を始めるところですので、全く利用がない場合等については、どのように対応していくかは今後検討してまいりたいと思っています。","id":"exchange-064"},{"speaker":"まつざわ委員","kind":"質問","question":"もう１つ、課題の１つで、見守り隊の確保と、今、シルバー人材センターとかに委託、警備会社とかに頼みたいというお話があった。そういった差も、これからどうやって埋めていくのか、そこを説明するよう求めました。","respondent":"上野子ども育成課長","answer":"まずは全校展開を進めていく中で、そこについては、一旦は差がある状況で進めてまいると考えています。今後、シルバー人材センターでの募集を進めていく中で、なるべく同一の事業者で対応できるように進めてまいりたいと考えております。","id":"exchange-065"},{"speaker":"まつざわ委員","kind":"質問","question":"やはりそれを感じ取るのは子どもですから、しっかり子どもの話を聞いて、見守り隊の方はどうですかということは意見を聞いてほしいと思っています。１１月から３校で試行実施すると言いますけれども、その効果があるのですか、そういうものは現状であるのか説明を求めました。","respondent":"上野子ども育成課長","answer":"お考え等あると思いますので、ご利用される方がいらっしゃれば、ニーズがあると考えております。","id":"exchange-066"},{"speaker":"まつざわ委員","kind":"質問・要望","question":"７％は食事をとらないのであれば、なおすばらしい事業になると勝手に思っていますので、要望です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-067"},{"speaker":"高橋（し）委員","kind":"質問","question":"そのときには何か、当時の課長の言葉をかりると、何かあったときのための体制はどのように構築されているのでしょうかということが２つ目。現状で応募の状況はどうなのか、この１０月で１０校でしょうか、その辺りはいかがか尋ねました。","respondent":"上野子ども育成課長","answer":"何かあった場合は、まずは本課にご連絡をいただきまして対応するということで進めてまいりたいと考えています。第１期１０月開始につきましては、ほぼ開始のめどが立っており、人員は集まっている状況です。","id":"exchange-068"},{"speaker":"高橋（し）委員","kind":"質問","question":"これから１０校とか増えていくときに、すぐそこに、８時少し前だったら学校の先生がいるわけですよね。どう調整しているか、その辺の連携は、どのようになっているのか尋ねました。","respondent":"上野子ども育成課長","answer":"一義的には、まずは見守り員の方にご対応いただいて、本課にご相談いただくことにはなります。もしどうしても、そこについては、まずは見守り員の方と今回は対応してまいりたいと考えています。","id":"exchange-069"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"いろいろなものに対応をするということを学校を回ってお話しされているということですので、事故がないのが一番ですけれども、そういったときの対応はしっかりと協力して行ってほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-070"},{"speaker":"横山委員","kind":"確認","question":"多くて源氏前小学校で１０.９人ということなので、不十分なのかどうか、教えてください。どういったことが想定されているのかということと、また、こうした対応をしてくださいといったご案内がされているのか確認したいと求めました。","respondent":"上野子ども育成課長","answer":"それから２点目のご質問、場合分けしたトラブル対応のマニュアルをつくっておりまして、そちらを見守り員の方にご説明をしてお配りしている状況です。回答率につきましては、低いところで１６％になっておりますので、おおよそこのぐらいの割合と考えております。","id":"exchange-071"},{"speaker":"横山委員","kind":"確認","question":"お部屋の中で見守る見守り員の方が２名と、校門の前で見守っていただく方が１名で、これからは進めていくということを確認いたしました。被害を受けている校舎などあったかと思いますが、こちらについても危機管理マニュアルに記載されているのか、最後に確認したいと求めました。","respondent":"上野子ども育成課長","answer":"朝の居場所の実施マニュアルに記載させていただいておりまして、どちらかというと、中止時の対応についてに記載を含めております。どういう場合に中止をするかということで、こちらにつきましては、品川区教育委員会の対応を準拠し対応することで記載をしております。","id":"exchange-072"},{"speaker":"横山委員","kind":"質問・要望","question":"危機管理マニュアル等にも教育委員会の指針ですとか様々な地震マニュアルを含めて研修等でしっかり伝えていただく必要があるかと思いますので、ぜひ今後に生かしていただきたいと思うのですが、その辺りをもう１回お願いします。","respondent":"上野子ども育成課長","answer":"ご指摘のございました大雨等の場合、中止のご連絡がどうしても難しい場合ということもいただきましたので、今後、研修等で、その辺りをお伝えしつつ、管理マニュアルにも反映させてまいりたいと考えております。","id":"exchange-073"},{"speaker":"若林委員","kind":"意見","question":"２期と進む中で、着実にこれは前に進めるべきだということでもいいですし、コメントをいただけますかとの意見を述べました。","respondent":"上野子ども育成課長","answer":"なので、門の前で待つというよりは、門は７時半には開いていて、学校の玄関の前、そちらまでは入れる状況に現在あるということです。屋外にはなるのですけれども、お子さんがそこで待つことができる環境にある状況で、見守りの部屋まで行く方が結果的に少ないと聞いています。","id":"exchange-074"},{"speaker":"若林委員","kind":"提案","question":"いずれにしても、このアンケート結果、居場所を知っているかというのが９６％ですか、高い周知率も含めて、おおむね評価を得ているのだと思いました。議会の提案に対して区が積極的に朝食にも光を当てていただいてセットで、１％でも、それは願ってやみませんとの意見を述べました。","respondent":"上野子ども育成課長","answer":"すみません、説明が足りずに失礼いたしました。道を渡らないといけない、外で待っているお子さんがいらっしゃって、あえて道を挟んだ反対側の見守りの部屋に行っていないという状況があるようです。","id":"exchange-075"},{"speaker":"若林委員","kind":"質問","question":"その子たちは、いわゆる登録している方たちか尋ねました。","respondent":"上野子ども育成課長","answer":"登録している方です。","id":"exchange-076"},{"speaker":"若林委員","kind":"質問","question":"７時半の時間帯を目指して来ている子どもたちは、７時半にいらっしゃる子どもは、全部登録している方ですか。登録していなくても、別に７時半に行ってもいいわけですよね。","respondent":"上野子ども育成課長","answer":"７時半に門が開きますので、開いた時点で入れるので、必ずしも居場所に登録されているかどうかは分からない状況です。ただ、部屋にいらっしゃったときに、事前登録制になっておりますので、登録していただいた方が居場所の利用ができるという形の事業になっております。","id":"exchange-077"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/843512?Template=document&Id=7167#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=9&TermStart=2025-01-01&TermEnd=2025-12-31"}],"sourceMeta":{"pages":0,"characters":75952,"voices":240}},{"id":"r07-20250924-5","meetingId":"r07-cm09","date":"2025年9月24日","dateIso":"2025-09-24","committee":"総務委員会","time":"午前１０時００分～午後 １時０５分","status":"正式会議録","sourceType":"formal","overview":"総務委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を50件整理しています。","topics":[{"id":"topic-01","title":"説明に入る前に、各所管委員会における審査の結果","agenda":"説明に入る前に、各所管委員会における審査の結果","exchanges":[{"speaker":"西本委員","kind":"質問","question":"その仕組みを教えてほしいのと、それと、なぜ今の時期に補正が出てくるのかなと思います。結構頻繁に最近出てきていると感じるのですが、それの何か基準というのは何か決め事があるのでしょうか、説明を求めました。","respondent":"加島財政課長","answer":"その分、令和７年度に本来行うべきであった工事ができておりませんので、７年度に当初予定していた工期出来高が発生しない見込みです。町会・自治会が設置する防犯カメラへの助成と、住まいの防犯のほうは令和６年度からですけれども、区で実施していたものです。","id":"exchange-001"},{"speaker":"西本委員","kind":"質問","question":"ただ、これ、事業者の方々はどうなのですか。金額はいろいろあるでしょうから、その中の範囲だったら流用可能なのですよというようなものがあるのであれば、それを説明するよう求めました。","respondent":"加島財政課長","answer":"１点目の八潮南特別養護老人ホームの工期延伸の件ですけれども、またインフレスライドにも対応しておりますので、そういう状況ではございません。","id":"exchange-002"}]},{"id":"topic-02","title":"勝島歩道橋補修工事請負契約","agenda":"勝島歩道橋補修工事請負契約","exchanges":[{"speaker":"須貝委員","kind":"質問","question":"この歩道橋補修工事ですが、前回はいつ頃やられたのですか。説明を求めました。","respondent":"佐藤経理課長","answer":"前回の大きい補修工事については特段所管から聞いておりませんで、この歩道橋は１９８５年ですので、約４０年前にできたもので、細かい補修については日々の中でやっているということだと思います。","id":"exchange-003"},{"speaker":"須貝委員","kind":"質問","question":"やはり１０数年から２０年ぐらいのサイクルで補修していると思うのですが、何でこんなふうに４０年間も放っておいたのかなというのは少し疑問に感じたもので、それだけ説明を求めました。","respondent":"佐藤経理課長","answer":"橋梁に関しては、品川区橋梁長寿命化修繕計画というもので、区が管理している橋梁については全て計画に含んでいると。今回のような大規模な工事については、設計をした上で、状況に応じて計画して進めていると聞いております。","id":"exchange-004"},{"speaker":"西本委員","kind":"質問","question":"これは補助金があるのですか、国とか東京都から。これは、品川区独自の財源からか尋ねました。","respondent":"佐藤経理課長","answer":"〔「そうですね。","id":"exchange-005"}]},{"id":"topic-03","title":"子供の森公園管理事務所改築工事請負契約","agenda":"子供の森公園管理事務所改築工事請負契約","exchanges":[{"speaker":"須貝委員","kind":"質問","question":"経理課として、昨日も少し質問させていただきましたが、大丈夫なのですか。そんなに従業員がいるようには私も見ていないのですが、その辺は大丈夫なのか尋ねました。","respondent":"佐藤経理課長","answer":"一定の施工能力を確保するために実績要件ですとかそういったものを求めて、条件として出して、それに応じて入札いただいているということです。こちらに関しては、区で一つ一つ確認するわけではありませんけれども、それぞれの事業者で判断して応札いただいているところです。","id":"exchange-006"},{"speaker":"須貝委員","kind":"意見","question":"今、民間企業でも、例えば協力会社に仕事をお願いするときに、能力的にどうだとかこうだとかということをやはり判断しながら発注をしている。また入札に参加させて落札したというのは、非常に何か違和感を覚えるのですが、もう一度だけお答えくださいとの意見を述べました。","respondent":"佐藤経理課長","answer":"区が事業者の事業実態について踏み込んで確認するということはできませんので、そういったペナルティについても制度として設けておりますので、そこは事業者としてきちんと判断して応札いただいているということだと思います。","id":"exchange-007"},{"speaker":"須貝委員","kind":"意見","question":"ほかの様々な、品川区でいろいろ指名入札する場合もあると思うのですが、必ず見ていると思うのですね。相手が仕事を受けるから、入札に参加させたというのは、私はやはり考えていかなければいけないと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-008"}]},{"id":"topic-04","title":"庁有自動車のカーナビに係るＮＨＫ放送受信料の支払い","agenda":"庁有自動車のカーナビに係るＮＨＫ放送受信料の支払い","exchanges":[{"speaker":"須貝委員","kind":"質問","question":"これ、今まで、毎年、ＮＨＫから請求というのはきちんとコンスタントに来ていたのですか。説明を求めました。","respondent":"佐藤経理課長","answer":"毎年ＮＨＫから１０月に、テレビも含めて受信機器の設置状況の調査というものが来ておりまして、経理課で取りまとめて回答しております。これを基にしまして翌年度に設置施設ごとに受信料を請求して、それに対して各施設、この分それぞれについて支払いをしているという状況です。","id":"exchange-009"},{"speaker":"須貝委員","kind":"質問","question":"ＮＨＫが裁判でも勝ったから皆さんに、各自治体にも請求するというのは、少し不可解な気持ちがするのですね。そうでなかったら、何か過去の分は払う必要はないのではないかという気がするのですが、その辺のご見解を説明するよう求めました。","respondent":"佐藤経理課長","answer":"もう１点、テレビをはじめとした受信機器を設置した場合は受信契約を結ばなければならないという規定になっております。それに従って、受信料についても同様、過去に遡って請求されるです。","id":"exchange-010"},{"speaker":"須貝委員","kind":"質問","question":"アンテナが何本立っています、ＢＳアンテナがありますと調べるではないですか。こうやって「どうなのですか、ほかの自治体が払っているからうちもやらなければいけないというのは、何か違和感がある今回の事件です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-011"},{"speaker":"西本委員","kind":"質問","question":"それから、カーナビ５台を撤去しているということですが、カーナビ５台は必要ないという結果に基づいて撤去ということになったのでしょうか。では、要らなかったということは、今まで甘かったのという、何かそういうことも考えてしまうので、その現状を説明するよう求めました。","respondent":"佐藤経理課長","answer":"先ほど説明の中でもありましたけれども、解釈の範囲の中で、当初想定していた台数よりは減ったところかと考えています。今はもうスマホ等もありますので、撤去した車に関しては必要ないだろうというところで、撤去されているところです。","id":"exchange-012"},{"speaker":"西本委員","kind":"質問・要望","question":"やはり責任の所在というのはもっと明確であるべきではないのかと私も思いますので、少し私たちは税金で支払うという、そこはきちんとしてもらいたい。していただきたいと、今後こういうことのないように、いろいろと注視していただきたいと考えています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-013"},{"speaker":"塚本副委員長","kind":"確認","question":"これは少し教えてほしいというか、ないのかの確認だけですが、向こう側の契約の在り方としてあるのかどうかというのを説明するよう求めました。","respondent":"佐藤経理課長","answer":"契約の本数といいますか、対応のことですけれども、結論的には車１台について１契約という形になっております。１台契約していれば、その範囲で１契約しているというところですけれども、それに沿って１契約ずつになっております。","id":"exchange-014"},{"speaker":"塚本副委員長","kind":"質問","question":"そうすると、カーナビですが、本来は道案内が、もともとは役割だったと思うのですが、今の車は多分、基本的にテレビが見られるようになっていると思うので、車を買うと、もう必然的に契約みたいな、ＮＨＫの契約はしませんみたいなことは恐らくできないと思うのですが、できる余地はあるのか尋ねました。","respondent":"佐藤経理課長","answer":"世帯で１契約というところになっておりますので、１契約で済むということですので、それは影響ないということでした。各車ごとに考えるという形になっておりますので、あるいは、つけずに購入するかというところで判断していきたいと思います。","id":"exchange-015"},{"speaker":"塚本副委員長","kind":"確認","question":"最後に一つ確認で、では、仮にカーナビは内蔵していない車がオプションとしてあって、カーナビはつけません。職員とか庁舎が持っているスマホとかでカーナビの代用をしますというような場合は、それは契約の対象にならないということでよろしいか尋ねました。","respondent":"佐藤経理課長","answer":"あくまでもテレビの受信装置というところで、今回、受信料を払いますので、単純にカーナビであれば、スマホであっても同様だと思いますけれども、受信料は必要ないということになると思います。","id":"exchange-016"},{"speaker":"山本委員","kind":"質問・要望","question":"本件は放送法にのっとったお支払いだということで、理解しております。何か横の連携とかで国にこの法改正を求めるとか、お考えやその動向があれば、説明を求めました。","respondent":"佐藤経理課長","answer":"自治体は支払う義務があるという形になろうと思いますが、社会福祉施設ですとか学校等は個別に受信料が免除されているという状況です。","id":"exchange-017"},{"speaker":"山本委員","kind":"質問","question":"状況は理解いたしました。東京都は本件に関してどれぐらい支払っているかというのをもし把握されていたら、説明を求めました。","respondent":"佐藤経理課長","answer":"東京都は、報道の内容ですけれども、５１８台対象になって約５,１００万円を支払うと聞いております。","id":"exchange-018"},{"speaker":"山本委員","kind":"質問・要望","question":"東京都も５,０００万円と割と大きな金額を払っていると思いますし、そういった機会があるときは、ぜひ積極的に連携してほしいと求めました。要望であります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-019"}]},{"id":"topic-05","title":"「品川区ジェンダー平等と性の多様性を尊重し合う社会を実現するための計画（素案）」に係るパブリックコメントの実施","agenda":"「品川区ジェンダー平等と性の多様性を尊重し合う社会を実現するための計画（素案）」に係るパブリックコメントの実施","exchanges":[{"speaker":"石田（ち）委員","kind":"質問・要望","question":"計画策定ということで、本当に重要なものになっていくだろうなと思っています。私たちは区民への説明というのは求めているのですけれども、ジェンダーの部分でも説明会をしていただきたいと思うのですけれども、いかがか尋ねました。","respondent":"木村人権・ジェンダー平等推進課長","answer":"推進計画について、パブリックコメントには多く皆さんにご意見をいただきたいと思っているところなのですけれども、特にご説明会というよりは、初日からＳＮＳ配信等で、パブリックコメントを実施していますというところを広く周知してまいりたいと思います。","id":"exchange-020"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"そうした積極的な対応が必要だと思っていますので、説明会の実施を改めて求めておきたいと思います。それを具体化させる計画ということなのですけれども、そういう中でも少し困難があるとか、そういう部分があれば伺いたいと思います。","respondent":"木村人権・ジェンダー平等推進課長","answer":"先ほど説明の中にあったＤＥ＆Ｉなどに関することについては、たたかれているというような状況、困難になっている状況があります。進め方については、ジェンダーについて考えて、全ての事業を執り行っていく必要があるというところを打ち出していくところになっております。","id":"exchange-021"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"本当に世界的にバックラッシュがあるというところでは、そういったところへの対応もしつつ進めていくというのは、本当に大変だと思うのですよね。ぜひ積極的に進めていただきたいですし、改めて説明会等も少し要望しながら、進めていただきたいと思っています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-022"},{"speaker":"西本委員","kind":"質問・要望","question":"子育て支援とは何だろうかといったときに、やはり親が子どもをしっかり見てほしいというのがあるのですよ。これから進める上で、その２点についてどう考えられるのかなと思いますが、いかがか尋ねました。","respondent":"木村人権・ジェンダー平等推進課長","answer":"５年の計画に変更して策定をしていきますし、前年度の事業状況評価をする中で、確認をしていくような形になるのかなと考えています。２つ目の子育て支援につきましては、子育て支援の中に、区内の事業者等と連携して進めていければと考えています。","id":"exchange-023"},{"speaker":"西本委員","kind":"質問・要望","question":"５年でも長いかなというぐらい世の中はすごい進んでいると感じているので、実際、将来も見据えた形の内容にぜひ改定をしてほしいと求めました。そこは今後、子育て支援というのはどういうことなのかということも含めて進めていただきたいと、要望をしておきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-024"},{"speaker":"須貝委員","kind":"質問・要望","question":"区としてできる限りこういうことをどんどん進めていってほしいのと、今度、また取り組んでいってほしいと求めました。どうすればいいのというのが、行政としてできる限りのことを、私はやってほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-025"},{"speaker":"山本委員","kind":"確認","question":"今回、５年の計画で、各項目で目標設定して、各年度で進捗確認をすることで理解いたしました。この計画では５年後が示されているのですけれども、これには表記されていないものも、区としては設定していかれるのでしょうかというところです。","respondent":"木村人権・ジェンダー平等推進課長","answer":"１点目の件につきましては、こちらは計画になりますので、目標値は５年後の数値を掲載しております。毎年の目標というよりは、毎年の結果をもって毎年評価をしていこうというところで、考えているところです。","id":"exchange-026"},{"speaker":"山本委員","kind":"質問","question":"ホームページで全部こういうものを、項目ごとに発表していくのか尋ねました。","respondent":"木村人権・ジェンダー平等推進課長","answer":"ホームページにこちらの資料を掲載いたしますので、こちらを見ていただいて、パブリックコメントをいただくような形で考えております。","id":"exchange-027"},{"speaker":"山本委員","kind":"質問・要望","question":"先ほどの２つ目の質問の主旨は、今回もご答弁いただいたように、全項目について発表されるということなのかどうかというのが知りたかった。５年ごとに実施の中でこれを確認するということなのかなと、５年後に取るまでは、併せて確認させてほしいと求めました。","respondent":"木村人権・ジェンダー平等推進課長","answer":"令和６年に実施しておりまして、５年ごとに実施をすることになっておりますので、正確なものについては分からないというところになります。ただ、５年後に向けて、条例と宣言の周知に努めてまいります。","id":"exchange-028"},{"speaker":"山本委員","kind":"質問・要望","question":"この２年で１０％弱ぐらい、こうやって横串で見ると進んでいるというのが確認できたりもしますので、実施していただきたいと考えています。それに関してのご意見を伺いたいというのが１つと、何か分かりやすく説明していく手法とかお考え、教えてほしいと求めました。","respondent":"木村人権・ジェンダー平等推進課長","answer":"１つ目の件につきましては、渋谷区もそうなのですけれども、ほかの事例等を勉強して、確認をしていきたいと思います。２つ目の、この計画自体は進められませんので、ＳＮＳも含めて広く周知に努めていきたいと考えています。","id":"exchange-029"},{"speaker":"山本委員","kind":"質問・要望","question":"ＳＮＳ等を通じて周知を進めていただきたいのですが、計画自体が１５０ページぐらいで結構量が多いものですから、ご検討ほしいと求めました。要望で終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-030"}]},{"id":"topic-06","title":"令和６年度マイセルフ品川プラン～誰もが自分らしく～推進状況評価の報告","agenda":"令和６年度マイセルフ品川プラン～誰もが自分らしく～推進状況評価の報告","exchanges":[{"speaker":"石田（ち）委員","kind":"意見","question":"今、マイセルフ品川プランの推進状況評価報告書ということで、この推進状況評価報告書ですが、今後、さっき説明いただいたジェンダー平等と性の多様性を尊重し合う社会を実現するための計画が策定された後というのは、このマイセルフ品川プランというのが一緒に……との意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-031"},{"speaker":"石田（ち）委員","kind":"質問","question":"そうです、移行されるのかと、整合性、どういうふうになっていくのか、お聞きしたいと思います。","respondent":"木村人権・ジェンダー平等推進課長","answer":"年来年４月以降に、同じような状況評価報告書が上がるのかというところだと思いますけれども、こちらについては毎年実施をしてまいります。","id":"exchange-032"},{"speaker":"石田（ち）委員","kind":"質問","question":"そうすると、令和７年度の評価ということになると、もうこのマイセルフ品川プランという言い方ではなくなる。先ほど毎年出すとおっしゃっていたので、マイセルフ品川プランという名前の計画、プランというのはなくなっていくということでいいのか尋ねました。","respondent":"木村人権・ジェンダー平等推進課長","answer":"現在、愛称をつけるかどうかも含めて検討中ということになりますので、今のところはまだ未定になっております。新しい計画は令和８年から実施ということになりますので、ただ、評価方法ですとか内容については今後検討していくところにはなりますけれども。","id":"exchange-033"},{"speaker":"須貝委員","kind":"質問","question":"言うべきか言わぬべきか少し迷ったのですが、区の企画経営部長、こういうのをどう思うのですか。どうなのか尋ねました。","respondent":"柏原区長室長","answer":"いろいろな方にも入っていただいてご意見をいただいていますので、こういった目標を出させていただいて、それに向かって努力していくのだと。こういう世の中を目指したいという大きな区としての思いを出させていただいたというところで、ご理解いただければと思います。","id":"exchange-034"},{"speaker":"須貝委員","kind":"質問・要望","question":"課長からこういう報告書が出るではないですか、区でまとめて。議論はしません。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-035"},{"speaker":"西本委員","kind":"質問","question":"結局は統合になることをやるということは、何か取っかかりが逆なのではないのと思っているのですが、どうなのですか。どうなのか尋ねました。","respondent":"木村人権・ジェンダー平等推進課長","answer":"いろいろな法律を包含しているものになりますので、こちらの内容は引き続きやっていくところも多いかと思いますけれども、二重になるということは考えていないです。","id":"exchange-036"},{"speaker":"西本委員","kind":"質問","question":"本来は、品川区のいろいろな事業の中に、全ての基礎となる１本こういう柱があってというのは分からないではないのですか。結果的には一緒で別にいいのだけれども、スタートのときからそうすればよかったのではないのですかという話。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-037"}]},{"id":"topic-07","title":"その他","agenda":"その他","exchanges":[{"speaker":"西本委員","kind":"質問・要望","question":"ということは、では、どこが起点になるのかというのをまず確認したいのが１つです。これは要望も含めて、そのお考えを確認させていただきたいということで、この２つをお願いしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-038"},{"speaker":"石田（秀）委員長","kind":"質問・要望","question":"目的が違うのでと言ったのかどうか、そこは必ず大切なことだと思っていたので、それは理事者の方にもご答弁はいただきたい。ただ、先ほども自分でも何回も質問をやっているのでということなので、この場でそれをもう一回行ったり来たりの議論はないと思っているのですね。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-039"},{"speaker":"西本委員","kind":"質問・要望","question":"それはどういう意味なのでしょうか。おかしいのではないかという動議もかけさせていただきましたが、それを受けて、議員の行動次第というのはどういう意味なのか尋ねました。","respondent":"與那嶺戦略広報課長","answer":"今年の補正予算でも様々なご説明をさせていただいているかと思うのですけれども、プレス発表の前にご説明させていただいているというところで、そういった形にはしていないところになっているものです。","id":"exchange-040"},{"speaker":"西本委員","kind":"質問","question":"では、区長が発表する前にそういう情報が得られたら、公開してよいということでの理解でいいですか。そういうことを意味しているのか尋ねました。","respondent":"與那嶺戦略広報課長","answer":"ある意味お願いと申しますか、どういった形で取り扱っていただくかというところは、そこはご判断に委ねるしかないのかなと考えています。我々といたしましては、いかにしっかりと伝えていけるかというところをプレス発表として準備しています。","id":"exchange-041"},{"speaker":"西本委員","kind":"確認","question":"ほかのところはやっていないですよ、今回、この第２回定例会の報道はしかもデジタル配信ですから、もうばーんと出てしまうわけですよね。そこだけもう一度確認して、これは終わりたいと思います。","respondent":"與那嶺戦略広報課長","answer":"なかなか答えは難しいところではあるのですけれども、それが区として最も大きく世間に発表できるやり方、タイミングだとは思っております。そこに向けてしっかりとアピールしていく、そういったところを取り組んでいるところです。","id":"exchange-042"},{"speaker":"西本委員","kind":"質問・要望","question":"実態はどうでしょうか。改心した、職場の環境がよくなったというような、そういうのをどのように測っていくのかということを教えてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-043"},{"speaker":"西本委員","kind":"質問・要望","question":"応じないという方に対してどういう説得をして改善を求めていくのか、どういうことをされているのか、お聞きしたいと思っています。これは要望したいと思います。","respondent":"宮尾人事課長","answer":"例えば、場合によっては相談があることを伏せた上で指導していただくとか、そういった対応も取っております。ですので、相談者のご意向と、それから、我々がそれを受けて、その条件の中でできることを見極めながら、１件１件丁寧に取り扱っているところです。","id":"exchange-044"},{"speaker":"西本委員","kind":"質問・要望","question":"企業、事業所も一緒です。やはり丁寧な、一人一人仕事が十分にできるような環境をぜひやっていただきたいと要望して、終わりたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-045"},{"speaker":"須貝委員","kind":"質問","question":"こういう行動は慎んでくれと言う段階で、そこで庁内で、やはり管理職である程度その人を特定できてしまうのではないのでしょうかね。注意喚起をするということは、そこから被害者が特定されやすい状況を生むのではないかと思うのですが、その辺についてご見解を説明するよう求めました。","respondent":"宮尾人事課長","answer":"ただ、私が相談者であるということが分かってしまうということを、すごく慎重にお考えになります。日々模索、あるいは工夫をしながら、相談の対応をさせていただいているところです。","id":"exchange-046"},{"speaker":"須貝委員","kind":"意見","question":"それと、もう一点、今、課長、部長ぐらいまではいいですが、今度、副区長、区長という場合もあるわけですよね、ゼロではないので。ある中間で止まってしまうのではないかという可能性、危険性も思うのですが、その辺についてどう思われますかとの意見を述べました。","respondent":"宮尾人事課長","answer":"真摯に対応をして、そして再発防止に努めていく、この考え方というのは一貫して常に持っているつもりです。誰もが気持ちよく、自分の仕事に誇りを持って働いていただけるように、環境づくりに努めてまいりたいと思っています。","id":"exchange-047"}]},{"id":"topic-08","title":"行政視察","agenda":"行政視察","exchanges":[{"speaker":"石田（秀）委員長","kind":"質問・要望","question":"視察先で特に質問や確認したい事項、ご要望等がございましたら、現地にてご発言をほしいと求めました。〔「質問をしていいですか」と呼ぶ者あり〕。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-048"},{"speaker":"山本委員","kind":"質問・要望","question":"行政視察の視察先の選定について、少し確認をさせていただきたいということになります。私自身がいろいろな都市と交流を進めるべきだと思いながらも、この３か所の決まり方、お考えをお聞かせいただきたいです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-049"},{"speaker":"山本委員","kind":"質問","question":"改めてになりますが、ご説明をお伺いできてよかったです。ありがとうございました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-050"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/787454?Template=document&Id=7187#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=5&TermStart=2025-01-01&TermEnd=2025-12-31"}],"sourceMeta":{"pages":0,"characters":51365,"voices":147}},{"id":"r07-20250925-21","meetingId":"r07-cm09","date":"2025年9月25日","dateIso":"2025-09-25","committee":"子ども若者支援・共生社会推進特別委員会","time":"午前１０時００分～午後 ２時４８分","status":"正式会議録","sourceType":"formal","overview":"子ども若者支援・共生社会推進特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を26件整理しています。","topics":[{"id":"topic-01","title":"特定事件調査","agenda":"特定事件調査","exchanges":[{"speaker":"西村委員","kind":"質問・要望","question":"一つ伺いたいのが、改めて教えていただきたいのですが、改めて伺いたいなというふうに思います。何が原因でほかの自治体ではトラブルになっているのですかというような率直なご質問もあって、どのようにお考えかを改めて伺えればと思います。","respondent":"佐藤保育事業担当課長","answer":"まだ１か所、しかも昨年度から実施、お仕事をされている方がほとんどですので。次に５歳児健診の今後の進め方ですが、今年度、モデル実施を区のほうでも実施させていただいておりまして、１２の施設で今まさに実施しています。","id":"exchange-001"},{"speaker":"西村委員","kind":"質問・要望","question":"５歳児健診を経て８人から２６人に療育に来てくださる方が増えて、これは大賛成ですというようなご意見もあったと思います。伺わせていただきたいなというふうに思うのと、もしご存じでしたら、お聞かせほしいと求めました。","respondent":"佐藤保育事業担当課長","answer":"葛飾区の方式の詳細については把握していないのですが、私の認識しているところで言いますと、心理士という、児童福祉心理司だと思うのですけれども、専門の方がそのようなスクリーニングに一定の関与をされているというのを記憶しています。","id":"exchange-002"},{"speaker":"西村委員","kind":"質問・要望","question":"巡回相談のご報告も今あった中で品川区で無理のない５歳児健診の運用というのをぜひこれから進めていただきたい。調査されたり、柔軟にやっていけるような健診をつくれるのではないかという思いもありますので、ぜひお願いをしたいというふうに思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-003"},{"speaker":"鈴木委員","kind":"質問・要望","question":"区立保育園における特別支援保育の取組というところで、この専門チームというのは全ての園でつくられているという状況になっているのでしょうか。そういうものの研修というのが保育士の中でどこまでされているのかな、その点についてもちょっとお知らせほしいと求めました。","respondent":"染谷保育施設運営課長","answer":"特別支援保育研修が全てで、いわゆるコースとしては５種類ありまして、クラス運営における実践に関する研修というような構成になっております。現状、区に勤務している保育士のうち９０％の職員がそちらの初級の研修については受講しているという状況です。","id":"exchange-004"},{"speaker":"鈴木委員","kind":"質問・要望","question":"嘱託医による巡回相談というのは、これは年１回の巡回相談ということになるのか、そこら辺の回数についても教えてほしいと求めました。臨床発達心理士による巡回相談というのは３９園で延べ３９０人ということなので、具体的なところをお聞かせいただけたらと思います。","respondent":"佐藤保育事業担当課長、染谷保育施設運営課長","answer":"そのような研修を受けて特別な支援が必要なお子様に対応されていると考えております。保護者の方の同意を得られるかどうか等々なども含めて保健所と連携しながら対応していきたいなというふうに考えているところです。 区立においては今、学校心理士の方が３名の方で構成して巡回相談をさせていただいているというような状況です。その後、各園平均いたしまして５回実施をしているというところがありますので、令和６年度の実績におきましては。","id":"exchange-005"},{"speaker":"鈴木委員","kind":"質問・要望","question":"何園に対して、その加配の保育士というのは、そのための研修というのはその発達障害のお子さんとかに直接ついて支援をするという形になるわけですね。そういうことで、研修というのは受けるという仕組みになっているのか、その点についてもお聞かせほしいと求めました。","respondent":"染谷保育施設運営課長、佐藤保育事業担当課長","answer":"そのうちの区立保育園につきましては、令和７年度の認定児童数として４１５人というところになっております。５時間、６時間というような時間の区分での職がございまして… 私立の状況についてご説明します。午前中はこの先生、なかなか把握することはできないのですけれども、基本的には１対１で保育についていただいているというような状況です。","id":"exchange-006"},{"speaker":"鈴木委員","kind":"質問・要望","question":"何というのですか、５歳児健診で指摘されたけれども、本当に不安ばかりになると思うのです。そこのところが求められていると思うのですけれども、その点に対してはどのようにされていくのかということについても伺います。","respondent":"染谷保育施設運営課長","answer":"区立園における特別支援、児童への加配が１対１かです。その加配の職員が対応するというところはあるかと思うのですけれども、最終的に加配の職員につきましては、そういう考え方で現在運用をしています。","id":"exchange-007"},{"speaker":"鈴木委員","kind":"質問・要望","question":"前のときでも児童発達支援、また、この５歳児健診をやることによってかなりそういう明確になってくる部分というのがあると思うのです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-008"},{"speaker":"澤田委員","kind":"質問・要望","question":"私からはまず伺いたいことが、保護者の発達障害への理解についてですが、現在、保育園のほうではどのような取組を行っているとか、もしあれば教えていただきたいです。","respondent":"染谷保育施設運営課長","answer":"育児相談会というものを各区立・私立の保育園に通っているお子さんの保護者の方に実施しております。この２つが全体の相談の大半を占めているというような状況ですので、そういったところを通じて保護者の方の支援を保育園としては実施しています。","id":"exchange-009"},{"speaker":"澤田委員","kind":"質問","question":"私の質問の仕方が悪くて申し訳ないのですけれども、絵本を置いてある、本を置いてあるみたいなこととかは特にそういうのはやっていらっしゃらない感じか尋ねました。","respondent":"染谷保育施設運営課長","answer":"保護者の方からご相談を受けた中で専門機関のほうにおつなぎするというような対応はさせていただいているところですが、そういったことに関しては、私が把握している中では実施していないというところで認識しております。","id":"exchange-010"},{"speaker":"澤田委員","kind":"質問","question":"保護者への対応の仕方ではないので、ちょっと私の質問がずれていて申し訳ありません。今後、それはいわゆる拠点校に近い形になると思うのですけれども、そういうものについて区としてはどうお考えか尋ねました。","respondent":"染谷保育施設運営課長","answer":"巡回相談の部分も先ほど、委員がおっしゃられたとおりで各園巡回を定期的に実施してです。保育所と訪問支援ですとか、現状、公立・私立ともに今後設置については検討していくものであるのかなというふうに認識しております。","id":"exchange-011"},{"speaker":"おぎの委員","kind":"質問・要望","question":"ちょうど今、補助を出して、また検証していくということですので、こちらの検証を見て、ぜひ人材確保のほうを進めてほしいと求めました。個人情報ですので、子育てに関して保育園からスムーズに小学校と子育てできるように、区としてはそういった枠組みみたいなのは現在あるのか尋ねました。","respondent":"染谷保育施設運営課長","answer":"中学相談に教育総合支援センター、特別支援保育に限ったことではありませんけれども、従前から進めている保幼小連携の事業の中でも実際に保育園とそれから学校との連携というのは密に取って実施をしているというところが現状です。","id":"exchange-012"},{"speaker":"鈴木委員","kind":"質問","question":"２人体制で見るみたいなことが書かれていたのですけれども、どういう体制でやっているのかということと、現状どうなっているのかを伺いたいと思います。","respondent":"染谷保育施設運営課長","answer":"委員がおっしゃられたような形で対応する医療的なケアについてを令和５年から大きく拡充いたしまして、今、午睡中の人工呼吸器の使用など。それから、現時点におきましては特に送迎といった形の対応はしてはおりません。","id":"exchange-013"},{"speaker":"鈴木委員","kind":"意見","question":"本当に令和５年からさらに拡充をしていただいて、ここまで保育園でも、そういうのを整えていただいているなというふうに思います。それは本当に、人工呼吸器は午睡中のみというふうなことですけれども、そういうことも今後に向けてご検討いただけたらなというふうに思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-014"},{"speaker":"つる委員","kind":"確認","question":"先ほどの西村委員の質疑で確認があって、当然、ハードの部分に課題がある。視察先では１日１０人というお話があったのですけれども、どういう広さというか、分かります。","respondent":"佐藤障害者施策推進課長","answer":"児童発達支援事業所の施設の基準のご質問というところで……。","id":"exchange-015"},{"speaker":"つる委員","kind":"質問","question":"園を利用されている方は５人というようなお話もあったわけですけれども、どのぐらいの広さであれば、よいのか。スペースがあれば、できるのかな、そこが分かれば説明を求めました。","respondent":"佐藤障害者施策推進課長","answer":"児童発達支援は、お子様１人当たりで中心となる発達支援を行うお部屋において、１０名に対して掛けるというようなところになります。六十とかそういった形で、受け入れるお子さんの人数にもよりますけれども、というような面積が必要になってくるところです。","id":"exchange-016"},{"speaker":"つる委員","kind":"意見","question":"で、また、保育園のあり方って見たときに今日のような形の併設の整備というのが必要なのかどうかという意味なのです。いや、これは別々でそこは別々になっていたほうがいいのかというのはその辺というのはまさにあり方なので、どんな感じなのでしょうとの意見を述べました。","respondent":"染谷保育施設運営課長","answer":"今後、就学前のお子さんの人口が減っていく中では当然、その定員を見直しをするといったタイミングというのは当然出てくるかと思います。今日、今後、そのときの状況によって検討するという内容のものになっていくのかなというふうに現時点では考えているところです。","id":"exchange-017"},{"speaker":"つる委員","kind":"質問","question":"ちょっと私も分からないのですけれども、今日は視察させていただいたことからしても、そういう施設のありようというのがどうなのかな。どうだってあると思うのですけれども、何かまたあれば、ぜひ説明を求めました。","respondent":"佐藤子ども未来部長","answer":"令和１１年以降もある程度、また一方で特別支援を含めた子どもの成長につながるようなあり方というのはますますニーズが上がると思いますので、その辺を見極めて両部でまた検討しながらニーズにしっかり対応していくような検討を進めていきたいと考えております。","id":"exchange-018"},{"speaker":"ゆきた副委員長","kind":"質問","question":"１１園で計１２名が在園しているというお話があったと思うのですけれども、この需要というのがどのぐらいあるのかが把握できるところでと思いました。","respondent":"染谷保育施設運営課長","answer":"そういった意味ではニーズについてはきちんと現状対応できるという状況にあるかと思いますし、申し訳ありません、ニーズにはきちんと対応できる状況にはあるかなというふうに考えているところです。","id":"exchange-019"},{"speaker":"ゆきた副委員長","kind":"質問","question":"私立保育園での医療的ケア児の受入れのそこの現段階を説明するよう求めました。","respondent":"佐藤保育事業担当課長","answer":"昨年度は１園、今年度も１園、研修の予定となっております。看護師の方でしたり、保育支援員の方、こういった方を雇用された場合の人件費への補助というのを用意しています。","id":"exchange-020"},{"speaker":"ゆきた副委員長","kind":"質問","question":"先ほどの中で受入れは三十数園、受入れの可能な状態というのはお聞きしましたけれども、申請自体はどのぐらいあるのかというようなところをもう一度お願いします。","respondent":"染谷保育施設運営課長","answer":"現状におきましてガイドラインで示している医療的ケアで対応が可能な項目に該当するお子さんについては原則、特別支援保育審査会の中で受入れをしているという状況にありますので、特別支援保育審査会においてその集団。","id":"exchange-021"},{"speaker":"ゆきた副委員長","kind":"質問","question":"今後、受入れをさらに拡充していくとしても、私立・区立含めて看護師の加配とか、専門的な研修に要する費用の予算も関係してくると思うのですけれども、今後、必要性に合わせて方向性についてお聞きできればと思います。","respondent":"染谷保育施設運営課長、佐藤保育事業担当課長","answer":"令和５年度におきまして痰吸引、今の体制のまま受入れ項目を現状の形で継続して実施していくかどうかというところについては受入れをする園の体制なども含めまして、今後引き続き検討をする内容かなというふうに考えております。私立についての状況ですが、私立は従来、看護師の方、雇用いただいた園に対しまして人件費の補助というのを実施しています。","id":"exchange-022"},{"speaker":"ゆきた副委員長","kind":"質問・要望","question":"１名の医療的ケア児を受け入れるのに受入れの園の体制の準備とそれぞれの役割の相当な業務があると感じられます。様々な課題がある中ですが、より一層医療的ケア児の受入れを進めてほしいと求めましたので、こちらは要望で終わりたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-023"},{"speaker":"西村委員","kind":"提案","question":"今回、保育園のあり方、今回は私立園が自ら認可園が独自の判断でこのような方法はどうかと区にご提案したものと思っているのですけれども。区内バランスを考えていただきたいなというふうに思いますので、ご意見があれば、お考えをお聞かせほしいと求めました。","respondent":"芝野保育入園調整課長","answer":"進めていきまして、改築と合わせて、またどういう施設が必要なのかというのもしっかり検討していくと。こちらも引き続き、引き続き公私のバランスというか、役割分担につきましてもしっかり検討してまいりたいというふうに考えております。","id":"exchange-024"},{"speaker":"西村委員","kind":"質問・要望","question":"ありがとうございました。区が主導でぜひ引っ張っていっていただきたいという思いで質問させていただきました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-025"},{"speaker":"せお委員長","kind":"質問","question":"ないようでしたら、私から１点ご質問します。そういったところで、そういったところも含めて今後の改築や改装していく上での考え方というか、そこをお聞かせいただければと思うのですけれども。","respondent":"芝野保育入園調整課長","answer":"今後の複合施設の考え方ですね、そちらのほうが出た段階で企画課のほうでしっかりとあり方は検討させていただきたいですが、こちらのほうを引き続き模索していきたいというふうに考えております。","id":"exchange-026"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/404196?Template=document&Id=7189#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=21&TermStart=2025-01-01&TermEnd=2025-12-31"}],"sourceMeta":{"pages":0,"characters":23895,"voices":66}},{"id":"r07-20250925-20","meetingId":"r07-cm09","date":"2025年9月25日","dateIso":"2025-09-25","committee":"ＳＤＧｓ推進・行財政改革特別委員会","time":"午前１０時００分～午後 １時５１分","status":"正式会議録","sourceType":"formal","overview":"ＳＤＧｓ推進・行財政改革特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を43件整理しています。","topics":[{"id":"topic-01","title":"特定事件調査","agenda":"特定事件調査","exchanges":[{"speaker":"あくつ委員","kind":"提案","question":"当然それは提案ですから、区長の中の事業提案という中で、それに関して、私は少し危機感を覚えたのです。この１０番目の子ども食堂に関するテーマ、その提案者とかの方たちは、意見交換はされたのか尋ねました。","respondent":"井添ＳＤＧｓ推進担当課長","answer":"事業化を進めるべきかどうかを検討いたしまして、決して１０名の者が事業化前提に、あそこまで構築したものではないということは申し伝えておきます。第２回の検討会から実際に入って、リバースメンターのフォローですとか質問の対応とかしてまいりましたので、私ども企画課から。","id":"exchange-001"},{"speaker":"あくつ委員","kind":"提案","question":"ということでの今、確認をしたという認識です。すばらしい提案だったがゆえに、大人の意図が入り込んでいたら困るというところでの質問、承知いたしましたとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-002"},{"speaker":"安藤委員","kind":"質問・要望","question":"それぞれの専門家という意味なのかを伺いたいのと、１つの客観的な事実として、中高生とか男女の比率はどうだったのか。そもそもの募集ですけれども、どのように行って、応募された方の主な動機、何かそういった辺りがもしあれば教えてほしいと求めました。","respondent":"井添ＳＤＧｓ推進担当課長","answer":"それぞれのテーマの専門家に入っていただくことも検討したのですけれども、新聞社ですとか、大学教授の方などに携わっていただいております。ヒアリングの中では１名もいらっしゃらずに、自分たちで、学校から渡されたチラシを見てというように聞いているところです。","id":"exchange-003"},{"speaker":"安藤委員","kind":"質問・要望","question":"ご説明を聞けば聞くほどすばらしい事業だと思ってしまいます。１６名というのは若干少ないと思うのですが、最後まで努力していただきたいですし、次年度以降も発展させてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-004"},{"speaker":"新妻委員","kind":"質問","question":"すばらしい、そういうことというのはレクチャーがあったのですかと聞いたら、本当にすごいメンバーがここに集われているのだということを感じました。お伺いしたいのが、検討会が４回行われる中で、そこら辺を少し教えてほしいと求めました。","respondent":"井添ＳＤＧｓ推進担当課長","answer":"区立学校の方から１名ご応募があったのですが、こういう形で実施したということ、区立学校も含めて広く周知してまいりたいと考えています。","id":"exchange-005"},{"speaker":"新妻委員","kind":"質問・要望","question":"区立中学校の方からもぜひ応募をいただけるような周知を進めてほしいと求めましたし、継続して、よろしくお願いいたします。９月以降に事業化へ向けた検討実施とありますが、１０テーマありますけれども、もう少し今後の流れを教えてほしいと求めました。","respondent":"井添ＳＤＧｓ推進担当課長","answer":"リバースメンター１０名と、区長、教育長との意見交換のような場を設けることを現在検討しております。区での検討がどのようになされて、全て、きちんとそこはフィードバックしていけるように準備を進めたいと考えています。","id":"exchange-006"},{"speaker":"新妻委員","kind":"提案","question":"すごく大事な視点だと思います。今回提案をいただいた皆様にお伝えいただくということは非常に大事なことですし、できなかった、引き続きとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-007"},{"speaker":"こしば委員","kind":"質問","question":"テーマは１０項目ありまして、そこの辺りでお聞きしたいと思うのですけれども、そういったことをすごく綿密にされていたのです。調整がどうしても必要になってくると思うのですけれども、そこまではないかもしれないですが、考えについて教えてほしいと求めました。","respondent":"井添ＳＤＧｓ推進担当課長","answer":"今回の提案の中で地域に根づいた提案も何件かありますので、今後その地域との連携の仕方とか折衝の場があるのかというようなご質問をいただきました。","id":"exchange-008"},{"speaker":"こしば委員","kind":"質問・要望","question":"ぜひ、その辺、地域の未来に関わってくるわけですので、それが場合によっては、地域で活動する団体の声がまた大きくなってしまうと、それは本来の趣旨にもまた外れていってしまいかねないのですけれども、そこはぬかりなく、調整して進めてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-009"},{"speaker":"あくつ委員","kind":"提案","question":"そもそもそういうご提案だったのか、その辺が私はどうしても気になる、それを大人が恣意的に利用してはいけないと私は思っているのです。要するに、もう最初からこういうご提案だったということなのかどうか、確認させていただいてもいいか尋ねました。","respondent":"井添ＳＤＧｓ推進担当課長","answer":"そこの作文の内容の中に、最終的に提言内容に記載されているような令和８年度の品川区長選挙という言葉は一言も出てきておりません。","id":"exchange-010"},{"speaker":"あくつ委員","kind":"提案","question":"公開討論会、公開討論会を区が主催するというのはできないでしょうが、行政側ですから。事業提案しましたということになってしまうと、それはないということなのでしょうけれども、そこのところだけはないということを確認させてくださいとの意見を述べました。","respondent":"久保田企画経営部長","answer":"私もほとんどの検討会に出ていましたけれども、検討していく過程の中で、それだけは私から明言させていただきたいと思います。考え、至ったものと我々は認識していますし、予算として提案をさせていただきたいと考えています。","id":"exchange-011"},{"speaker":"あくつ委員","kind":"質問・要望","question":"特にこの選挙という部分に関して、ほかもそうですけれども、かなりセンシティブなものを含んでいます。そういうところはきちんと配慮した上での予算の編成はしっかり行っていただきたいということは最後に申し上げておきます。","respondent":"久保田企画経営部長","answer":"我々もその辺については、委員のご指摘を踏まえまして、しっかりと肝に銘じで対応していきたいと考えております。どうぞよろしくお願いいたします。","id":"exchange-012"},{"speaker":"まつざわ委員","kind":"提案","question":"本当に提案者はどういう意図があるのかというのが分からないと思っていたので、あと１回でしたか、何というのだろう。ＳＮＳとかで大々的にやっていくべきだとすごく思っていて、ほかの中高生にもいい刺激になると思うのですけれども、そこら辺はいかがか尋ねました。","respondent":"井添ＳＤＧｓ推進担当課長","answer":"子ども育成課で取り組んでおります品川区こども会議がございまして、広報しながわで、区民の皆様に周知をする機会を設ける予定をしています。現在、検討会の経緯などについて写真とともに掲載をしておりますので、見ていただけるようなことを検討してまいりたいと考えております。","id":"exchange-013"},{"speaker":"山本委員","kind":"提案","question":"幾つかご質問をさせていただきたいのですけれども、区立学校の方が１名、もし分かったら教えていただきたい。もう１つ、取り入れられるかどうかが決まってきたタイミングで、併せて説明を求めました。","respondent":"井添ＳＤＧｓ推進担当課長","answer":"こちらについては、来年度に向けて、さらに検討を進めてまいりたいと思います。きちんと公表できるように、今後、見せ方等の検討を進めてまいりたいと考えております。","id":"exchange-014"},{"speaker":"山本委員","kind":"提案","question":"１回やって終わりではなくて、この品川区政に政策提案、さらに広げていくことをしていただくのがいいと思っています。ＯＢ的なつながりを残すということと、次年度以降も参加者に体験談を言ってもらうことでの関わり方を模索するのがいいだろうとの意見ですとの意見を述べました。","respondent":"井添ＳＤＧｓ推進担当課長","answer":"第１回の検討会ですが、今年度のリバースメンター１０名の継続的な関係性が築けるようなことも含めて、事業の検討を進めてまいりたいと思います。","id":"exchange-015"},{"speaker":"まつざわ委員","kind":"質問・要望","question":"ＡＩ、ＧＸというのは専門的なものがすごく多い中で、これを審査する専門員がいるのでしょうか。そこの確認をお願いします。","respondent":"井添ＳＤＧｓ推進担当課長","answer":"２年目となりまして、事前に説明会なども行った結果、より具体化したものであったと捉えております。添付資料などの技術の、ほかとの差別化はどこなのかといったところ、その辺りは総合的に各委員の皆さんに判断をしていただけたかと考えております。","id":"exchange-016"},{"speaker":"まつざわ委員","kind":"質問・要望","question":"果たしてどのように審査したのかというのが１点と、そうすると、素人ながらにそういうことを思ったので教えていただきたい。２年目の事業者が２社いて、何かそこら辺が少し分かりづらかったので、簡単に説明していただけるとありがたいです。","respondent":"井添ＳＤＧｓ推進担当課長","answer":"２年目の５番目、６番目、２年目までは同じ事業で継続して応募ができる。３年目からは、昨年から２事業者とも、自走に向けて少し工夫をした上でのご提案をいただいたところです。","id":"exchange-017"},{"speaker":"あくつ委員","kind":"提案","question":"先ほどのご説明の中で何か応募したような雰囲気がありましたけれども、そこについてもう１回確認させていただきたい。１番目は簡単に言ってしまうと、安否確認ができますというものはそもそもやっていて、それを実証実験したいというご提案だと思うのですけれどもとの意見を述べました。","respondent":"井添ＳＤＧｓ推進担当課長","answer":"各種計画や計画事業を把握した上で審査に取り組むようにというところにつきましては、書類審査の段階で委員の方にご説明をしてまいりました。","id":"exchange-018"},{"speaker":"あくつ委員","kind":"質問","question":"何というのですか、相乗効果が出て、資金なども集まりやすくなると思います。この事業自体は成功してほしいと思っていますので、私からは以上です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-019"},{"speaker":"安藤委員","kind":"質問・要望","question":"それと、単純に選定事業の説明で、点数が書いていないのですけれども、それは書かないのですか。助成金の額の決め方について、事業費と助成金と書いていますが、こちらについてはどのように決まっているのか伺います。","respondent":"井添ＳＤＧｓ推進担当課長","answer":"区と同様に１０万円以上のものだと、相見積もりという形で複数の見積書を提出していただいています。そこに疑義が生じた場合には、再度、事業者に見積書の提出や根拠資料の提出などを求める場面もございまして、最終的に助成金額を決定したところです。","id":"exchange-020"},{"speaker":"安藤委員","kind":"質問・要望","question":"今回６つのうち５つが株式会社で、実際上、その点はどのようにお考えでしょうかというのが２点目です。そんなことができるのか率直に思ってしまうのですが、これはどういう事業なのか、もう少し教えてほしいと求めました。","respondent":"井添ＳＤＧｓ推進担当課長","answer":"改めまして、３点、ご質問をいただきましたのでお答えしてまいります。２点目の収益性とかを鑑みるに、株式会社とか以外の参入がなかなか難しい、手を挙げることが難しいというご指摘です。","id":"exchange-021"},{"speaker":"安藤委員","kind":"質問・要望","question":"様々こうした事業の選定に当たっては、専門的な知見をすごく大事にしていただきたい、これが意見と考えています。３年目以降のスキームを考えてもいいと思いまして、そうしたこともあるのと私は感じましたということで、意見で終らせていただきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-022"},{"speaker":"筒井委員","kind":"確認","question":"私からまず、中高生リバースメンター事業についてお伺いをしたいと思います。投票率９割を超すに当たり、所管や専門家の方に質問、その時点で気づかなかったのかを確認したいと思います。","respondent":"井添ＳＤＧｓ推進担当課長","answer":"それから所管から公職選挙法上の説明だとか、例えば１８歳未満の選挙運動が禁止されているですとか、投票日当日の選挙活動は禁止されてあります。","id":"exchange-023"},{"speaker":"筒井委員","kind":"提案","question":"提案としてなかった品川区長選挙とかが盛り込まれるというのはなぜか、事業化するために、そうしたことはやっていくつもりなのでしょうか。私の思いとしては、あまりにばっさり切るのもどうなのかと思っているので、その辺り、お考えを説明するよう求めました。","respondent":"井添ＳＤＧｓ推進担当課長","answer":"これまで調べたことなども含めて、打合せの場などセッティングしながら、事業化に向けた検討を進めてまいります。ただ、そのためにいろいろな手段があるといったことを含めて、これから所管と連携して事業化の検討を進めてまいりたいと考えております。","id":"exchange-024"},{"speaker":"筒井委員","kind":"提案","question":"やはり一生懸命提案していただいたので、なるべく丁寧に、提案してくれたお子さんたちにも納得できるようなご説明をしてほしいと求めました。今回２年目の事業につきましては、地域を盛り上げていっていただきたいという思いがあるのですけれども、その点はいかがお考えか尋ねました。","respondent":"井添ＳＤＧｓ推進担当課長","answer":"具体的に選定事業の２年目の一般社団法人めぐもりからの提案内容が、そこを選定する妥当性についてのご質問かと思います。区内全域に発展性として考えられるのかといった視点での質問などもなされておりまして、実際、プレゼンテーションの中でも示されたところです。","id":"exchange-025"},{"speaker":"筒井委員","kind":"質問・要望","question":"それは本当に、この事業の審査基準の対象事業の要件でもありますので、その辺り、しっかり審査していっていただきたいと考えています。それは先ほど安藤委員からもご質問がありましたが、ぜひ公表していっていただきたいと思っているのですが、その辺りいかがお考えか尋ねました。","respondent":"井添ＳＤＧｓ推進担当課長","answer":"実行委員会でも、こうしたご意見をいただいたということで、報告して検討してまいりたいと考えています。","id":"exchange-026"},{"speaker":"山本委員","kind":"質問","question":"私からも１点、ご質問します。今回、それぞれの事業者では、どのような成果目標を設定されているのかお伺いしてもよろしいか尋ねました。","respondent":"井添ＳＤＧｓ推進担当課長","answer":"各事業を、例を挙げてご説明しますと、意思決定期間の短縮についても平均３週間のところを３日まで短縮できることを指標として立てています。ＫＰＩは設定していますので、最終的に成果報告の段階では、それを目標達成できたのかどうかを評価してまいりたいと考えております。","id":"exchange-027"},{"speaker":"山本委員","kind":"質問・要望","question":"今日お聞きしなかったところも、それが妥当かどうかも、目標を決めていただいて進めていただくというのがよいと考えています。何でしょう、それを出すことで企業としての価値があると感じていただいて出せるようになったらいいと考えています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-028"},{"speaker":"こしば委員","kind":"質問・要望","question":"確認ですが、それがまた細分化されていくのか、その辺を教えてほしいと求めました。","respondent":"井添ＳＤＧｓ推進担当課長","answer":"令和６年度の当初予算として、ＳＤＧｓ推進事業補助金として議決いただけました５,０００万円を今、現在までに区から執行している金額です。","id":"exchange-029"},{"speaker":"こしば委員","kind":"質問・要望","question":"２年目を迎えた一般社団法人めぐもりのプロジェクトですが、また、本来で言えばそういったところの話になってくると思うのです。その辺はどのようにお考えなのか、また、今後どういう見通しをつけているのか教えてほしいと求めました。","respondent":"井添ＳＤＧｓ推進担当課長","answer":"２年目の取組で、より発展して取り組んでくださるところですので、そして地域とも連携してできればいいと考えています。今のところはこちらで線引きをするようなことは考えていないのですけれども、今後、その辺りも含めて検討してまいりたいと思います。","id":"exchange-030"},{"speaker":"こしば委員","kind":"質問・要望","question":"それは本来の趣旨と全くかけ離れていってしまうので、そこは調整、共有をしてほしいと求めました。お願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-031"},{"speaker":"安藤委員","kind":"質問","question":"目的で、この区民の幸福（しあわせ）の視点というのは、つまりどういう視点なのか伺いたいというのが１つです。なぜ今は空白になっているのでしょうかというのをお伺いしたいのと、評価の基準、何をもってＡからＤを決めるのか伺います。","respondent":"吉岡政策推進担当課長","answer":"３点、ご質問をいただきました。重点的に実施すべきものがあれば、このまま継続してくるようなものはＤという評価をするというところで、あるいは取組。","id":"exchange-032"},{"speaker":"安藤委員","kind":"質問・要望","question":"どの辺を重要視して決めるとか、先ほど説明いただいた項目に基づいて何か評価基準ですか、もう一度説明ほしいと求めました。今年はスポーツということでしたが、この政策の選定を行っているのはどなたで、その選定の基準は何かあるのか伺いたいと思います。","respondent":"吉岡政策推進担当課長","answer":"一方で、なかなかこういった課題が解決できない、あるいは、役割に応じていないというところであれば、そこがＤ評価につながっていくと考えています。１つ、一昨年度は防災環境、昨年度は地域社会という形で選定をしていたです。","id":"exchange-033"},{"speaker":"安藤委員","kind":"質問","question":"それと、区内関係団体の方が３人、選定されていると思うのですけれども、この選定の考え方も伺います。原則公開となっておりましたけれども、伺いたいと思います。","respondent":"吉岡政策推進担当課長","answer":"１回、２回が事前検討会で、こちらは非公開という形でやらせていただいています。５回目につきましては、提言ということで、政策評価委員の皆さんがまとめていく作業になりますので、こちらは公開で開催するものです。","id":"exchange-034"},{"speaker":"安藤委員","kind":"質問・要望","question":"そういうことでいいのかという確認と、この政策評価は１１月に昨年、新年度予算にどのように反映する方針を持っているのか伺いたい。それぞれについて、やるのですけれども、考え方として、区として、これをこのように反映する方針ですというのがあれば教えてほしいと求めました。","respondent":"吉岡政策推進担当課長","answer":"１名ずつにつきましては、それに興味がある方を募集しているということで、従前行っています。いわゆるＰＤＣＡサイクルのＣの部分ですので、次の予算に生かしていく、Ａにつなげていくという活用をしています。","id":"exchange-035"},{"speaker":"新妻委員","kind":"質問","question":"今年３年目でよろしいでしょうか。この３年を迎えた、まず、区の評価と、やった上でのよかったこと、また、課題、職員の負担等も含めた評価をお聞きしたいと思います。","respondent":"吉岡政策推進担当課長","answer":"いわゆる事業実施の中で、こういった１つのシートとして見える化をしたことによって、より改善につながっているというところを感じております。","id":"exchange-036"},{"speaker":"新妻委員","kind":"質問・要望","question":"そして、区長が掲げられたウェルビーイング予算は、区の予算の１％、約２０億円余りですか、そこの予算が捻出をされると。国の予算や東京都の予算の、そこをより多く活用するためには、どういうことが必要なのかという区のお考えがあれば教えてほしいと求めました。","respondent":"吉岡政策推進担当課長","answer":"幾つかのご質問いただきまして、順不同で対応します。やはりこういった予算がついていないところに関しては、所管だけでなくて、国ですとか都と取っていく必要があるとは認識をしています。","id":"exchange-037"},{"speaker":"新妻委員","kind":"質問・要望","question":"１つの課だけで見るのではなくて、そこはうまく、しっかり連携をしてほしいと求めました。公募区民の方は公募だと思うのですけれども、大学生に関しては、どういう形で入っていただいているのかを教えてほしいと求めました。","respondent":"吉岡政策推進担当課長","answer":"大学につきまして、その年々でお願いする大学、いわゆる連携協定を結んでいる大学にお願いしていまして、今年度は立正大学の学生にお願いしています。ご推薦をいただくという形で、男性１名、女性１名の選出をいただいたです。","id":"exchange-038"},{"speaker":"新妻委員","kind":"質問","question":"名前だけ載せているということではなくて。若い方たちの意見を反映させるように発言をいただくことが大事だと思うのですが、実際にこの方たちは発言をしっかりいただいているのか尋ねました。","respondent":"吉岡政策推進担当課長","answer":"この政策評価委員、委員長を入れて１１名ですが、委員おっしゃるとおり、そういったところの懸念を解消するために、ある程度人数を絞ってやっていまして、今年度も昨年度もそれまでも、大学生の皆さん、活発にご議論いただいているところです。","id":"exchange-039"},{"speaker":"まつざわ委員","kind":"質問","question":"３年たって、３年たって、ゼロベース方式というのがあるのです。６５２事業全部ではなくて、ゼロ査定から１から落としていくやり方だと、そういうのは分かるものなのか尋ねました。","respondent":"吉岡政策推進担当課長","answer":"１年目に比べると、１年目は１から作り出さなくてはいけないので、それに比べると負担感は減ってきているところではあります。いわゆる改善・見直し事項が出てこないと、何かそういった委員のご提案も含めて、変えていく必要があるだろうとは認識しております。","id":"exchange-040"},{"speaker":"まつざわ委員","kind":"意見","question":"３年か５年で事業をこうやって終了させて、スクラップ・アンド・ビルドでもう新しいのばかりやっていて、事業をなくすのはなかなか大変です。例えばＣ評価が２年続いてしまったら、少し違うものなのか、そのお話を聞きたいと思いますとの意見を述べました。","respondent":"吉岡政策推進担当課長","answer":"評価軸を変えてというご提案だと考えております。なかなかそういった一律の数字だけで見るのは難しいと認識をしていますが、事業をしっかり見直すような体制は非常に重要だと思っています。","id":"exchange-041"},{"speaker":"まつざわ委員","kind":"意見","question":"何かいろいろなことをやりながらも、また、自分たちに過度な負担がかからない何かいい方法を一緒に見つけていけたらと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-042"},{"speaker":"筒井委員","kind":"質問・要望","question":"いよいよ３年目を迎えたということで、それをつくってほしいという、非常にいいことだと考えています。前年度は６６９事業、今回６５２事業で減ったのですけれども、６６９事業から６５２事業になった理由を示すよう求めました。","respondent":"吉岡政策推進担当課長","answer":"昨年度の事務事業評価を実施した予算事務事業が６６９事業で、今回６５２事業ですので１７事業差分があります。２つの事業が統合して１つの事業になったとか、令和６年度から開始した新規事業がありますので、その差で１７事業減ったです。","id":"exchange-043"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/579883?Template=document&Id=7213#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=20&TermStart=2025-01-01&TermEnd=2025-12-31"}],"sourceMeta":{"pages":0,"characters":53737,"voices":111}},{"id":"r07-20250926-22","meetingId":"r07-cm09","date":"2025年9月26日","dateIso":"2025-09-26","committee":"まちづくり・公共交通推進特別委員会","time":"午前１０時００分～午後 ０時０８分","status":"正式会議録","sourceType":"formal","overview":"まちづくり・公共交通推進特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を35件整理しています。","topics":[{"id":"topic-01","title":"特定事件調査","agenda":"特定事件調査","exchanges":[{"speaker":"田中委員","kind":"質問・要望","question":"これこそ新庁舎を建てるに当たって、求められる成果というか効果だと感じています。新たな価値とはどういうことを指されているのか、まずはお聞かせほしいと求めました。","respondent":"三井新庁舎整備課長","answer":"今後、そういったコミュニケーションを活性化していくため、検討を進めているところです。今後進めてまいりながら、まさに委員がおっしゃっているとおり、新庁舎移転をきっかけに事務機能の強化を進めてまいりたいと考えております。","id":"exchange-001"},{"speaker":"田中委員","kind":"質問・要望","question":"何が求められるのかはあれですけれども、交流によってお互いに刺激し合って、活性化された職場をつくっていく。今の段階での想定されているものがあればお知らせをほしいと求めました。","respondent":"三井新庁舎整備課長","answer":"品川区もこの新庁舎移転を機に、窓口ＤＸ化を進めることを方針として掲げておりまして、全体を調整していかなければいけないと考えています。","id":"exchange-002"},{"speaker":"田中委員","kind":"質問・要望","question":"今１３地域センターありますが、それぞれの地域センターと本庁舎との連携について、お聞きします。","respondent":"三井新庁舎整備課長","answer":"実際にシステムを更新するということになりますと、どういった形で連携ができるかというのは考えていく必要があるのかなと考えています。地域センターで実施する内容も多岐にわたりますので、関係の窓口部署と引き続き連携を図りながら検討していきたいと考えています。","id":"exchange-003"},{"speaker":"田中委員","kind":"質問・要望","question":"ぜひ地域振興部とも連携していただきたい。新庁舎に限定せず、オール都庁というかオール区役所として、窓口も含めた対応を取ってほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-004"},{"speaker":"塚本委員","kind":"質問・要望","question":"ＺＥＢとＣＡＳＢＥＥですかね、ＺＥＢが今回の本庁舎で１２施設目、この規模の建物としては。そういった認証が取れたことは物すごくすばらしいことだとは思っているのですが、そこについてご説明をお願いしたいと思います。","respondent":"小林新庁舎建設担当課長","answer":"当然、これは乖離がないように、建物ができた後も数値を確認できるようなシステムを導入する予定です。運用上の状況も含めて、設計者と我々の中で管理をしていきながら、より適切なＺＥＢの施設の運用に努めてまいりたいと考えているところです。","id":"exchange-005"},{"speaker":"塚本委員","kind":"質問","question":"そのチェックというのは、ＣＡＳＢＥＥとかＺＥＢの認定に影響があるのですか。極端な言い方をすると、数値が悪いと認定は取消しみたいな、そういう事後のチェック機能みたいなものも、この認定の中にはあるのか尋ねました。","respondent":"小林新庁舎建設担当課長","answer":"区としては認証を取得することが目的ではなくて、実運用の中でしっかりと成果を出していくことも大事なところかと思ってあります。施設によっては結果をホームページ上で公開しているところもありますので、そういった対応も含めて検討してまいりたいと考えています。","id":"exchange-006"},{"speaker":"塚本委員","kind":"質問・要望","question":"それから、もう一点、防災計画のところで、先日の木曜日、９月１１日の大雨のことで伺います。浸水を防ぐ、あるいは排水で何とか全部水を外に出していく、こういう対策がどこまで取られているのかというところをちょっとお伺いしたいと思います。","respondent":"小林新庁舎建設担当課長","answer":"さらに、防潮板については５０センチありますので、合わせると１メートルちょっとの浸水であれば地下に流れない仕組みになってあります。さらに、当然ポンプとかを設置して排水する機能を設ける必要があるかと思ってありますが、様々そのような対策を設けることによって。","id":"exchange-007"},{"speaker":"塚本委員","kind":"確認","question":"１階部分が周りの道路よりも少し高いということで、周りからは入ってこない。道路より１階が高ければ水は基本的には入ってこないだろうという想定で大丈夫ということなのでしょうかというのを、もう一回確認したいと求めました。","respondent":"小林新庁舎建設担当課長","answer":"敷地内につきましても、強い雨、今回の設計でいきますと時間１２０ミリの雨に対して排水可能なしつらえとなっています。先ほど申し上げたとおり、敷地内につきましても、時間１２０ミリまでは耐えられるような設計になっているといったところです。","id":"exchange-008"},{"speaker":"若林委員","kind":"質問・要望","question":"２週間ぐらい前に議会として、二言、ご要望とかがあったように記憶をしております。聴覚障害者の方への配慮、いわゆる合理的配慮についても一言、今の段階で言えること、お考えを、示すよう求めました。","respondent":"小林新庁舎建設担当課長","answer":"本来であれば音声案内で流れるところですけど、それを視覚で表して見ることができないかというところで、光警報装置というのを今回導入する予定です。トイレの中にそういったものを設置することによって、災害時、広く検討しています。","id":"exchange-009"},{"speaker":"えのした委員","kind":"質問・要望","question":"やはり新庁舎建設に当たっては、安全第一ということで、進めていってほしいと求めました。これ、何か具体的に、また新しい取組等あれば説明を求めました。","respondent":"小林新庁舎建設担当課長","answer":"まずは安全で工事を進めなければいけないところがありますので、我々も当然ながらその管理をしっかりと行っていきたいと考えているところです。","id":"exchange-010"},{"speaker":"えのした委員","kind":"質問・要望","question":"これ、まだ国の話ですけれども、各自治体でも広げていければということで、この辺、もう何か区としてお考えありますでしょうか。説明を求めました。","respondent":"小林新庁舎建設担当課長","answer":"そのための対応も、熱中症に対する対応というところでも一定程度、我々は経費を見ていきながら発注をしています。適切な時期にきちんと工事をまとめていただくというところをしっかりと管理してまいりたいと考えているところです。","id":"exchange-011"},{"speaker":"石田（秀）副委員長","kind":"質問・要望","question":"ウェルネスオフィスもどこを中心として、Ｓランクになれたのかというところをまず教えてほしいと求めました。建築から説明を求めました。","respondent":"小林新庁舎建設担当課長","answer":"何か１つというところではなかなか難しいところですが、一つ一つの積み重ねでこのような結果になったかなと思ってあります。令和１０年度頃に工事が始まる時期ですので、今後も情報収集し、より高めてまいりたいと思っているところです。","id":"exchange-012"},{"speaker":"石田（秀）副委員長","kind":"質問","question":"その辺のからくりをもう少し教えていただければありがたいと思います。電力を稼ぐほうと省エネで使わないほうをどういうふうにされてここまで来たのかというところだけもう１回説明を求めました。","respondent":"小林新庁舎建設担当課長","answer":"そもそも床面積が非常に大きな建物ですので、太陽光をどこまで設置してどこまで効果的かというところはなかなか難しい部分があるかと思ってあります。","id":"exchange-013"},{"speaker":"石田（秀）副委員長","kind":"質問・要望","question":"今伺って、１％というのはえっと思ったけれども、そんなものなのだなと思いました。","respondent":"三井新庁舎整備課長","answer":"現在、オフィスレイアウトの調整をしている段階で、これから待合スペースをどういうふうにするかという具体的な検討を進めていく段階になります。これについては本当に検討を始めた段階になりますので、新庁舎移転までに量を減らしたいと考えているところです。","id":"exchange-014"},{"speaker":"石田（秀）副委員長","kind":"質問・要望","question":"先ほど言ったようにイトーキも、あそこで伺ったら、これをやったのはいいけれども、実際動き出してから３年かかったというわけです。スペースはあるわけだから、私はある程度柔軟性を持っていたほうがいいと思うのだけれども、その辺も併せて教えていただきたい。","respondent":"三井新庁舎整備課長、小林新庁舎建設担当課長","answer":"今、各課とフロアのレイアウトを調整し始めた段階で、現実問題、スペースが取れないということが一番大きい問題になっております。実施設計概要に書かせていただいていると思うのですが、現実的にはなかなか厳しいのではないかなと… 実際に所管も今それに向けた検討を進めているところでございまして、いわゆる競合他社がやはり入ってくる懸念というのはあるかと思ってあります。","id":"exchange-015"},{"speaker":"田中委員","kind":"質問・要望","question":"まず基本的な考え方の確認ですけれども、今回サウンディング調査ということで１３の民間事業者、建設関係の業者の意見を聞いたということです。ここは、財務の視点の内容がほとんどない状態なのですが、そこはどういうふうな対応をされるのかというところをお聞かせほしいと求めました。","respondent":"泉広町事業調整担当課長","answer":"こちらの広町地区の開発におきましてはＪＲが開発を進めておりますけれども、前提条件については今まさに検討を進めている状況になってあります。","id":"exchange-016"},{"speaker":"田中委員","kind":"質問・要望","question":"今回、そこに限定したわけではないという、民間事業者からの意見も聞くという、そういう段階なのかなということで確認をいたしました。一つの意見として捉えていただいて、広く区民のご理解、ご納得をいただけるようないいプランにしてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-017"},{"speaker":"松本委員","kind":"質問","question":"そういうことを考えたとき、区の中でこの２００億円という一つの指標が今も妥当なのか、これをもう少し上げていかないといけないという話があるのか。そうした協議は区の中で行われているのかどうか伺います。","respondent":"泉広町事業調整担当課長","answer":"先ほど申し上げた金額といったところは今現在指標として考えてありますが、そういったことにもなりますので、精査している段階です。そういった状況ですので、まさに検討しています。","id":"exchange-018"},{"speaker":"松本委員","kind":"質問","question":"どういうふうに財源に充てていくかというのを考えていくと、高めれば高めるほど収益性のある施設になるというのはおっしゃるとおりかと思います。持っている資産を活用すれば、今後の区民の負担を下げることにもつながっていくわけですから、そこの部分はバランスを考えてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-019"},{"speaker":"石田（秀）副委員長","kind":"質問・要望","question":"幾つか伺いたいと思っています。不動産事業者といっても、例えば大手の不動産事業者だとするならば、もうちょっとそこら辺の内訳を教えてもらえればありがたい。","respondent":"泉広町事業調整担当課長","answer":"こちらは委員からお話がありましたとおり、なかなか業者のお名前は開示できないというところになってあります。なので過半数を超える方はそういったデベロッパーの方です。","id":"exchange-020"},{"speaker":"石田（秀）副委員長","kind":"質問・要望","question":"多分そういうことなんだろうと思いますけれども、この「等」というのは、何で「等」をつけたのかをあわせて教えていただきたい。は「等」というのはどういう想定であえて「等」とつけたのかというところもあわせて説明を求めました。","respondent":"泉広町事業調整担当課長","answer":"今回、この建設事業者等と書いているところが、いわゆるゼネコンと言われているところだということでご理解いただければです。かなりお名前が限定されてしまうことも考えられ得ることから、今回は等という形で少しまとめさせていただいているところがあります。","id":"exchange-021"},{"speaker":"石田（秀）副委員長","kind":"提案","question":"こういう提案をもっとちゃんとそれなりにやる意味のであれば、ここにこういうものがあるんだ、そういう経済効果を入れるべきだと思います。","respondent":"泉広町事業調整担当課長","answer":"そういったところも一つ重要な視点の一つとして、認識をしていただいているところになってあります。引き続きどういった示し方をできるかというところを含めて検討を進めてまいりたいと思ってあります。","id":"exchange-022"},{"speaker":"藤原委員","kind":"確認","question":"一つ確認をしたいんですが、指標が２００億という形でしたよね。例えば毎年２０億ずつで１０年とか、１０億ずつで２０年とか、確認させていただけますか。","respondent":"泉広町事業調整担当課長","answer":"どういった形が適切なのか、今検討を進めているところになってあります。区の財政の状況も捉えながら、どういった形が適切ないただき方になるのかは検討してまいりたいと思ってあります。","id":"exchange-023"},{"speaker":"藤原委員","kind":"質問","question":"令和１１年に新庁舎が完成したとして、ここから引っ越して、その後に解体していくということでいいんですよねということ。現実にこの跡地がどうなったとなるのは、例えば１０年後とか、何かそういうのをつかんでいたら教えていただけますか。","respondent":"泉広町事業調整担当課長","answer":"解体をして進めていく視点で考えてあります。そこからまた新しい建物、令和１６年度の末ぐらいに本庁舎の跡のほうに建物ができてくる、そういう感覚で我々のほうは考えているところです。","id":"exchange-024"},{"speaker":"藤原委員","kind":"質問","question":"最後に数字的なことを伺いたいんですけれども、いろいろ変動はあると思うのですが、第二庁舎まで解体したとしたら、解体料はどのぐらい今の時点で考えているんか尋ねました。","respondent":"泉広町事業調整担当課長","answer":"まだ解体に関する基礎調査等々が終わっていない段階でございまして、まだ幾らぐらいかという試算がなされてないところもあります。今、単純に私どもの庁舎の面積で割りますと大体４０億円ぐらいのお金が必要になってくるのではないかというところで、そういった想定です。","id":"exchange-025"},{"speaker":"石田（秀）副委員長","kind":"質問・要望","question":"それもよく踏まえたほうが私はいいと思うので、そこら辺の状況もぜひ最新のものをとっていただいて、検討していただきたいなと。これは要望だけにしておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-026"},{"speaker":"松本委員","kind":"質問","question":"一応、８月からの収支を見ると、あまり影響がないように思われるのですけれども、ここはどう解釈すればいいでしょうか。お願いいたします。","respondent":"櫻木地域交通政策課長","answer":"子育て支援割につきましては、利用者数としては、８月以降少しずつ増えてきている状況です。多少影響はあったかとは思いますが、現在のところは、全体としては収支率は向上したです。","id":"exchange-027"},{"speaker":"松本委員","kind":"意見","question":"では、半額になっているわけですね。ある程度、収支の改善につながっているという理解でいいか、もう一度お願いいたしますとの意見を述べました。","respondent":"櫻木地域交通政策課長","answer":"委員ご指摘のとおりの推移と考えております。","id":"exchange-028"},{"speaker":"松本委員","kind":"質問","question":"令和７年度に考えると言っていたのが３年、令和１０年まで延長するということで、収支率の改善に向けた取組が書かれています。これまでの数年間を見ると、頑張ったとしても５０％というのは、現状の改善の方向性とか取組というのはどういうことが考えられるのか尋ねました。","respondent":"櫻木地域交通政策課長","answer":"１つは、やはり地道な周知に努めていって、ご利用いただく方を増やしていくことが大きなところかと考えています。アプリとの連携等も含めて、より使いやすいような工夫、改善策を考えていければいいかと考えています。","id":"exchange-029"},{"speaker":"松本委員","kind":"質問","question":"試行期間を延長するということであれば、むしろそこをやらないと、なかなかこの状況は改善しないのかとも思うのです。収支を考える上では、そこの部分も検討は必要ではないかと思いますが、いかがか尋ねました。","respondent":"櫻木地域交通政策課長","answer":"料金の割引の考え方です。一定、慎重な判断をしつつ、考えていくことになろうかと考えています。","id":"exchange-030"},{"speaker":"塚本委員","kind":"質問","question":"相当程度、運転手不足がもし解消されれば、バス事業者にとっては大きな経営の転換期みたいなことも訪れるのかというのも思ったのです。今日の資料には１行、現段階で本格導入みたいなものがどの程度見込まれるのかというのを一応お伺いしておきたいと思います。","respondent":"櫻木地域交通政策課長","answer":"自動運転技術につきましては、地方のほうで比較的導入が進んでおりまして、レベル４と言われるようなバスを運行している地域もあります。自動運転は地方のほうで少し実証運行をやられているということもありますので、その辺り、我々としても注視していきたいと考えています。","id":"exchange-031"},{"speaker":"塚本委員","kind":"意見","question":"移動手段の確保というのは、区の目指すウェルビーイングの大事な一要素だと思います。歳出等確保しながら進めていくべき分野なのかと思いますので、これは意見ですけれども、今後ともよろしくお願いしたいと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-032"},{"speaker":"田中委員","kind":"提案","question":"逆に、忖度しているがゆえに、京急バスのほうにそういう提案をしていないということなのか。今までの質疑の中でもう少し突っ込んでお伺いをしたいと思いますとの意見を述べました。","respondent":"櫻木地域交通政策課長","answer":"申入れをしてきているところでして、現時点では、なかなか使っていただくのは難しいという回答をいただいているところです。とはいえ、委員も含めて地域の方からもご要望を多々いただいておりますので、諦めずにこれからも申入れ、協議をしていきたいと思っているところです。","id":"exchange-033"},{"speaker":"田中委員","kind":"質問・要望","question":"今回、試行運行で、当初の計画であれば、大崎地区とか荏原地区にも、今回の実証結果を踏まえて導入するかどうかを検討するということでした。そのように捉えられるのですけれども、そういう背景があるから、なかなか大崎とか荏原地区には導入できないということなのか尋ねました。","respondent":"櫻木地域交通政策課長","answer":"大井地区の運行状況を踏まえて、大崎ルート、荏原ルートは判断するということで検討を行ってきたところです。説明させていただいたとおり、基本的には、やはり地域の状況というところが主立ったところです。","id":"exchange-034"},{"speaker":"田中委員","kind":"質問・要望","question":"４番目に、新たな地域で展開してほしいと求めましたが、より利用者にとって利便性の高い交通の導入につなげてほしいと求めました。これは要望で終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-035"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/676877?Template=document&Id=7215#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=22&TermStart=2025-01-01&TermEnd=2025-12-31"}],"sourceMeta":{"pages":0,"characters":41664,"voices":98}},{"id":"r07-20250930-4","meetingId":"r07-c-settlement","date":"2025年9月30日","dateIso":"2025-09-30","committee":"決算特別委員会","time":"午前 ９時３０分～午後 ５時３６分","status":"正式会議録","sourceType":"formal","overview":"決算特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を151件整理しています。","topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"筒井副委員長","kind":"質問","question":"１人当たりの質問時間は、２０分のいずれかとし、答弁時間も含めて１日につき１０分となります。残り時間がなくなった時点で振鈴を２回鳴らしますので、質問の途中でありましても、直ちに取りやめていただきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-001"}]},{"id":"topic-02","title":"以上で、決算統計上の数値および、財政健全化法に基づく各指標についての説明が終わりました。 それでは、令和６年度品川区一般会計歳入歳出決算","agenda":"以上で、決算統計上の数値および、財政健全化法に基づく各指標についての説明が終わりました。 それでは、令和６年度品川区一般会計歳入歳出決算","exchanges":[{"speaker":"まつざわ委員","kind":"質問","question":"この飛躍的な増収の主な要因をどのように分析されているでしょうか。その中で、ふるさと納税制度が果たした役割と、今年度の取組の状況、今後の可能性について説明を求めました。","respondent":"藤村総務課長、宮澤税務課長","answer":"私のほうで、一般寄附金というところで、今回の２５億９,０００万円余というところで収入があったところについてお答えいたします。方向性に共感を頂いて、区を応援したいというところで、こういったものを頂けたと考えております。返礼品を通じまして区内の魅力を発信するとともに、税外収入の確保、財源の確保の役割を果たしていると認識しています。","id":"exchange-002"},{"speaker":"まつざわ委員","kind":"意見","question":"昨年度の子育て支援の取組に共感し、子どもたちの未来のためといった２５億円の寄附です。要はいわゆるガバメントクラウドファンディングといったことや、寄附の対象といった拡大の取組を強化すべきと考えますが、ご見解を説明するよう求めました。","respondent":"宮澤税務課長","answer":"３事業でクラウドファンディングを展開していますけれども、区民の共感が得られやすい、各課と調整しながら積極的に進めていきたいと考えています。","id":"exchange-003"},{"speaker":"まつざわ委員","kind":"意見","question":"今年度から税務課にふるさと納税の専門部署が設置されたことは理解しています。全庁的に情報を集約して、また戦略的に取り組む司令塔というものを置くべきと考えますが、ご見解を説明するよう求めました。","respondent":"宮澤税務課長","answer":"ふるさと納税の取組は、今年度４月より専任の係を新設して取り組んでおります。","id":"exchange-004"},{"speaker":"山本委員","kind":"質問","question":"１人当たりの税収増でしょうか、人口増でしょうか。品川区では今後、２０５１年まで人口が増える見通しを立てておりますので、特別区民税は人口増に伴って増えていくという見通しか尋ねました。","respondent":"宮澤税務課長、加島財政課長","answer":"単純に区民の方々の総所得を世帯数で割り戻した数値、１人当たり、１世帯当たりの所得というところでも、やはり増加しているというところ。は収入率の増加ということで、そういったところが要因となって増収となっているところです。 私からは、財政調整交付金の状況についてお答え申し上げます。それから算定では、義務教育施設の建築工事単価の臨時的算定や区立児童相談所の開設などによります基準財政需要額が増となったことによるものです。","id":"exchange-005"},{"speaker":"山本委員","kind":"確認","question":"続いて、令和６年度決算において、翌年度への繰越額６７億円余とありますが、こちらはどのように扱うのでしょうか。概算額で結構ですので、均等割での徴収額を併せてお教えいただいた上でご見解を伺えればと思います。","respondent":"加島財政課長、宮澤税務課長","answer":"この理論に従いますと、我々は２分の１以上を積み立てていく、ないしは償還に充てていく必要があると考えているところです。令和６年度は国策として、定額減税に取り組んだところではありますが、減税を行う考えはございません。 住民税均等割につきまして、令和６年度は６億９,５００万円余という形の金額になっています。都民税部分で１,０００円、合わせて４,０００円というもので、広く負担いただいているものです。","id":"exchange-006"},{"speaker":"山本委員","kind":"質問・要望","question":"先日の一般質問でも要望いたしましたが、財政の見える化をさらに前に進めてほしいと考えます。ご見解を伺います。","respondent":"加島財政課長","answer":"効果等を研究しながら、必要性、有効性等を考えてまいりたいと考えております。品川区では今現在、総合実施計画で５年間の見通しを立てているところですが、今後考えてまいりたいと考えています。","id":"exchange-007"},{"speaker":"山本委員","kind":"質問・要望","question":"最後に、決算全般について伺います。令和６年度決算の、行政としての評価について伺います。","respondent":"加島財政課長","answer":"区立学校学用品の無償化、また令和６年１０月には区立児童相談所を開設したことなどが令和６年度の大きなトピックであったと考えております。","id":"exchange-008"},{"speaker":"山本委員","kind":"意見","question":"健全財政を維持しながら、様々な施策を講じていたということで理解いたしました。令和６年度、ウェルビーイング予算３８億円を捻出されて実施されたというところですけれども、この辺りについてもご評価を説明するよう求めました。","respondent":"加島財政課長","answer":"令和６年度のウェルビーイング予算というところですけれども、さらにはＬＧＢＴＱ支援のための相談体制なども始められたところです。令和６年度ウェルビーイング予算の４つの柱に基づいて取り組んできたところではありますけれども、昨年度中に実施いたしました世論調査では。","id":"exchange-009"},{"speaker":"山本委員","kind":"質問・要望","question":"特に費用対効果を意識して、さらに効果が高まるような施策のブラッシュアップを進めていただきたいと考えています。この辺りは歳出の款別審査でもそれぞれ確認させていただきたいと考えています。","respondent":"加島財政課長","answer":"目下の物価高騰や、既存施設の老朽化に伴う更新経費、区としても計画的に財源を確保いたしまして対処していかなければいけないと考えております。","id":"exchange-010"},{"speaker":"ゆきた委員","kind":"質問","question":"１４６ページの災害対策職員待機寮利用料に関連して、７８ページ、それぞれお伺いします。初めに、災害対策職員待機寮の単身寮、家族寮それぞれについて、簡単な間取りと利用料をお聞きしたいと思います。","respondent":"宮尾人事課長","answer":"それから利用料ですが、単身寮につきましては、広さ等にもよるのですが、大体平均すると３万円程度です。家族寮につきましては５万円台のものが中心ということになってあります。","id":"exchange-011"},{"speaker":"ゆきた委員","kind":"確認","question":"確認させていただきました。品川区の賃料としては、かなり安価な設定になっていると思われますが、この理由についてお聞きしたいと思います。","respondent":"宮尾人事課長","answer":"待機寮に入居できる資格といたしまして、以下のことを義務づけしております。それから各種の防災訓練への参加を義務づけているといったことを条件に入居を認めているというものです。","id":"exchange-012"},{"speaker":"ゆきた委員","kind":"確認","question":"品川区では、災害対策待機寮が９棟９８戸あり、それ以外でも借り上げが３６戸あると確認しています。以前の確認では、現在９７人の職員が災害対策要員として区内で居住しています。","respondent":"星災害対策担当課長","answer":"私からは、一定規模の火災時に災害対策職員の待機寮生を参集するというお話についてのお答えをします。なお、延焼火災に対する品川区の支援につきましては、延焼中の情報を消防署から入手し、速やかに防災課職員が参集を行い、実施しているところです。","id":"exchange-013"},{"speaker":"ゆきた委員","kind":"質問","question":"すみません。私が聞き逃したのかもしれないのですけれども、過去の実績、災害対策職員の風水害も含めて、全ての実績について説明を求めました。","respondent":"宮尾人事課長","answer":"令和６年度の実績といたしまして、令和６年度は震度５弱以上の地震が発生していないこともありますので、風水害の対応といたしまして９件、延べ７７名の待機寮生が従事したという実績があります。","id":"exchange-014"},{"speaker":"ゆきた委員","kind":"質問","question":"すみません。これまでの過去の実績を説明するよう求めました。","respondent":"宮尾人事課長","answer":"今お答えした実績が、令和６年度１年間の実績ということでお答えさせていただきました。","id":"exchange-015"},{"speaker":"ゆきた委員","kind":"意見","question":"夜間・休日の火災での参集について迅速に行い、被災された区民への支援を早急に進めていくべきであると訴えさせていただきました。火災現場での迅速な支援、そして災害対策要員のスキルアップのために、こちらについて区の見解をお聞かせほしいと求めました。","respondent":"星災害対策担当課長","answer":"先ほどの答弁と一部重なりますけれども、災害対策職員の待機寮生は現在、災害対策本部室が開設される災害に対して対応いただいているところです。それ以外の通常の延焼火災に対しましては、品川区の防災課職員が参集を行い、支援しているところになります。","id":"exchange-016"},{"speaker":"ゆきた委員","kind":"質問","question":"火災発生時の従前居住者用住宅への受入れについてお聞きしたいと思います。従前居住者用住宅の利用料についてお聞きできればと思います。","respondent":"小川木密整備推進課長","answer":"利用料ですが、従前居住者用の家賃に関しましては、収入の金額に合わせまして設定しています。一番安価なところでは３万５,０００円から、一番高いところで１２万２,０００円というような形での設定となっています。","id":"exchange-017"},{"speaker":"ゆきた委員","kind":"質問","question":"現在の従前居住者用住宅、ソレイユ戸越は、火災被災者が居住する常設のお部屋が確保されているところになっていると思われますが、こちらのランニングコストについてお聞きできればと思います。","respondent":"小川木密整備推進課長","answer":"ソレイユ戸越のランニングコストですけれども、こちらに関しましては、維持管理、清掃等といったものにコストがかかってあります。金額については、今、手元にございませんので、そういった委託関係でコストがかかっているといったところでのご説明となります。","id":"exchange-018"},{"speaker":"安藤委員","kind":"質問・要望","question":"１３３ページ、不燃化特区支援事業、１００ページ、社会資本整備総合交付金、時間があれば７８ページ、従前居住者住宅使用料について伺います。来年度以降も支援が受けられるように、制度の延長を都に働きかけてほしいと求めましたが、いかがか尋ねました。","respondent":"小川木密整備推進課長","answer":"こちらが７０％を超えますと、火災による延焼の焼失率がほぼゼロになるといった効果が見込まれるといったものです。実施地区や助成支援内容は、検討を行っておりまして、東京都としっかり検討してまいりたいと考えています。","id":"exchange-019"},{"speaker":"安藤委員","kind":"質問・要望","question":"改めて、特定整備路線の放射２号線・補助２９号線の事業費はそれぞれ幾らか教えてください。そして、最新の土地取得率も伺います。","respondent":"高梨都市計画課長","answer":"補助２９号線につきましては路線ごとに分かれておりまして、全ての路線を足しますと、約５９２億円余というような数字になってあります。用地取得率についてですが、補助２９号線につきましては区間ごとに異なってございまして、３２％から６７％という状況になってあります。","id":"exchange-020"},{"speaker":"安藤委員","kind":"質問","question":"併せてなのですが、道路の予定地内での現在の不燃領域率というのがどうなっているのか、お分かりでしょうか。伺いたいと思います。","respondent":"小川木密整備推進課長、高梨都市計画課長","answer":"不燃化特区として位置づけられております３地区の不燃領域率についてお答えします。補助２９号線沿道が５３.５％、放射２号線沿道が７０.９％、補助２８号線沿道が７３.７％という形になってあります。 特定整備路線の道路の区域内における不燃領域率についてですが、そちらについては東京都から情報を得ているものではございませんし、区としても算出してございません。","id":"exchange-021"},{"speaker":"安藤委員","kind":"質問","question":"地域住民ですので、そうした方々も対象に意見交換を行うべきかと思いますが、やっていただけるのでしょうか。伺いたいと思います。","respondent":"大石まちづくり立体化担当課長","answer":"地域との意見交換という点ですけれども、現在、地域の意見交換につきまして、誰とやるかというところはまだ検討中ですが、基本的には町会やまちづくり団体等、まちづくりに関する方としっかりと意見交換をしていきたいと考えているところです。","id":"exchange-022"},{"speaker":"安藤委員","kind":"質問","question":"伺いたいのですが、品川区の今のご答弁ですと、再開発を進めたいという住民以外とは対話しませんということなのでしょうか。伺いたいと思います。","respondent":"大石まちづくり立体化担当課長","answer":"地域との意見交換につきましては、準備組合だけではなく、準備組合に加入されていない方も含めまして、現在、検討しているという状況です。","id":"exchange-023"},{"speaker":"安藤委員","kind":"質問・要望","question":"区が同意率の判断とする仮同意書の提出について伺いますと、仮同意書を出した方は８１％でした。１月下旬、都市計画案そのものを見直すべきだと思いますけれども、いかがか尋ねました。","respondent":"中道都市開発課長","answer":"現在、大崎東口第４地区では都市計画手続を進めている状況でございまして、これは当初の予定どおり進められている計画です。区の総合実施計画にも、令和７年度に都市計画決定を行うという計画となっているです。","id":"exchange-024"},{"speaker":"安藤委員","kind":"質問・要望","question":"区は、最終的に責任を持つべきだと思いますけれども、いかがでしょうか。従前居住者用住宅に入れるようにする、または専用のそうした住宅を整備することが必要だと私は思いますけれども、いかがか尋ねました。","respondent":"中道都市開発課長","answer":"ですので、こういった個人に対しまして寄り添った対応を行っていくということが非常に寄り添った対応と考えています。区といたしましては、こういった様々な声に対しまして丁寧な対応を行うよう、組合に指導してまいります。","id":"exchange-025"},{"speaker":"せらく委員","kind":"質問","question":"一般質問で地域センターの自習室開放について伺いましたところ、会議室に空きが少なく、実際に開放できる会議室が少ないことが課題とされていました。稼働率が高い地域センターと一番低い地域センターの２か所で、当日の実利用率を、令和６年度の実績を説明するよう求めました。","respondent":"平原地域活動課長","answer":"それに事由があって還付したというようなところですと、調定件数１万７,３０６件に対しまして、還付というところは５７４件。これが、事実上のキャンセルに相当するようなものと考えているところです。","id":"exchange-026"},{"speaker":"せらく委員","kind":"確認","question":"直前のキャンセルによってほかの利用者が使えなくなる、いわゆる機会の損失について、区はどのように把握・評価しているのかを確認したいと思います。キャンセル枠というのは、再利用ができる仕組みがあるのか伺います。","respondent":"平原地域活動課長","answer":"ですので、使用されないという形になりましたら、そういったところであらかじめ余裕を持ってキャンセルされるものと考えています。システム上、空きという形になりますので、例えば極端に言いますと当日の受付といったものに対応できるようになってあります。","id":"exchange-027"},{"speaker":"せらく委員","kind":"確認","question":"三回と続くような団体に対しては、声を伺ったり、活動状況を確認することも必要ではないでしょうか。単に料金の徴収で終えるのではなく、実際に区民が利用できる環境を整えることが重要だと考えますが、区のご見解を伺います。","respondent":"平原地域活動課長","answer":"今現状は、一定期間が終了した段階で自動キャンセルという形で、またそういったところで繰り返し仮予約することも可能な状況になってあります。どのような対応がいいのかというのは、平等な形で使えるような検討というものはこちらでも進めてまいりたいと考えています。","id":"exchange-028"},{"speaker":"せらく委員","kind":"質問・要望","question":"そのときいろいろ質問ができなかったのは私の反省点ではあるのですけれども、せっかくやった事業ですので、今後していただきたいと考えています。様々な年代への広報戦略について、どうお考えか、方針を伺いたいと思います。","respondent":"上野子ども育成課長","answer":"今、ＹｏｕＴｕｂｅ等で子ども向けに児童センターの魅力を発信しています。今後も、様々なニーズ等を確認しながら、広報については検討してまいります。","id":"exchange-029"},{"speaker":"せらく委員","kind":"質問・要望","question":"今日質問をさせていただきまして、集会所の利用実態は丁寧に把握して、空き枠の有効活用には努めてほしいと求めました。子どもたちにとって安全な居場所を提供できるように取り組んでほしいと求めましたが、見解を伺います。","respondent":"平原地域活動課長","answer":"全て合わせますと１４か所で６６部屋ありますけれども、そういったところについては、お声がけさせていただいているところです。区民集会所の活用なども、様々検討させていただきまして、そういった居場所のさらなる確保というものをしっかり考えてまいりたいと考えています。","id":"exchange-030"},{"speaker":"横山委員","kind":"提案","question":"１点目に、デジタル基盤改革支援補助金に関連しまして、区のＤＸの取組についてお伺いいたします。庁内での提案や実践を可視化し、その他の職員の方々にも提案していく仕組みにしていただきたいと考えますが、区のお考えを説明するよう求めました。","respondent":"西澤ＤＸ戦略担当課長","answer":"この内容を基に改善計画を策定して実施していく予定になっております。庁内における連携・共有については、成功事例の共有と横展開を図って、特に優れたグループには表彰もしていく予定になっております。","id":"exchange-031"},{"speaker":"横山委員","kind":"確認","question":"令和７年前期の監査報告書では、その背景には、マニュアル確認不足やチェック体制の形骸化があると言及されています。例えば、一定金額以上の処理では自動的に複数人の確認が必須になるような承認フローの設定や、現在のお考えを説明するよう求めました。","respondent":"西澤ＤＸ戦略担当課長","answer":"最後に、こちらはＡＩを使ったりといったところも今後検討が必要かと思っていますし、ＡＩエージェントの適用なども効果的と考えております。ただ、実証実験や民間企業との連携といったところも視野に入れながら検証していきたいと考えております。","id":"exchange-032"},{"speaker":"横山委員","kind":"提案","question":"２点目に、ふるさと納税寄附金についてお伺いいたします。今後も制度の趣旨に沿った建設的な提案をお願いしたいのですが、取り組んでいくのか、ご見解をお伺いいたしますとの意見を述べました。","respondent":"宮澤税務課長","answer":"ふるさと納税制度に対する国への要望活動です。他の自治体と連携した要望活動を、実施時期・内容についてはまだ詳細は未定のところですけれども、実施していく予定です。","id":"exchange-033"},{"speaker":"横山委員","kind":"質問・要望","question":"ぜひ引き続き積極的に、様々な団体や、ほかの都市部との連携も含めて進めてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-034"},{"speaker":"おぎの委員","kind":"確認","question":"は１０３ページ、国庫支出金、再開発事業から、近年高騰するマンション価格と区民の安定した居住に関してお伺いします。は品川区の現状を確認したいと思います。","respondent":"中道都市開発課長","answer":"市街地再開発事業において、組合等の事業協力者でありますデベロッパー等のヒアリングを実施しているという状況です。そうした中で、または一般的に建設するマンションにつきましても、マンションの価格は高騰しているということは聞いております。","id":"exchange-035"},{"speaker":"おぎの委員","kind":"質問","question":"品川区でもそういった調査ができるのかと思いますが、調査に関してはいかがでしょうか。こういったものを品川区ですぐに活用できるのか、また品川区として考えている何か手だてがあれば示すよう求めました。","respondent":"中道都市開発課長、川原住宅課長","answer":"千代田区での投機目的でのマンション取引に関する要請、また、そこに対する取組というものについては、区も認識しております。そうした動きを踏まえまして、マンション取引を含む不動産市場の動きについて… 現在、選定しているところかと思います。子育て世帯がより住みやすくなるまちになるために、子育て世帯を中心とした住まいの施策の在り方というところも検討してまいりたいと考えています。","id":"exchange-036"},{"speaker":"おぎの委員","kind":"質問・要望","question":"令和７年度の国会議員政策担当秘書資格試験の筆頭問題にもこちらは出題されており、それに取るべき政策提言といったものを問うものでした。国政での審議を注視しつつ、品川区の健全な成長と品川区民の安定した生活をしっかりと支えていただきたいと強く要望して、次の質問に移ります。","respondent":"今井八潮まちづくり担当課長","answer":"具体的に申し上げますと、次いで鏡張りのダンススタジオとなっております第二地域交流室が７５.９％といったような状況です。講習室やパソコン室などといった、用途がある程度限定的になるようなお部屋でございまして、いずれも４０％程度という状況になっております。","id":"exchange-037"},{"speaker":"おぎの委員","kind":"質問","question":"今回、「しながわシティラボ」の実証実験型プロジェクトとして採択されました垂直水耕栽培施設についてお伺いします。ということですが、こちらの施設の今後の展開を説明するよう求めました。","respondent":"今井八潮まちづくり担当課長","answer":"設置いたしました垂直水耕栽培装置ですけれども、今回実施させていただきましたような収穫体験会などを通じまして、地域住民同士の新たな交流の場を創出していきたいと考えているところです。","id":"exchange-038"},{"speaker":"おぎの委員","kind":"質問","question":"１８歳の壁が問題となっている障害者の就労支援にも向いているのではないかと思いますが、そういった展開の活用はいかがでしょうか。説明を求めました。","respondent":"今井八潮まちづくり担当課長","answer":"１点目については、ほかの自治体でも様々な好事例があるということは所管としても認識しています。今回、八潮地区内で就労支援事業を実施していただいております品川総合福祉センターの理事長以下職員の方、事業者とも協議を進めているところです。","id":"exchange-039"},{"speaker":"おぎの委員","kind":"意見","question":"福祉分野の展開など、様々な展開がこの先まだ未知数ですが、私も八潮に行くたびに見に行こうと思います。どうぞとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-040"},{"speaker":"新妻委員","kind":"確認","question":"私からは、１５５ページ、歩行喫煙防止過料について、１６７ページ、粗大ごみからのリユース品売却についてお伺いいたします。委託料は１,０００万円でよろしいか尋ねました。","respondent":"篠田品川区清掃事務所長","answer":"売上金額ですけれども、今年度につきましては、８月末現在で１７万４,０００円となっています。委託料につきましては１,０００万円ということで間違いございません。","id":"exchange-041"},{"speaker":"新妻委員","kind":"質問","question":"一方で、ごみの減量の視点から見た場合の効果はいかがでしょうか。そして、またこの数について区の評価をお伺いします。","respondent":"篠田品川区清掃事務所長","answer":"ごみとして処理されるものが、区民の皆様方に改めてリユースされるということで、ごみの減量につながっているものと認識しています。先ほど売上げ等のお話がございましたとおり、そういった点に関しましては課題があるのかなということで認識しています。","id":"exchange-042"},{"speaker":"新妻委員","kind":"質問","question":"委託料が１,０００万円、その売上げは３０万円程度ということで、それに対しては課題があるというご答弁でした。委託料が発生しないやり方、このリユースを推進していくということも必要かと思いますが、今後の区のお考えをお聞きしたいと思います。","respondent":"篠田品川区清掃事務所長","answer":"委員ご指摘のとおり、他区等ではジモティーを使っても、サイトの提供だけをしていただくような形で取り組んでいるところもあります。かなり浸透してきてありますので、効率的な運営につきまして、私どもも今後考えていく必要があるのかなと認識しています。","id":"exchange-043"},{"speaker":"新妻委員","kind":"質問・要望","question":"現状確認ですけれども、令和６年度は８万５,０００円と、決算書で確認させていただきました。令和７年度の現状、今現在までの過料の徴収の金額を伺い、今後の見通しを併せてお聞きいたします。","respondent":"澤邉生活安全担当課長","answer":"令和７年、ここにつきましては８月末の数字ですけれども、指導件数が７７１件、過料については７６件を取っております。本年７月１日に条例が改正されたということもありますので、今後この条例の趣旨の周知、それから取締りを進めてまいりたいと考えています。","id":"exchange-044"},{"speaker":"新妻委員","kind":"確認","question":"本年３月の予算特別委員会で、若林副委員長もたばこ税の質疑から、今後の喫煙に関する評価と、また喫煙所整備の考え方、取組を確認しております。時間がなくなってしまいましたので、そこの部分について改めて確認いたしますけれども、７月１日から喫煙に関する取組が強化されました。","respondent":"澤邉生活安全担当課長","answer":"警備会社の委託については、本年度から実施している事業でございまして、昼間が９６回、深夜と早朝が２４回となっております。喫煙所の整備につきましては、公用地を含めて検討していますが、なかなか難しい点もあります。","id":"exchange-045"},{"speaker":"新妻委員","kind":"提案","question":"先日９月２１日に行われた中高生リバースメンター事業のプレゼンテーションでも、与えない社会へ」と題し、問題・課題解決の提案がされておりました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-046"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"最初に、１３５ページ、災害時応急物資確保費に関連しまして、先日ありました９月の大雨対応についてお伺いさせてほしいと求めました。最初に、品川区内にある土のう置場は、私は５４か所と認識しているのですけれども、確認したいと求めました。","respondent":"森道路課長","answer":"土のう置場です。品川区内で５６か所、１万４,１５０袋を用意しています。","id":"exchange-047"},{"speaker":"高橋（伸）委員","kind":"質問","question":"私のお店も旗の台三丁目商店街に面していまして、私の店も浸水で、膝までつかって、水を掃き出すのに２時間半かかったところであります。９月１８日現在で事業所は２４８件という報告がございましたけれども、今現在どのぐらいなのか説明を求めました。","respondent":"羽鳥防災課長","answer":"事業所の被害については３２６件になってあります。住家の床上浸水は５０２件、床下浸水は２７４件という状況です。","id":"exchange-048"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"ぜひ今後、要綱で、もう少し事業所に対してのお見舞金を引き上げていただきたいというのが私の要望であります。その辺のご見解をお聞きしたいと思います。","respondent":"星災害対策担当課長","answer":"確かに水のうは非常に有効になるものだとは思っておりますので、今後、防災訓練もしくは水防の訓練といったところで、区民の皆様に周知していければと考えているところです。","id":"exchange-049"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"次に１０７ページ、移動教室経費について質問させてもらいます。教育の観点から、移動教室という意味というか意義、目的を、改めてご紹介ほしいと求めました。","respondent":"石井学務課長","answer":"有識者検討会の議論や、あと今後の方針についてもいろいろ議論されていますけれども、引き続きやっていきたい。この施設というものについては教育的な意義があると考えています。","id":"exchange-050"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"保養所事業は廃止というので私はいいと思うのですけれども、ぜひこれは教育施設として今後も利用していただきたいと、私から、要望します。その辺について、お尋ねさせてほしいと求めました。","respondent":"石井学務課長","answer":"日光という場所は、２３区はいろいろなところで、日光という場所での移動教室を実施しております。そういうところも踏まえて、これから様々な検討を含め、議論していきたいと考えております。","id":"exchange-051"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"所管課と連携して、教育という観点から、ぜひ今後もやっていただきたい、続けていきたいと思いまして、私の要望として、終わりとします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-052"},{"speaker":"澤田委員","kind":"質問・要望","question":"本日は、６５ページ、なぎさ会館についてお伺いします。令和６年度の事務事業評価で３年以内の廃止を検討となっていますが、現在もその方向性で間違いないか尋ねました。","respondent":"築山戸籍住民課長","answer":"事務事業評価では３年以内としていますが、令和８年１月に臨海斎場が式場を増設することも踏まえ、検討しています。廃止になった場合の跡地活用につきましては企画部門で進めることになりますが、行政需要や地域ニーズなどを総合的に勘案し、検討してまいります。","id":"exchange-053"},{"speaker":"澤田委員","kind":"質問・要望","question":"そこでお伺いします。臨海部広域斎場組合議会を構成する５区の区長と議長の間で、また要望などはあるのか、説明を求めました。","respondent":"築山戸籍住民課長","answer":"臨海部広域斎場組合議会からの要望を受けまして、臨海斎場では令和６年３月に、葬祭業者を通じて臨海斎場へのアクセスの実態調査を行いました。","id":"exchange-054"},{"speaker":"澤田委員","kind":"質問","question":"タクシーで向かった場合には４,０００円前後、同時に台数不足もあり、高齢者の方にとっては利用が難しいという声もお聞きしています。区として把握している区民のお声などありましたら、説明を求めました。","respondent":"築山戸籍住民課長","answer":"直接、品川区に区民の声が届いているわけではありませんが、バスの本数を増やしてほしいといった声があることを確認しております。区民委員会においてもアクセス改善についてのご要望を頂いているところです。","id":"exchange-055"},{"speaker":"澤田委員","kind":"確認","question":"先ほどの質問にも重ねてしまいましたけれども、いろいろな方面からアクセスの向上を望む声があるのだなということを確認させていただきました。ぜひ前向きにご検討ほしいと求めましたが、お考えを説明するよう求めました。","respondent":"築山戸籍住民課長","answer":"ご自宅や式場からドア・ツー・ドアで火葬場まで行けるタクシーやマイクロバス等の利用のニーズが高まっていくものと考えております。区民の葬儀費用負担軽減のための区民葬儀において、２３区共通の補助制度を検討中ですので、これらの取組を進めてまいります。","id":"exchange-056"},{"speaker":"澤田委員","kind":"質問","question":"続いて、おくやみコーナーについてお伺いします。一定期間が過ぎた今、効果検証は行われたのか尋ねました。","respondent":"築山戸籍住民課長","answer":"その中で、利用者の声といたしましては、１か所で手続が完了して楽だった。ウェブ予約がしづらいといった意見、また、予約制ではなくて当日に対応してほしいといった声を聞いているところです。","id":"exchange-057"},{"speaker":"澤田委員","kind":"質問","question":"その期限は１０日以内、国民年金は１４日以内に行わなければならないという情報を、より親切ではないのかなと思います。区としてのお考えを説明するよう求めました。","respondent":"築山戸籍住民課長","answer":"相談に乗りながら丁寧に対応はしていますが、委員のご指摘の点について区民に周知できるよう、改めて確認してまいります。予約につきましても、改善に向けた検討もしてまいりたいと思います。","id":"exchange-058"},{"speaker":"澤田委員","kind":"質問・要望","question":"書類のみでの申請となっていますけれども、他自治体では死亡届の原本の提出以外は、マイナンバーを活用するなどして電子申請が可能となっています。品川区でも手続の利便性向上のために、ぜひ電子申請、ＤＸ化をさらに進めていただきたいと要望いたしますが、ご見解を説明するよう求めました。","respondent":"山下国保医療年金課長","answer":"本年３月より電子申請サービスでの受付を開始しておりまして、取扱いをしていますが、まだ電子申請サービスの受付ができていない状況があります。利便性の向上という観点から、そちらの電子化についても、引き続き取組を進めてまいりたいと考えています。","id":"exchange-059"},{"speaker":"中塚委員","kind":"質問・要望","question":"６４ページから始まる使用料及び手数料について、区民プールのロッカー代と子どもの料金の無償化を求めて質問いたします。受益者負担の考えに変更があったのか、伺います。","respondent":"大友公園課長","answer":"ロッカー代の返却につきましては、様々なご意見やご要望を踏まえまして、ロッカー代を返却式にする検討をしてきたところです。利用者の利便性向上を図るために、プール営業開始前の設備点検に合わせて、返却式に変更したところです。","id":"exchange-060"},{"speaker":"中塚委員","kind":"質問","question":"利便性の向上ということですけれども、２つ目に受益者負担の考えに変更があったのかと伺いました。改めて答えるよう求めました。","respondent":"大友公園課長","answer":"１０円の徴取というところについては、運用面のところで徴収していたところですので、受益者負担の考えに変更があったというところではございません。","id":"exchange-061"},{"speaker":"中塚委員","kind":"質問・要望","question":"そこで今回の依命通達ですが、従来の受益者負担を見直すものなのか、伺います。改めて区民プールの子ども料金を無料にすべきと思いますが、いかがか尋ねました。","respondent":"崎村企画課長、大友公園課長","answer":"そういった観点から、施設を利用することによって益がある人と、利用しない人との負担の公平性を確保するというのが大前提の考え方であります。こういった状況を踏まえて… 利用者も限られる施設でありますので、受益者負担の考えの下、ご負担いただいているところです。この受益者負担の考えから、料金を無料にするという考えは、現在のところございません。","id":"exchange-062"},{"speaker":"中塚委員","kind":"質問","question":"保育園やすまいるスクールは無償化を進めてきましたが、なぜ区民プールだと、同じ子どもでも料金を取るのか。ならば私は、同じ子どもなのだから、区民プールも少なくとも子どもから取るのはやめようと判断すべきだと思いますけれども、いかがか尋ねました。","respondent":"大友公園課長","answer":"利用用途を限定し、また利用者も限られる施設ではありますので、受益者負担の考えが基本となっているところです。無用の予約を防止することで、より多くの方の利用を図るといった運用面からも、利用料金を頂いているところです。","id":"exchange-063"},{"speaker":"中塚委員","kind":"質問","question":"伺いたいのは、区民プールは同じ子どもでも、なぜお金を取るのか。改めて伺います。","respondent":"大友公園課長","answer":"先ほども申しましたとおり、受益者負担の考えが基本となるというところではありますけれども、さらにより多くの利用を図るということで、無用の予約を防止するという目的もあって、こちらは利用料金の徴収をしているというところになってあります。","id":"exchange-064"},{"speaker":"中塚委員","kind":"質問・要望","question":"１８歳選挙権の議論ですので、やはり小学校・中学校・高校生までを子ども料金とすべきだと思いますけれども、いかがでしょうか。これはプールだけでなく、品川区の施設全体にも関わりますけれども、ぜひこれを機にご検討ほしいと求めましたが、いかがか尋ねました。","respondent":"大友公園課長","answer":"その結果、高校生は大人料金とさせていただいておりまして、中学生と小学生、それぞれ料金を設定しています。区民プール以外の各施設について、それぞれの施設ごとの考えもあるですので、一律で変更するということは難しいのではないかと考えております。","id":"exchange-065"},{"speaker":"松永委員","kind":"質問","question":"こうした方へ、どういった方法で対応されているのでしょうか。その外国人に対して、もしいらっしゃったら、どういった形で対応されているのか、伺いたいと思います。","respondent":"澤邉生活安全担当課長","answer":"今、過料についてのご質問がありましたので、回答します。基本的にはチラシを持っておりますので、それをお示しして、品川区の条例が改正した旨についてご説明します。","id":"exchange-066"},{"speaker":"松永委員","kind":"提案","question":"ご提案なのですけれども、伺ったことがあるのですけれども、こうしたご提案をしています。クラウドファンディングで喫煙所の設置というのは可能かどうか、これはふるさと納税として扱えるのかどうか、確認させてくださいとの意見を述べました。","respondent":"澤邉生活安全担当課長、宮澤税務課長","answer":"喫煙所の設置につきましては、先般も答弁させていただきましたが、公用地を中心に配備してきました。補助事業を充てまして、鋭意、設置を図っているところです。具体的に言えば、区内で製造、作られているのかなどといったところになってくるところです。","id":"exchange-067"},{"speaker":"松永委員","kind":"質問","question":"１３４ページの災害対応力向上支援事業補助金について伺います。例えば、消火器やＷｉ－Ｆｉ、発電機、スタンドパイプなど、いろいろあると思うのですが、どの部類になるのか尋ねました。","respondent":"羽鳥防災課長、遠藤防災体制整備担当課長","answer":"私からは、災害対応力向上支援事業補助金のうち、防災区民組織育成費についてお答えします。内訳といたしましては、発電機が１３基、蓄電池が１１基、モバイルＷｉ－Ｆｉが１基という内容です。 私からは、災害時応急物資確保費、初期消火体制強化費についてご回答いたします。令和６年度は、消火器の購入助成が６０２本、詰め替えが９本といった内容になってあります。","id":"exchange-068"},{"speaker":"松永委員","kind":"質問・要望","question":"各総合防災訓練が今後行われると思いますので、せっかくみんな集まってこういった訓練をやるので、そうしたところで消火器についての確認をする。要望で終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-069"},{"speaker":"つる委員","kind":"質問","question":"５２ページ、特別区民税で、ミドル期シングルやベーシックサービス、それから社会的処方の関係について伺っていきたいと思います。特別区議会でしょうか、２０１３年、３５歳から６４歳の状況の変化というところを調査したことがあります。","respondent":"宮澤税務課長","answer":"令和６年度と令和７年度を比べると、若干、上にシフトしているというところがあります。４０代・５０代の納税義務者数のうち約６５％近くが単身世帯という状況という傾向にあります。","id":"exchange-070"},{"speaker":"つる委員","kind":"提案","question":"財政の学者のいろいろな書籍を確認すると、それから租税負担率については３６か国中２８位ということで、要は負担率が低いという状況なのです。議会側からも様々な提案があると思うのですが、どういう場所で、説明を求めました。","respondent":"崎村企画課長","answer":"今年度の施政方針でも申し上げましたけれども、品川区としても各種施策を実施しているところであります。１自治体として提供していくべきなのかというのは、また区民の声等をお聞きしながら、品川区としてしっかりと考えていきたいと考えております。","id":"exchange-071"},{"speaker":"つる委員","kind":"提案","question":"これまでも会派としても様々な提案をさせていただきましたけれども、しっかりとそこで、共感・納得を頂けるような施策展開をお願いしたいと思います。今、品川区はどういう形で取組を進めていらっしゃるのか、説明を求めました。","respondent":"東野福祉計画課長","answer":"このミドル期シングルの層といいますと、例えば今取り組んでおります重層的支援体制整備事業と孤独・孤立対策のプラットフォームの事業があります。こちらでは、地域の支援者が集まりまして、地域の中でどういった方々にどういった支援を届けられるか。","id":"exchange-072"},{"speaker":"つる委員","kind":"質問・要望","question":"品川区のまさに売りになっていくと思いますので、これからもそうした施策展開を、全国に先駆けてやってほしいと求めました。様々な款別質疑で伺っていきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-073"},{"speaker":"吉田委員","kind":"質問・要望","question":"私からは、９７ページのすまいるスクール運営費から伺います。それを求めるなら、それに対応する契約金額の上乗せも必要なのではないかという趣旨の質問ですので、それを踏まえてお答えほしいと求めました。","respondent":"上野子ども育成課長","answer":"吉田委員からのご質問にお答えいたします。そちらに、医療行為を除くアレルギー発症時の対応ということで記載しておりまして、こちらに記載されているものと考えております。","id":"exchange-074"},{"speaker":"吉田委員","kind":"質問","question":"それで、私の見解では、エピペンの使用は明らかに医療行為と考えるのですけれども、医療行為ではないのでしょうか。その点について説明を求めました。","respondent":"上野子ども育成課長","answer":"医療行為を除くアレルギー発症時の対応というのが、エピペンの使用に当たるかどうかというところですけれども、医療関係者のみ対応できるというものではないと考えておりますので、研修の中で、そこは対応できる範囲内と、こちらでは考えております。","id":"exchange-075"},{"speaker":"吉田委員","kind":"質問・要望","question":"私は結構、エピペンの使用まで踏み込んだものを求めるのであれば、やはり契約の中にそれを明記してやるべきなのではないかというのが見解です。それを契約相手に求めるのであれば、契約の在り方として伺っていますので、その点について説明を求めました。","respondent":"上野子ども育成課長","answer":"繰り返しになってしまうのですけれども、医療関係者のみ対応するものではないという見解の下に仕様書を作成しておりますので、こちらについては記載のとおりで問題ないと、こちらは考えているところです。","id":"exchange-076"},{"speaker":"吉田委員","kind":"質問・要望","question":"昨年の西本委員の質問に対する子ども育成課長の答弁は、契約内容を超えているのではないかと思いますが、超えていないという判断なのでしょうか。この中身にはここまで含まれておりますということを説明して契約を結ぶべきだと思うのですけれども、そうだということで確認してよろしいか尋ねました。","respondent":"上野子ども育成課長","answer":"すまいるスクール仕出し弁当昼食対応補助業務委託ですけれども、仕出し弁当の受領、保管場所の……。","id":"exchange-077"},{"speaker":"のだて委員","kind":"質問","question":"午前中の質疑で、２,２００人ですか、高所得者が増えていると。これが、どこの層が増えているのかというのも伺いたいと思います。","respondent":"加島財政課長、宮澤税務課長","answer":"令和６年度特有の歳入増の事情といたしましては、定額減税が実施された際の減収補填特例交付金２０億円が増となっております。株式等譲渡所得割交付金につきましても… 午前中、高所得の方の増加という部分ですけれども、いわゆる合計所得金額が１,０００万円以上の方です。","id":"exchange-078"},{"speaker":"のだて委員","kind":"提案","question":"その一つとして、義務教育の無償化をさらに進めるために、移動教室無償化を提案したいと思います。ぜひこの移動教室も無償化できたらと思いますが、いかがか尋ねました。","respondent":"石井学務課長","answer":"現在、移動教室の宿泊費やバスの借り上げ費用等は公費負担をしており、これは従前から実施しているものです。一部、食費負担等はありますけれども、教育に必要な部分では十分に無償化されていると考えています。","id":"exchange-079"},{"speaker":"のだて委員","kind":"質問・要望","question":"ぜひやってほしいと求めましたけれども、何か課題があるのかどうか、伺いたいと思います。この林間学園も無償化してほしいと求めましたが、いかがでしょう。","respondent":"石井学務課長","answer":"なるべく負担の大きいところで、そこから財源を振り分けていくという考えで、これまで実施してまいりました。今後、そういった施策の実施に当たっては、限られた財源をどのように適切に配分していくかといったことも考えながら進めていきたいと考えています。","id":"exchange-080"},{"speaker":"のだて委員","kind":"質問・要望","question":"この林間学園でぜひやっていただきたいと思うのですが、林間学園の意義をどのように考えているのか伺います。無償化にもぜひ踏み出していただきたいと、改めて伺いますが、いかがか尋ねました。","respondent":"石井学務課長","answer":"非常に教育的意義が高いものとは考えてありますけれども、任意であるということ、そして私費で実施している事業です。これらはきちんと検討せねばならないことであると考えています。","id":"exchange-081"},{"speaker":"のだて委員","kind":"質問・要望","question":"ぜひ今後、学校改築をしていく上で、女性の便器を増やすことを検討すべきだと思いますが、いかがでしょうか。現在のこの女性と男性の便器の数、そして比率が何対何か、伺いたい。","respondent":"荒木学校施設担当課長","answer":"平時の学校改築時におけるトイレの器具数の考え方ですが、適正な個数を確保しているという状況です。男女比は１対１としております。","id":"exchange-082"},{"speaker":"えのした委員","kind":"質問・要望","question":"１５１ページのトイレトラック購入分、１６８ページの環境政策加速化事業補助金、９９ページのヤングケアラー支援事業についてお伺いします。会派で要望し、２３区で初めて導入されたトイレトラックを歓迎しております。","respondent":"遠藤防災体制整備担当課長","answer":"委員のクラウドファンディングを実施した効果についてお答えいたします。こういったところが、事業の効果としてあるといったところです。","id":"exchange-083"},{"speaker":"えのした委員","kind":"質問","question":"財政負担も軽減されて、区民の直接の支援、そしてまた名前ですか、企業、個人名。そこで、また改めてお伺いしますが、クラウドファンディングはどのような形で実施されたのか尋ねました。","respondent":"遠藤防災体制整備担当課長","answer":"クラウドファンディングの実施方法につきましては、ふるさとチョイスといった、ふるさと納税サイトを利用いたしました。税務課で実施しているといったところと、ふるさとチョイスを選定して、こちらでふるさと納税を実施したといったところになってあります。","id":"exchange-084"},{"speaker":"えのした委員","kind":"確認","question":"ふるさとチョイスを確認して調べたところ、企画・運営するのは、周知啓発にも認知度や効果が高かったのかと考えています。今後の展開についてはいかがか尋ねました。","respondent":"遠藤防災体制整備担当課長","answer":"防災力強化に向けた発信を行っていくといったところで、区民の関心を引くために、いろいろ機会を捉えて実施していきたいと考えております。今後、より使いやすい、災害時にもスムーズに運用できるようなことを改善してまいりたいと考えております。","id":"exchange-085"},{"speaker":"えのした委員","kind":"確認","question":"１７件の派遣。実際に被災した際にはトイレトラックを使用していただくわけですから、ぜひ区民の方にも、区のご見解をお伺いいたします。","respondent":"遠藤防災体制整備担当課長","answer":"防災訓練でのトイレトラックの活用といったところで、トイレトラック自体は、すぐにトイレとして使えるといったものになってあります。訓練の際には、比較的広い場所で展開するといったところで、訓練を通じて皆様方に周知していくことを考えているところです。","id":"exchange-086"},{"speaker":"えのした委員","kind":"提案","question":"ご提案で、これを活用した際の清掃費について質問したところでありますけれども、この課題を解決できるように要望します。令和６年度に、環境教育に関する講座やイベント等の取組を実施されていれば説明を求めました。","respondent":"中西環境課長","answer":"それから８回ほどのアウトリーチ講座、３回の大型イベント、８回の企画展示などを実施したところです。アウトリーチ講座といいまして、また環境について少し学ぶ場を設けていただくなどといったことができるように、積極的に取り組んでいるところです。","id":"exchange-087"},{"speaker":"えのした委員","kind":"確認","question":"年間７６回、環境講座をおこなっていると、確認ができました。初回から伺っており、今年も４月に開催された「エコルフェス－ＳＰＲＩＮＧ－」では、地域に根差した行事に育っていると実感しております。","respondent":"中西環境課長","answer":"グリーンカーボンにつきましては、間伐材でチャームをつくるワークショップや、品川区商店街連合会と連携した間伐材ツアーなども実施しています。引き続き、ブルーカーボンなどに関連する環境講座に関しても、積極的に進めてまいりたいと考えています。","id":"exchange-088"},{"speaker":"えのした委員","kind":"質問・要望","question":"ブルーカーボン、グリーンカーボン等に関する取組を評価して、今後、拡充も要望いたします。ゼロカーボンポイント等の取組も、区民の方への啓発や理解に有効だと考えますが、区のご見解をお伺いします。","respondent":"中西環境課長","answer":"はクリーニング店にプラスチック製のハンガーをお返しすることでポイントがつくといった取組も様々あるといったことを確認しています。","id":"exchange-089"},{"speaker":"えのした委員","kind":"意見","question":"次世代の担い手として、子どもや家庭に対する環境教育、豊かな自然を引き継ぐための取組は重要だと考えます。今後も社会全体として、さらなる周知啓発も含め、ゼロカーボン達成に向けた取組を進めていただけるようお願いいたしますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-090"},{"speaker":"やなぎさわ委員","kind":"提案","question":"ちょうど１年前の１０月の決算特別委員会で、事実婚の方と同じように、表記を夫・妻（未届）としてみてはどうかという提案をさせていただきました。","respondent":"築山戸籍住民課長","answer":"こちらにつきましてはシステムが標準化されておりまして、アナログでの対応となることが理由です。運用を開始するに当たりまして、こういった課題があるということを事前にご説明させていただきまして、運用することといたしました。","id":"exchange-091"},{"speaker":"やなぎさわ委員","kind":"質問","question":"というところで、これは本来であれば、国が全国一律の制度として取り扱うべきだと個人的に思うのです。国に区長も１２月に申入れをしたということですが、その後の国の動きというのはどのように把握されていますか尋ねました。","respondent":"築山戸籍住民課長","answer":"国からの反応は、今のところございません。","id":"exchange-092"},{"speaker":"やなぎさわ委員","kind":"質問・要望","question":"これは要望で終わります。介護職員、ケアマネジャーを合わせて４.４億円ぐらいの予算かと承知しておりますけれども、この手当の執行率はいかがか尋ねました。","respondent":"菅野高齢者福祉課長","answer":"介護職員の居住支援手当についてのご質問にお答えします。予算に対しての執行率は４１.５％ということになります。","id":"exchange-093"},{"speaker":"やなぎさわ委員","kind":"質問","question":"これはつまり、大体３,１５０人ぐらいを人数として見積もっているのですけれども、そのうちの、全体１,２００人ぐらいしか受け取れていないです。この原因というのはどのように分析されていますか尋ねました。","respondent":"菅野高齢者福祉課長","answer":"実際の支援人数につきましては１,６０２人で、３,７２０人を見込んでいたので、その約７割の方という人数となっております。法人の中で、支給が年度末になってしまったというところで、一時的に手当の立替えが資金面で厳しいなどといった声が聞かれております。","id":"exchange-094"},{"speaker":"やなぎさわ委員","kind":"提案","question":"まだ１年目ということで、下に合わせて取らないという、これは非常に残念な事態が起きていると。個人的な私の提案としては、ケアマネジャーに対して手当が行き渡るようにと思うのですが、そういったご検討はいかがか尋ねました。","respondent":"菅野高齢者福祉課長","answer":"５月に受付を開始しまして、７月から順次交付ということで、早めに交付させていただいているなどの対応をしています。個人申請につきましては、事業者にとって人材の確保・定着に当たってどのような効果があるかということを、引き続き検証していきたいと考えています。","id":"exchange-095"},{"speaker":"やなぎさわ委員","kind":"質問・要望","question":"そして、それと併せてやはり、この問題、介護職員の給料が低いというのは、もう国の問題に帰結すると思います。会議体、国に対して介護事業所の報酬引上げを求めていっていただきたいと思うのですけれども、その点について最後にご意見があればお願いします。","respondent":"菅野高齢者福祉課長","answer":"介護報酬の引上げ等につきましては、国の動向を注視しながら、実態に合うように適正な介護報酬を望んでいきたいと思います。","id":"exchange-096"},{"speaker":"大倉委員","kind":"質問・要望","question":"１３５ページの災害時応急物資確保費、関連して、先ほどもありましたが、雨の対応と、１０７ページの学校ＩＣＴ活用経費で伺えればと思います。品川区の中でも事業所が困っているなら助けたいというお声が結構ありましたので、その辺をしっかり進めていければいいのかなと思って質問します。","respondent":"石井学務課長、羽鳥防災課長、豊嶋生活福祉課長","answer":"私より、学校ＩＣＴに関するご質問にご回答いたします。１人１台端末が来年度全部更改することに合わせまして、接続方式を変更することにより… こちらは、今回の大雨対応を踏まえまして、様々、教訓を踏まえて見直しを図っていこうと考えています。見舞金につきましても、中身をもう一度精査して… 今回の９月の大雨につきまして、社会福祉協議会と協力しながら、災害ボランティアの方を集めていただきました。","id":"exchange-097"},{"speaker":"大倉委員","kind":"質問・要望","question":"それで、あればぜひリースの期間も含めて対応を考えてほしいと求めましたが、いかがでしょうか。ぜひこういった災害時の対応を募っていくというのは一定できるのではないかと考えていますので、その見解について伺いたいと思います。","respondent":"石井学務課長、豊嶋生活福祉課長、藤村総務課長","answer":"令和２年３月に導入して、これを５年契約という形で、今進めてきたところです。我々のところには、電池が切れるから困る… 社会福祉協議会との災害ボランティアの説明をします。引き続き、事前のボランティアへの周知等々を含めても、情報を詰めていきたいと考えています。 そういった目的を持って何かできることがないかというところは、今後の状況を見て、１つの検討事項とできるのではないかと考えています。","id":"exchange-098"},{"speaker":"大倉委員","kind":"質問・要望","question":"利用が多いところは、そういった活用がしにくく、事業のさらなる充実のところでハードルになったりしないようにしていただきたいというところ。こういったことを進めていくと、品川区にさらに愛着が湧くのかなと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-099"},{"speaker":"須貝委員","kind":"質問","question":"スクラップ・アンド・ビルドをして、そういう予算を捻出しているということをおっしゃっておりましたが、今回はどうなのでしょうか。説明を求めました。","respondent":"加島財政課長","answer":"令和６年度中に実施いたしました世論調査の中で調べましたところ、８割以上の方が実感しているというお答えがあったことを申し上げたところです。その中で一層、今度は令和８年度のウェルビーイング予算３.０の財源につなげていきたいと考えているところです。","id":"exchange-100"},{"speaker":"須貝委員","kind":"質問","question":"そうすると、１００億円から１２０億円のお金は捻出されていると思うのですが、私の今言っていることは違いますか。説明を求めました。","respondent":"加島財政課長","answer":"財政調整基金に５.６億円ほど、そちらにつきましては、また令和８年度に発生いたします退職金の発生に備えて積立てを行ったものです。私どもとしては、この基金の積立ては、将来需要に備えた必要な積立てだと考えております。","id":"exchange-101"},{"speaker":"須貝委員","kind":"質問","question":"そういうことを考えたら、こういう方たちに対してもっと支援、目を向けるということは、やはり区として大事ではないですか。それについてご見解を説明するよう求めました。","respondent":"加島財政課長","answer":"令和７年度５月の補正予算では、高齢者の方のお手元に飲料水をお届けするということで補正予算を提案し、ご議決いただいたところです。決して目の前で困っている方々を無視しているというわけではございません。","id":"exchange-102"},{"speaker":"須貝委員","kind":"質問・要望","question":"そこで、今、品川区はどうですか。なぜか尋ねました。","respondent":"加島財政課長","answer":"家具転倒防止設置助成などを所得制限なく無償化、そのほかにも様々な施策に取り組んでいるところです。そういうところにきちんとアクセスできるように区としては施策を展開してまいります。","id":"exchange-103"},{"speaker":"塚本委員","kind":"質問","question":"１４ページから１９ページの一般会計、１０３ページの道路維持管理費、これは下水道のことについても関連して質問したいと思います。実施する側、現状についてと、今後どのように取り組んでいくおつもりがあるかというところについてお聞きします。","respondent":"今井選挙管理委員会事務局長","answer":"投票支援につきましては、例えば代理投票などにつきましても、東京都のマニュアルに従ってご説明しております。指定施設の説明会は必ず毎回の選挙でやっておりますので、今後とも丁寧に対応していきたいと考えています。","id":"exchange-104"},{"speaker":"塚本委員","kind":"質問","question":"令和６年度は、当初の予算に比して大変、歳入が増えました。５０年以上の老朽化している下水道が５０％を超えている、やはり念頭にあるべきなのではないかと思いますけれども、ご見解をお伺いしたいと思います。","respondent":"加島財政課長","answer":"私どもといたしましても、この課題を放置する気はございませんで、今、他区の財政シミュレーション等、調査研究を行っているところです。","id":"exchange-105"},{"speaker":"塚本委員","kind":"質問・要望","question":"この調査の詳細を見ると、２３区は調査対象となった下水管の距離が、区部で１８キロですか。それぞれ２００メートル、１,１００メートルと出ていますが、品川区の対象はどのようになっているのか教えてほしいと求めました。","respondent":"関根河川下水道課長","answer":"その結果ですが、原則１年以内に対応を実施する緊急度１が２区間、５年以内に対策を実施する緊急度２が６区間あると聞いております。なお、いずれも確認された損傷は軽微で局所的であり、今後、状態に応じた対策を実施するとのことです。","id":"exchange-106"},{"speaker":"塚本委員","kind":"質問・要望","question":"緊急の、本当にすぐさま対応していくことが求められると思いますけれども、いわゆる品川区内に耐用年数５０年を超えた下水道管がたくさんある。警戒道路など、今後の区としての下水道の維持管理をどのように進めていこうと思っていらっしゃるのか、現時点で頂ける答弁をお願いしたいと思います。","respondent":"森道路課長","answer":"今おっしゃられた緊急輸送道路は大変重要な動線ですので、一刻も早い改善が望まれると考えています。区としても空洞調査を行っておりますので、そういった結果も下水道局と共有しながら、しっかりと対策を進めていきたいと考えております。","id":"exchange-107"},{"speaker":"西本委員","kind":"確認","question":"医療行為ではなくていいのですか。仕出し弁当を含めて、いろいろ職員の方々に外部委託されたと思うのですが、研修をしっかりとされたのか尋ねました。","respondent":"上野子ども育成課長","answer":"委員のご質問のアレルギー対応のところですけれども、エピペンは医療行為ではないと考えております。それから研修についてですけれども、こちらから指導員、それから委託業者にも、併せて研修は実施しております。","id":"exchange-108"},{"speaker":"西本委員","kind":"質問","question":"私が調べるのを間違ったのでしょうか。それをきちんとやったのか尋ねました。","respondent":"上野子ども育成課長","answer":"委員のご指摘の研修ですけれども、研修については区としてきちんと対応しております。","id":"exchange-109"},{"speaker":"西本委員","kind":"質問・要望","question":"経常収支比率は７８.１％ということで、おおむね７０％台行っているということで、先ほどもいろいろと質問がありました。本当に困っていることにこそ使っていただきたいと、非常に私は思いますが、その使い方について、どうお考えになりますか。","respondent":"上野子ども育成課長、加島財政課長","answer":"先ほどご質問いただきました仕出し弁当の対応補助業務委託、それについてはアレルギー対応等の想定はしておりません。それから、先ほどのアレルギー対応の研修ですけれども、研修を実施して… 本当に困っている人にどう対応していくかというところにつきましては、令和７年度の予算の結果であり、本日以降ご審査いただくものになります。","id":"exchange-110"},{"speaker":"西本委員","kind":"質問・要望","question":"次に、私立保育園についてですけれども、今、私立保育園は６５か所ぐらいあるのですか。ですから正直、少子化である現在、閉園する現状もあるし、それにもかかわらず、まだ新設するというのもあるのです。","respondent":"芝野保育入園調整課長","answer":"私立保育園の新設に関するご質問ということでお答えいたします。在籍率が今９０％近くということで、今、求められていると思います。","id":"exchange-111"},{"speaker":"西本委員","kind":"質問","question":"いろいろな行政ニーズに対して対応できるようなことも、そろそろ考えていかないと、なくなってしまう。有効活用できる、協力していただくというような仕組みをつくれないかなと思うのですが、いかがか尋ねました。","respondent":"芝野保育入園調整課長","answer":"私立保育園に対する支援や、園の運営の厳しい状況というのは認識しておりますので、しっかり支援をしていきたいと考えております。その事業者のいろいろな思いや考えなどがありますので、お声は伺いながら、研究してまいりたいと思います。","id":"exchange-112"},{"speaker":"西本委員","kind":"意見","question":"もう今、研究していくには遅いと思いますが、ぜひお願いしたいと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-113"},{"speaker":"西村委員","kind":"質問・要望","question":"先ほどから質問が出ておりますけれども、先日、９月１１日に起きた水害対応について伺ってまいりたいと思います。災害時の地域センターの役割について確認させてほしいと求めましたが、区民の方が地域センターに相談をしたというようなお声もありました。","respondent":"羽鳥防災課長","answer":"今回の９月１１日の災害におきましても、やはりいろいろな相談をする窓口として機能していただいたです。やはり、庁内に対しても分かりやすく情報を伝えるということが重要だということは再認識したところです。","id":"exchange-114"},{"speaker":"西村委員","kind":"質問・要望","question":"次に、学校の対応についても確認させてほしいと求めました。今回、特に水のたまるエリアが分かったと思いますので、今後の対応に活かしてほしいと求めましたが、ご見解を説明するよう求めました。","respondent":"丸谷教育総合支援センター長","answer":"今回の短時間の大雨の影響も踏まえ、現在、校長会と連携して対応について検討しています。雷鳴がある場合の対応や、児童・生徒の安全を第一に考え、実効性のある対応策を検討してまいります。","id":"exchange-115"},{"speaker":"西村委員","kind":"質問・要望","question":"防災課から全庁への被害状況の報告も求められたと思いますが、その結果はどのように現場や職員の皆さんに還元されたのか、伺いたいと思います。声を頂いておりますので、災害時の指揮系統や情報伝達の仕組みをもう一度見直してほしいと求めましたが、お考えを説明するよう求めました。","respondent":"羽鳥防災課長","answer":"さらに分かりやすく、情報を庁内にも伝えていくことについては、先ほども申しましたけれども、再認識したところです。先ほどご説明した被災情報管理システムは、庁外からもアクセスできる、情報が共有できるという体制を取っております。","id":"exchange-116"},{"speaker":"西村委員","kind":"質問・要望","question":"水防訓練について伺いたいのですけれども、土のうの用意が間に合わなかった、ポンプや土のうの場所が分からなかったなどという声が聞かれています。被害の大きかったエリアの掲示板に貼られていたらよかったというお声もありますので、併せてご答弁をお願いしたいと思います。","respondent":"星災害対策担当課長、羽鳥防災課長","answer":"確かに委員がおっしゃるとおり、水防の訓練というのは非常に重要だと認識しております。今回、町会、商店街、また防災協議会等々から訓練の依頼がありましたら、積極的に行っていきたいと考えているところです。ＳＮＳ等で情報はお出ししていたところですけれども、ポスターや貼り紙といった紙媒体での情報というのは、少し弱かったかなと認識しています。","id":"exchange-117"},{"speaker":"西村委員","kind":"質問","question":"最後にシミュレーションについて伺いたいのですが、災害時の様々な計画・シミュレーションをしてきていただいたと思います。計画の部分について、最後に説明を求めました。","respondent":"羽鳥防災課長","answer":"これに対する対応といたしましては、日々訓練を重ねております。そういった訓練をやることで、想定外のときにも各部が自主的に対応できたと認識しています。","id":"exchange-118"},{"speaker":"田中委員","kind":"質問・要望","question":"時間があれば、７３ページのしながわ中央公園の多目的広場についてお伺いしたいと思います。ぜひ株主としてずっと居続けてほしい、株をぜひ売却しないでいただきたいと思うのですけれども、今のお考えをお聞かせほしいと求めました。","respondent":"高梨都市計画課長","answer":"りんかい線の拠点もありますし、委員からご紹介がありました運輸事業の関係性といったところも、しっかりと注視してまいりたいと考えています。現在の関係性を今後解消しようなどといった考えについては、現在のところはございません。","id":"exchange-119"},{"speaker":"田中委員","kind":"質問・要望","question":"地元の自治体としての意見ももちろん強く言っていただきたいのですけれども、株主としての視点での意見を言っていただきたい。株主としての立場からも、ぜひしっかりと発言してほしいと求めましたが、その視点はいかがか尋ねました。","respondent":"高梨都市計画課長","answer":"ＪＲ東日本により建設が進められている羽田空港アクセス線につきましては、今現在、ＪＲ東日本により事業が進められているという認識です。今後、りんかい線との関係につきましては、しっかり、区としては注視してまいりたいと感じております。","id":"exchange-120"},{"speaker":"田中委員","kind":"質問・要望","question":"確認して、一番最短コースであったとしても、運賃の関係で利用できないという規定になっているかと思います。もっと利用者を増やしてほしいという観点の考え方もできるのではないかと思われるのですが、あるいは働き方改革の一環からしても、いかがか尋ねました。","respondent":"宮尾人事課長","answer":"通勤手当を算出するとき、最も合理的で時間の面も考慮してというところがあります。これは全庁的に考えますと、経費の増というところがありますので、ここは慎重に考えたいと思います。","id":"exchange-121"},{"speaker":"田中委員","kind":"質問・要望","question":"競馬場は、もうご案内のとおり、１９５０年に開設されていますので、今年ちょうど７５年が経過しております。品川区にとっての競馬場の存在というのは、どういう位置づけになっているのか、まずお聞かせほしいと求めました。","respondent":"藤村総務課長","answer":"歳入というところの観点で言えば、競馬組合から分配金を頂いたりといった、収入という観点のところも１つあります。やはり大井競馬場というのが１つの観光拠点ということになっておりますので、多くの方が来られるスポットになっているのではないかと考えております。","id":"exchange-122"},{"speaker":"田中委員","kind":"質問・要望","question":"そのお考えの下、また昨年ですか、連携していくという協定を結んでおります。この１号交付金は、今後は進めていくべきではないかと強く思うのですけれども、お考えをお聞かせほしいと求めました。","respondent":"藤村総務課長","answer":"今、１号交付金のお話を頂きました。この１号交付金の、こちらにつきましては全庁的に考えた上で、どういった形にしていくかを今後の検討事項としたいと思います。","id":"exchange-123"},{"speaker":"田中委員","kind":"質問・要望","question":"７３ページのしながわ中央公園の多目的広場に関してなのですが、多目的広場の一般利用ではなくて、特に学校が優先的に使用する枠ができております。具体的にどこにどう、何回ぐらい貸しているのか、お聞かせほしいと求めました。","respondent":"守屋スポーツ推進課長","answer":"私から、しながわ中央公園の多目的広場の学校の優先利用についてお答えいたします。実績につきましては手元にございませんが、主に青稜中学校・高等学校や品川翔英中学校高等学校が活用されているということで認識しております。","id":"exchange-124"},{"speaker":"田中委員","kind":"意見","question":"私はその場合こそ、地元の公立学校に優先的に使ってもらうような形に改めるべきだと思いますが、最後にすみません。説明を求めました。","respondent":"守屋スポーツ推進課長","answer":"優先というところなのですけれども、貸出しのところにつきましては、条例規則で定められた貸出し方法に伴って貸出しをしています。現状としては、そういったところの意見を頂きながら、現状の貸出し方で進めさせていただきたいと思います。","id":"exchange-125"},{"speaker":"田中委員","kind":"意見","question":"その私立学校のパンフレットに、しながわ中央公園が自らの施設かのような写真がありますので、そこは私は改めるべきだと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-126"},{"speaker":"高橋（し）委員","kind":"質問","question":"１７３ページの議会費の議員研修会について伺います。","respondent":"大澤区議会事務局長","answer":"議会として、調査の結果を請求するということであれば、議会として区長部局に請求するということになるかと存じます。","id":"exchange-127"},{"speaker":"高橋（し）委員","kind":"意見","question":"第２項では、監査委員に対しても同じように議会は、ほぼ同じ内容を請求することができます。そこで、もし今、局長がお答えしたのですが、この請求があった場合に、行政側、つまり区長は断ることが可能なのか、お尋ねしますとの意見を述べました。","respondent":"川村コンプライアンス推進担当課長","answer":"ご質問の制度について、勉強不足で申し訳ないところがありますが、請求があった場合は、制度にのっとって適切に対応してまいる必要があると考えています。","id":"exchange-128"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"ということで、第９８条で請求できるということを改めてここで確認したいと思います。今年の８月１４日の時点で、１２８団体の１４４条例が確認されます。","respondent":"大澤区議会事務局長","answer":"ほかの議会では、品川区議会においては、条例や規程がない中での懲罰というのはなかなか難しいのかなと認識しています。区議会としてそういうものが今後必要ということであれば、皆さんの中でお話しいただいて、つくっていくという選択肢もあろうかと考えています。","id":"exchange-129"},{"speaker":"高橋（し）委員","kind":"提案","question":"提案したり、この場をお借りして、お話をさせてほしいと求めました。区議会事務局のほうで資料の収集や、その条例に基づく作業等の協力をしていただきたいと思うのですが、その辺りはいかがか尋ねました。","respondent":"大澤区議会事務局長","answer":"議員の方から調査等の依頼があれば、これまでと同様に対応してまいります。","id":"exchange-130"},{"speaker":"松本委員","kind":"質問・要望","question":"ふるさと納税について１つだけ、区民の方から要望があったことなので、質疑というか要望させてほしいと求めました。品川区のオリジナルデザインを付した返礼品の区民向け販売を希望いたしますが、いかがか尋ねました。","respondent":"宮澤税務課長","answer":"現在、確かにふるさと納税でしか入手できないという状況になっております。有料頒布物として取り扱っていけるかどうかというところと、あと販売価格等々をよくよく検討した上で、検討していきたいと考えています。","id":"exchange-131"},{"speaker":"松本委員","kind":"質問・要望","question":"この点について、当区では同様の乖離が生じていないのか、念のため伺いたいと思います。当区においても一応、調査してほしいと求めましたが、いかがか尋ねました。","respondent":"宮澤税務課長","answer":"課税変更は、税のシステム自体は調定額が積み上がってきているというところで、収納管理システムと連携しています。来年１月にシステム標準化という移行等もありますので、先ほどご指摘いただいたところも含めて、適切な賦課事務、賦課徴収事務に努めてまいります。","id":"exchange-132"},{"speaker":"松本委員","kind":"意見","question":"総務省が全市区町村を対象に、２０２４年に日本を出国した外国人労働者らの個人住民税の徴収実態に関する調査を始めたとの報道が８月にありました。","respondent":"宮澤税務課長","answer":"令和６年度の外国人の滞納者の数というのが７８０人。そのうち１７７人の方が出国しているという状況です。","id":"exchange-133"},{"speaker":"松本委員","kind":"質問","question":"出国したのが１７０人程度ということで、残りの５００人から６００人の間ぐらいの方が現在、滞納なのかなというところでお伺いいたしました。きちんと数字を持ちながら、いろいろと外国人問題を考えていかなければならないというところを言わせていただきまして、今日は終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-134"},{"speaker":"鈴木委員","kind":"質問・要望","question":"８８ページの生活保護費、それから生活困窮者支援費について、生活保護世帯と低所得者世帯のエアコン設置助成を求めて質問したいと思います。私は、生活保護の世帯や低所得者世帯が、自己負担なくエアコンを設置できる助成をぜひともしてほしいと求めましたが、いかがか尋ねました。","respondent":"豊嶋生活福祉課長","answer":"２年ほど前に区で行いました、生活保護世帯のエアコンの調査で、９５％程度が設置済みということで、残り５％、２１０世帯のお話が今ございました。この間の第３回定例会でもありましたとおり、現在、スキームの検討を進めているです。","id":"exchange-135"},{"speaker":"鈴木委員","kind":"質問・要望","question":"多くの団体からも、ぜひ区としても夏季加算を国に求めていただきたいと思うのですが、いかがでしょうか。電気代補助というのもぜひつくっていただきたいと思うのですが、いかがか尋ねました。","respondent":"豊嶋生活福祉課長","answer":"国が手当てすべきところでございまして、品川区だけが特別に暑くて夏季加算をということは、やはりなかなか難しい部分でもあるかとは思います。はエアコンの設置ができるように、区としては検討を進めているところですので、エアコンの設置の助成と。","id":"exchange-136"},{"speaker":"鈴木委員","kind":"質問・要望","question":"エアコンを設置していない世帯が１３５世帯しかいないというのは今回初めて伺って、設置助成をするとしても、本当にそれほど大きくない。もともと本来、国がやるべきという夏季加算というのは、ぜひとも区としても求めてほしいと求めました。","respondent":"川原住宅課長","answer":"申し訳ございません。３０代の世帯、４０代、子育てをしていると想定される世帯数では４０世帯いるといったところです。","id":"exchange-137"},{"speaker":"鈴木委員","kind":"質問・要望","question":"家賃の大体５.５か月から６か月分ぐらいかかりまして、その上に引っ越し費用がかかるので、大きな負担になるわけです。私は、ファミリー世帯への家賃助成や転居費用の助成制度もつくってほしいと求めましたが、いかがか尋ねました。","respondent":"川原住宅課長","answer":"子育て世帯に対して、民間賃貸住宅を対象とした家賃助成や引っ越しの助成を行う予定はございませんが、現在の事業として住宅課では。委員ご指摘の家賃助成とは制度は異なるのですけれども、今後の子育て世帯の住まいの在り方というところは検討してまいりたいと思います。","id":"exchange-138"},{"speaker":"こんの委員","kind":"質問","question":"１２０ページ、１２６ページ、順不同でお聞きしたいと思います。子どもや高齢者のインフルエンザ、その中で区独自の費用助成に充当している予防接種を、まず示すよう求めました。","respondent":"五十嵐保健予防課長","answer":"ほかには任意予防接種としまして、帯状疱疹のワクチンを、５０歳以上の方に、定期接種以外の方には任意接種としてやらせていただいているところです。高齢者の方につきましては、任意接種としまして肺炎球菌ワクチンを実施させていただいているところです。","id":"exchange-139"},{"speaker":"こんの委員","kind":"意見","question":"そうではないというものもあって、何か基準や考え方の指標などがあって、こういうふうになっているのか。その辺の、いわゆる独自費用助成を実施しようとするときの検討の背景というか、そういうものがありましたらお知らせくださいとの意見を述べました。","respondent":"五十嵐保健予防課長","answer":"任意予防接種の助成につきましては、その時々の状況を鑑みながら実施させていただいているところです。はしか、風疹などにかかるとお子さんが重症化してしまうこともありますので、定期予防接種を逃した方につきましては実施しています。","id":"exchange-140"},{"speaker":"こんの委員","kind":"質問・要望","question":"乳幼児と高齢者などのＲＳウイルス感染症の重症化を防ぐために必要な予防接種の費用助成を求めてまいりました。そして今後、ＲＳウイルス感染症予防接種への区独自の助成制度の創設をいま一度求めたいわけですが、区のご見解を説明するよう求めました。","respondent":"五十嵐保健予防課長","answer":"区としましては、様々な任意予防接種について助成してまいりましたが、今まで実施してまいりました予防接種に関しましては。その中でどのような接種方法がいいのか、いつ実施するほうがいいのかというようなことが、まだ固まってきていない状況と認識しているところです。","id":"exchange-141"},{"speaker":"こんの委員","kind":"質問・要望","question":"今回またこうして要望させていただきましたが、積極的に注視していただきながら、進めていただきたいと考えています。その管理費の額と、その管理費はどのように使われているのか、その辺をまず確認したいと求めました。","respondent":"樫村高齢者地域支援課長","answer":"大井林町についての管理費の用途についてのお尋ねです。こちらにつきましては、共用部分等の管理といったものに費用を充てているところです。","id":"exchange-142"},{"speaker":"こんの委員","kind":"質問","question":"いろいろな不具合が起きたときのお部屋の中の修繕というのは、どのように行われているのでしょうか。区としても把握し対応してくださっていることを、区としてはどのように認識されているのか、お伺いしたいと思います。","respondent":"樫村高齢者地域支援課長","answer":"お住まいの部屋の専用部分について、不具合等があった場合の対応といったところです。そういったところの対応についての把握ですけれども、そちらで対応していただいているところですけれども、区にも連絡を頂いて。","id":"exchange-143"},{"speaker":"こんの委員","kind":"質問","question":"それはどういうことなのかというと、費用面でもそうです。どうか管理者の方は多分、どうなのかなというところもありますので、区としてはどのようにお考えか尋ねました。","respondent":"樫村高齢者地域支援課長","answer":"実際の入居者のそういった細かいお声などが届かない場合もありますので、適宜、入居者の方にもそういったご意見を伺える場面等をつくっていけたらいいなと考えています。","id":"exchange-144"},{"speaker":"こんの委員","kind":"質問・要望","question":"「聞いてほしいな」、ぜひその点、入居者のお声もぜひ聞いてほしいと求めました。要望で終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-145"},{"speaker":"藤原委員","kind":"質問","question":"７８ページ、区民住宅使用料、区営住宅使用料、１４６ページ、財産収入、これは国債のことについて伺います。５２ページ、特別区民税、６０ページ、特別区財政調整交付金を伺いますが、まず初めに財産収入、国債です。","respondent":"品川会計管理者、川原住宅課長、宮澤税務課長","answer":"基金の運用の際に、いろいろと国債、地方債等、購入しているのですけれども、国債についても一部、購入はしています。… 現在、区営住宅には１３世帯の外国人の世帯の方が住まれておりまして、うち単身の外国人の方は１世帯のみです。残りの１２世帯については、夫婦もしくは親… 令和６年度の住民税の収納率です。２３区で１位という状況です。","id":"exchange-146"},{"speaker":"藤原委員","kind":"質問・要望","question":"私は思いますけれども、何か今日伺っていて、税務課長が答えられる。名称も企画部長から企画経営部長になったのですから、そこはしっかりやっていただきたいと思うので、答弁いただくよう求めました。","respondent":"品川会計管理者、川原住宅課長、久保田企画経営部長","answer":"６０億円ぐらい運用していたのですが、今回新しく買ったところも、本当に短期で数十億円というところで運用しています。… 割合だと、まだと言ったらあれなのですが、３％強といったところです。日本国に１年以上在住していて、引き続き５月から住宅の総合相談窓口も開設いたしま… 品川区の収入に対して一体的に取り組んでいくといった中で、そういった観点から経営の視点も含めて組織改正をやらせていただいたというところです。","id":"exchange-147"},{"speaker":"藤原委員","kind":"質問・要望","question":"窓口での説明を伺ったのではなくて、私は、日本の方を多く入れていただきたいという思いで質問をさせていただきました。それで、何で防災課ではないのにと言ったら、「何を言っているのですか」と。","respondent":"加島財政課長","answer":"特別区の都市計画事業に対する需要は９００億円と試算しておりますので、３００億円では到底、実態に見合っていないということは認識しております。","id":"exchange-148"},{"speaker":"せお委員","kind":"提案","question":"１３９ページ、給食運営費についてお伺いします。予算案が発表された後、私たち会派で地元の複数の青果事業者と意見交換を行い、予算特別委員会で問題提起や提案をさせていただきましたとの意見を述べました。","respondent":"石井学務課長","answer":"４月から関係各所とそういった意見交換を続け、さらに６月からは、事業の具体化についてここまで取り組んでまいりました。例えば野菜の大きさなどといったものについても、実際に現物を見ながらやっていくということで、サンプル品の比較会も実施しました。","id":"exchange-149"},{"speaker":"せお委員","kind":"提案","question":"給食プロジェクトのような取組を構築していただくのも１つですし、楽しみも加わって、満足度も高まるのではないでしょうか。こちらの見解を伺いますとの意見を述べました。","respondent":"石井学務課長","answer":"区としても、例えば食育推進月間の６月に合わせて、そういった取組をこれまでもしています。これについては、教育委員会としてもしっかり考えていきたいと考えています。","id":"exchange-150"},{"speaker":"せお委員","kind":"質問・要望","question":"ですから、当初から抱き合わせで施策を打っていただいて、当初からの予算確保をお願いしたいです。こちらは企画課か財政課か、すみません、ご見解を伺います。","respondent":"加島財政課長","answer":"利用者から頂くお声から課題をつかむこともありますし、数的な実績の動きから、このような問題が生じているのかということを把握することもあります。区の政策方針との整合性が取れているか、予算化して、きちんと所管課と共に歩んでいきたいと考えています。","id":"exchange-151"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/766906?Template=document&Id=7251#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=4&TermStart=2025-01-01&TermEnd=2025-12-31"}],"sourceMeta":{"pages":0,"characters":118190,"voices":370}},{"id":"r07-20250930-10","meetingId":"r07-cm09","date":"2025年9月30日","dateIso":"2025-09-30","committee":"議会運営委員会","time":"午後 ０時４５分～午後 ０時４７分","status":"正式会議録","sourceType":"formal","overview":"議会運営委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を0件整理しています。","topics":[],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/888788?Template=document&Id=7173#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=10&TermStart=2025-01-01&TermEnd=2025-12-31"}],"sourceMeta":{"pages":0,"characters":1237,"voices":11}}]);
